static Type *scalableReduceVectorType(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return nullptr;
  ScalableReduceKind Kind;
  bool HasStart = false;
  bool IsFloat = false;
  if (!scalableReduceKindFromID(II->getIntrinsicID(), Kind, HasStart, IsFloat))
    return nullptr;
  const unsigned VecIndex = HasStart ? 1u : 0u;
  if (Call.arg_size() <= VecIndex)
    return nullptr;
  return Call.getArgOperand(VecIndex)->getType();
}

static bool isScalableReduceShape(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  ScalableReduceKind Kind;
  bool HasStart = false;
  bool IsFloat = false;
  if (!scalableReduceKindFromID(II->getIntrinsicID(), Kind, HasStart, IsFloat))
    return false;
  Type *ResultTy = Call.getType();
  Type *VecTy = scalableReduceVectorType(Call);
  if (!ResultTy || !VecTy)
    return false;
  const auto *STy = dyn_cast<ScalableVectorType>(VecTy);
  if (!STy || ResultTy != STy->getElementType())
    return false;
  const unsigned ExpectedArgs = HasStart ? 2u : 1u;
  if (Call.arg_size() != ExpectedArgs)
    return false;
  if (IsFloat) {
    if (!isSupportedScalableFloatType(VecTy) ||
        !isSupportedScalarFPFrameType(ResultTy))
      return false;
    if (HasStart && Call.getArgOperand(0)->getType() != ResultTy)
      return false;
    return true;
  }
  return isSupportedScalableIntegerType(VecTy) &&
         isSupportedIntegerType(ResultTy) && !ResultTy->isIntegerTy(1);
}

static uint64_t packScalableReduceVariant(const Type *VecTy, unsigned Kind,
                                          const FastMathFlags &FMF) {
  if (isSupportedScalableFloatType(VecTy))
    return packScalableFloatBinaryVariant(VecTy, FMF) |
           ((uint64_t(Kind) & ScalableReduceKindMask)
            << ScalableReduceKindShift);
  return packScalableIntegerVariant(VecTy) |
         ((uint64_t(Kind) & ScalableReduceKindMask) << ScalableReduceKindShift);
}

static unsigned unpackScalableReduceKind(uint64_t Variant) {
  return unsigned((Variant >> ScalableReduceKindShift) &
                  ScalableReduceKindMask);
}

static constexpr unsigned ScalableFPClassMaskShift = 8;

static bool isScalableFPClassShape(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::is_fpclass)
    return false;
  if (Call.arg_size() != 2)
    return false;
  Type *SrcTy = Call.getArgOperand(0)->getType();
  Type *PredTy = Call.getType();
  if (!isSupportedScalableFloatType(SrcTy) ||
      !scalablePredicateMatchesData(PredTy, SrcTy))
    return false;
  return Call.getArgOperand(1)->getType()->isIntegerTy(32);
}

static uint64_t packScalableFPClassVariant(const Type *SrcTy, uint64_t Mask) {
  return packScalableDataVariant(SrcTy) | (Mask << ScalableFPClassMaskShift);
}

static uint32_t unpackScalableFPClassMask(uint64_t Variant) {
  return uint32_t(Variant >> ScalableFPClassMaskShift);
}

enum ScalableSatCastKind : unsigned {
  SVESatCastSI = 0,
  SVESatCastUI = 1,
};

static constexpr unsigned ScalableSatCastKindShift = 8;
static constexpr uint64_t ScalableSatCastKindMask = 0x1;

static Type *scalableSatCastDestType(const Type *SrcTy) {
  const auto *STy = dyn_cast<ScalableVectorType>(SrcTy);
  if (!STy || !isSupportedScalableFloatType(SrcTy))
    return nullptr;
  Type *Elt = STy->getElementType();
  LLVMContext &Ctx = SrcTy->getContext();
  Type *IntElt = nullptr;
  if (Elt->isHalfTy())
    IntElt = Type::getInt16Ty(Ctx);
  else if (Elt->isFloatTy())
    IntElt = Type::getInt32Ty(Ctx);
  else if (Elt->isDoubleTy())
    IntElt = Type::getInt64Ty(Ctx);
  if (!IntElt)
    return nullptr;
  return ScalableVectorType::get(IntElt, STy->getMinNumElements());
}

static bool isScalableSatCastShape(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  if (ID != Intrinsic::fptosi_sat && ID != Intrinsic::fptoui_sat)
    return false;
  if (Call.arg_size() != 1)
    return false;
  Type *SrcTy = Call.getArgOperand(0)->getType();
  Type *DstTy = Call.getType();
  Type *Expect = scalableSatCastDestType(SrcTy);
  return Expect && DstTy == Expect && isSupportedScalableIntegerType(DstTy);
}

static uint64_t packScalableSatCastVariant(const Type *SrcTy, unsigned Kind) {
  return packScalableDataVariant(SrcTy) |
         ((uint64_t(Kind) & ScalableSatCastKindMask)
          << ScalableSatCastKindShift);
}

static unsigned unpackScalableSatCastKind(uint64_t Variant) {
  return unsigned((Variant >> ScalableSatCastKindShift) &
                  ScalableSatCastKindMask);
}

enum ScalableVecHelperKind : unsigned {
  SVEVecHelperStep = 0,
  SVEVecHelperReverse = 1,
  SVEVecHelperSplice = 2,
};

static constexpr unsigned ScalableVecHelperKindShift = 16;
static constexpr uint64_t ScalableVecHelperKindMask = 0xFF;
static constexpr unsigned ScalableVecHelperImmShift = 24;

static bool scalableVecHelperKindFromID(Intrinsic::ID ID,
                                        ScalableVecHelperKind &Kind,
                                        unsigned &Arity, bool &IntOnly,
                                        bool &HasImm) {
  switch (ID) {
  case Intrinsic::experimental_stepvector:
    Kind = SVEVecHelperStep;
    Arity = 0;
    IntOnly = true;
    HasImm = false;
    return true;
  case Intrinsic::experimental_vector_reverse:
    Kind = SVEVecHelperReverse;
    Arity = 1;
    IntOnly = false;
    HasImm = false;
    return true;
  case Intrinsic::experimental_vector_splice:
    Kind = SVEVecHelperSplice;
    Arity = 2;
    IntOnly = false;
    HasImm = true;
    return true;
  default:
    return false;
  }
}

static Intrinsic::ID scalableVecHelperIDFromKind(unsigned Kind) {
  switch (Kind) {
  case SVEVecHelperStep:
    return Intrinsic::experimental_stepvector;
  case SVEVecHelperReverse:
    return Intrinsic::experimental_vector_reverse;
  case SVEVecHelperSplice:
    return Intrinsic::experimental_vector_splice;
  default:
    llvm_unreachable("invalid SVE vec helper kind");
  }
}

/// LLVM 15 AArch64 LowerVECTOR_SPLICE: idx>=0 becomes EXT (legal for
/// every verifier-legal full-register index).  idx<0 becomes
/// ptrue+rev+splice only when abs(idx) is a known SVE predicate
/// pattern (1..8, 16, 32, 64, 128, 256).  nxv16i8 -9..-15 is
/// verifier-legal but has no pattern and ISel returns SDValue().
static bool isISelSafeScalableSpliceIndex(const Type *Ty, int64_t Idx) {
  const auto *STy = dyn_cast<ScalableVectorType>(Ty);
  if (!STy)
    return false;
  const int64_t Min = int64_t(STy->getMinNumElements());
  if (Idx >= 0)
    return Idx < Min;
  if (Idx == INT64_MIN)
    return false;
  const int64_t Abs = -Idx;
  if (Abs > Min)
    return false;
  if (Abs >= 1 && Abs <= 8)
    return true;
  return Abs == 16 || Abs == 32 || Abs == 64 || Abs == 128 || Abs == 256;
}

static bool isScalableVecHelperShape(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  ScalableVecHelperKind Kind;
  unsigned Arity = 0;
  bool IntOnly = false;
  bool HasImm = false;
  if (!scalableVecHelperKindFromID(II->getIntrinsicID(), Kind, Arity, IntOnly,
                                   HasImm))
    return false;
  Type *Ty = Call.getType();
  if (IntOnly) {
    if (!isSupportedScalableIntegerType(Ty))
      return false;
  } else if (!isSupportedScalableDataType(Ty)) {
    return false;
  }
  const unsigned ExpectedArgs = HasImm ? Arity + 1 : Arity;
  if (Call.arg_size() != ExpectedArgs)
    return false;
  for (unsigned Index = 0; Index < Arity; ++Index)
    if (Call.getArgOperand(Index)->getType() != Ty)
      return false;
  if (HasImm) {
    const Value *Imm = Call.getArgOperand(Arity);
    if (!Imm || !Imm->getType()->isIntegerTy(32))
      return false;
  }
  return true;
}

static uint64_t packScalableVecHelperVariant(const Type *Ty, unsigned Kind,
                                             int32_t Imm = 0) {
  return packScalableDataVariant(Ty) |
         ((uint64_t(Kind) & ScalableVecHelperKindMask)
          << ScalableVecHelperKindShift) |
         (uint64_t(uint32_t(Imm)) << ScalableVecHelperImmShift);
}

static unsigned unpackScalableVecHelperKind(uint64_t Variant) {
  return unsigned((Variant >> ScalableVecHelperKindShift) &
                  ScalableVecHelperKindMask);
}

static int32_t unpackScalableVecHelperImm(uint64_t Variant) {
  return int32_t(uint32_t(Variant >> ScalableVecHelperImmShift));
}

enum ScalableWhileKind : unsigned {
  SVEWhileALM = 0,
  SVEWhileLo = 1,
  SVEWhileLt = 2,
  SVEWhileLe = 3,
  SVEWhileLs = 4,
};

static constexpr unsigned ScalableWhileKindShift = 16;
static constexpr uint64_t ScalableWhileKindMask = 0xFF;

static bool scalableWhileKindFromID(Intrinsic::ID ID, ScalableWhileKind &Kind) {
  switch (ID) {
  case Intrinsic::get_active_lane_mask:
    Kind = SVEWhileALM;
    return true;
  case Intrinsic::aarch64_sve_whilelo:
    Kind = SVEWhileLo;
    return true;
  case Intrinsic::aarch64_sve_whilelt:
    Kind = SVEWhileLt;
    return true;
  case Intrinsic::aarch64_sve_whilele:
    Kind = SVEWhileLe;
    return true;
  case Intrinsic::aarch64_sve_whilels:
    Kind = SVEWhileLs;
    return true;
  default:
    return false;
  }
}

static Intrinsic::ID scalableWhileIDFromKind(unsigned Kind) {
  switch (Kind) {
  case SVEWhileALM:
    return Intrinsic::get_active_lane_mask;
  case SVEWhileLo:
    return Intrinsic::aarch64_sve_whilelo;
  case SVEWhileLt:
    return Intrinsic::aarch64_sve_whilelt;
  case SVEWhileLe:
    return Intrinsic::aarch64_sve_whilele;
  case SVEWhileLs:
    return Intrinsic::aarch64_sve_whilels;
  default:
    llvm_unreachable("invalid SVE while kind");
  }
}

static bool isScalableActiveLaneMaskShape(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  ScalableWhileKind Kind;
  if (!II || !scalableWhileKindFromID(II->getIntrinsicID(), Kind))
    return false;
  if (Call.arg_size() != 2)
    return false;
  Type *PredTy = Call.getType();
  if (!isSupportedScalablePredicateType(PredTy))
    return false;
  Type *IdxTy = Call.getArgOperand(0)->getType();
  if (!IdxTy || IdxTy != Call.getArgOperand(1)->getType() ||
      (!IdxTy->isIntegerTy(32) && !IdxTy->isIntegerTy(64)))
    return false;
  return true;
}

static uint64_t packScalableActiveLaneMaskVariant(const Type *PredTy,
                                                  unsigned IdxBits,
                                                  unsigned Kind) {
  return packScalablePredicateVariant(PredTy) |
         (uint64_t(IdxBits) << 8) |
         ((uint64_t(Kind) & ScalableWhileKindMask) << ScalableWhileKindShift);
}

static unsigned unpackScalableActiveLaneMaskIdxBits(uint64_t Variant) {
  return unsigned((Variant >> 8) & 0xFF);
}

static unsigned unpackScalableWhileKind(uint64_t Variant) {
  return unsigned((Variant >> ScalableWhileKindShift) & ScalableWhileKindMask);
}

enum ScalablePredHelperKind : unsigned {
  SVEPredHelperReverse = 0,
  SVEPredHelperPTrue = 1,
  SVEPredHelperCntp = 2,
  SVEPredHelperPTestAny = 3,
  SVEPredHelperPTestFirst = 4,
  SVEPredHelperPTestLast = 5,
};

static constexpr unsigned ScalablePredHelperKindShift = 16;
static constexpr uint64_t ScalablePredHelperKindMask = 0xFF;
static constexpr unsigned ScalablePredHelperImmShift = 24;
static constexpr uint64_t ScalablePredHelperImmMask = 0xFF;

static bool scalablePredHelperKindFromID(Intrinsic::ID ID,
                                         ScalablePredHelperKind &Kind,
                                         unsigned &PredArity, bool &HasImm,
                                         unsigned &DestBits) {
  switch (ID) {
  case Intrinsic::experimental_vector_reverse:
    Kind = SVEPredHelperReverse;
    PredArity = 1;
    HasImm = false;
    DestBits = 0;
    return true;
  case Intrinsic::aarch64_sve_ptrue:
    Kind = SVEPredHelperPTrue;
    PredArity = 0;
    HasImm = true;
    DestBits = 0;
    return true;
  case Intrinsic::aarch64_sve_cntp:
    Kind = SVEPredHelperCntp;
    PredArity = 2;
    HasImm = false;
    DestBits = 64;
    return true;
  case Intrinsic::aarch64_sve_ptest_any:
    Kind = SVEPredHelperPTestAny;
    PredArity = 2;
    HasImm = false;
    DestBits = 1;
    return true;
  case Intrinsic::aarch64_sve_ptest_first:
    Kind = SVEPredHelperPTestFirst;
    PredArity = 2;
    HasImm = false;
    DestBits = 1;
    return true;
  case Intrinsic::aarch64_sve_ptest_last:
    Kind = SVEPredHelperPTestLast;
    PredArity = 2;
    HasImm = false;
    DestBits = 1;
    return true;
  default:
    return false;
  }
}

static Intrinsic::ID scalablePredHelperIDFromKind(unsigned Kind) {
  switch (Kind) {
  case SVEPredHelperReverse:
    return Intrinsic::experimental_vector_reverse;
  case SVEPredHelperPTrue:
    return Intrinsic::aarch64_sve_ptrue;
  case SVEPredHelperCntp:
    return Intrinsic::aarch64_sve_cntp;
  case SVEPredHelperPTestAny:
    return Intrinsic::aarch64_sve_ptest_any;
  case SVEPredHelperPTestFirst:
    return Intrinsic::aarch64_sve_ptest_first;
  case SVEPredHelperPTestLast:
    return Intrinsic::aarch64_sve_ptest_last;
  default:
    llvm_unreachable("invalid SVE pred helper kind");
  }
}

static bool isScalablePredHelperShape(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  ScalablePredHelperKind Kind;
  unsigned PredArity = 0;
  bool HasImm = false;
  unsigned DestBits = 0;
  if (!scalablePredHelperKindFromID(II->getIntrinsicID(), Kind, PredArity,
                                    HasImm, DestBits))
    return false;
  Type *PredTy = DestBits ? (Call.arg_size() ? Call.getArgOperand(0)->getType()
                                             : nullptr)
                          : Call.getType();
  if (!PredTy || !isSupportedScalablePredicateType(PredTy))
    return false;
  if (DestBits && !Call.getType()->isIntegerTy(DestBits))
    return false;
  const unsigned ExpectedArgs = HasImm ? PredArity + 1 : PredArity;
  if (Call.arg_size() != ExpectedArgs)
    return false;
  for (unsigned Index = 0; Index < PredArity; ++Index)
    if (Call.getArgOperand(Index)->getType() != PredTy)
      return false;
  if (HasImm) {
    const Value *Imm = Call.getArgOperand(PredArity);
    if (!Imm || !Imm->getType()->isIntegerTy(32))
      return false;
  }
  return true;
}

static uint64_t packScalablePredHelperVariant(const Type *PredTy, unsigned Kind,
                                              uint32_t Imm = 0) {
  return packScalablePredicateVariant(PredTy) |
         ((uint64_t(Kind) & ScalablePredHelperKindMask)
          << ScalablePredHelperKindShift) |
         ((uint64_t(Imm) & ScalablePredHelperImmMask)
          << ScalablePredHelperImmShift);
}

static unsigned unpackScalablePredHelperKind(uint64_t Variant) {
  return unsigned((Variant >> ScalablePredHelperKindShift) &
                  ScalablePredHelperKindMask);
}

static uint32_t unpackScalablePredHelperImm(uint64_t Variant) {
  return uint32_t((Variant >> ScalablePredHelperImmShift) &
                  ScalablePredHelperImmMask);
}

