/// Shape only: listed constrained fptosi/fptoui/sitofp/uitofp/
/// fptrunc/fpext on fixed 1..128 IEEE f32/f64 vectors.  Same
/// operand/metadata slots as the scalar convert surface.  Integer
/// lanes are i1/i8/i16/i32/i64; both sides independently 1..128
/// with matching lane count.  fptrunc is only v*f64->v*f32;
/// fpext is only v*f32->v*f64.  No feature and no ABI.
/// half/bfloat/fp128/i128/scalable/>128 stay generic.
static bool
isConstrainedFixedVectorFPConvertShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || Call.arg_empty())
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  if (!isConstrainedScalarFPConvertID(ID))
    return false;
  const Value *Arg = Call.getArgOperand(0);
  Type *SrcTy = Arg ? Arg->getType() : nullptr;
  Type *DstTy = Call.getType();
  const auto *SrcVec = dyn_cast_or_null<FixedVectorType>(SrcTy);
  const auto *DstVec = dyn_cast_or_null<FixedVectorType>(DstTy);
  if (!SrcVec || !DstVec ||
      SrcVec->getNumElements() != DstVec->getNumElements() ||
      !isSupportedOrdinaryCallOperand(Arg))
    return false;
  unsigned ExpectedArgs = 0;
  if (ID == Intrinsic::experimental_constrained_fptosi ||
      ID == Intrinsic::experimental_constrained_fptoui) {
    if (!isSupportedF32F64VectorType(SrcTy) ||
        !isSupportedIntegerVectorType(DstTy))
      return false;
    ExpectedArgs = 2;
  } else if (ID == Intrinsic::experimental_constrained_sitofp ||
             ID == Intrinsic::experimental_constrained_uitofp) {
    if (!isSupportedIntegerVectorType(SrcTy) ||
        !isSupportedF32F64VectorType(DstTy))
      return false;
    ExpectedArgs = 3;
  } else if (ID == Intrinsic::experimental_constrained_fptrunc) {
    if (!isSupportedF32F64VectorType(SrcTy) ||
        !isSupportedF32F64VectorType(DstTy) ||
        !SrcVec->getElementType()->isDoubleTy() ||
        !DstVec->getElementType()->isFloatTy())
      return false;
    ExpectedArgs = 3;
  } else if (ID == Intrinsic::experimental_constrained_fpext) {
    if (!isSupportedF32F64VectorType(SrcTy) ||
        !isSupportedF32F64VectorType(DstTy) ||
        !SrcVec->getElementType()->isFloatTy() ||
        !DstVec->getElementType()->isDoubleTy())
      return false;
    ExpectedArgs = 2;
  } else {
    return false;
  }
  if (Call.arg_size() != ExpectedArgs)
    return false;
  for (unsigned Index = 1; Index < ExpectedArgs; ++Index) {
    const MDString *S = getMetadataAsString(Call.getArgOperand(Index));
    if (!S)
      return false;
    const ConstrainedFPMetadataKind Kind =
        getConstrainedFPMetadataKind(ID, Index);
    if (Kind == ConstrainedFPMetadataKind::Rounding &&
        !isLegalConstrainedRoundingMDString(S->getString()))
      return false;
    else if (Kind == ConstrainedFPMetadataKind::Except &&
             !isLegalConstrainedExceptMDString(S->getString()))
      return false;
    else if (Kind == ConstrainedFPMetadataKind::None)
      return false;
  }
  return true;
}

