/// Generic llvm.copysign / llvm.pow on fixed f32/f64 vectors only
/// (total width 1..128).  Re-emitted via CallDescriptor / vector
/// VRegs.  Does not accept half vectors — those stay on the existing
/// last-token +fullfp16 half-vector math path — and does not change
/// the scalar copysign/pow helpers.  Does not open vector sin/cos/
/// exp/log or other transcendentals.  Call site must be
/// CallingConv::C, exact non-vararg FunctionType, formal type
/// equality.  Ordinary tail, musttail, bundles, noreturn,
/// returns_twice, and complex ABI stay out.  No dedicated VM opcode
/// and no +fullfp16 gate.  Fast-math forms are whitelisted by the
/// intrinsic FMF gate.
static bool isSupportedF32F64VectorCopySignPowIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  if (ID != Intrinsic::copysign && ID != Intrinsic::pow)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedF32F64VectorType(ResultTy))
    return false;
  if (!isSupportedScalarFPMathCallSite(Call, ResultTy, 2))
    return false;
  for (unsigned Index = 0; Index < 2; ++Index) {
    if (!scalarFPMathFormalMatches(Call, Index, ResultTy) ||
        !isSupportedOrdinaryCallOperand(Call.getArgOperand(Index)))
      return false;
  }
  return true;
}

/// Generic llvm.powi on fixed f32/f64 vectors only (total width
/// 1..128): matching vector base plus a strict i32 scalar exponent
/// (LangRef vector form).  Re-emitted via CallDescriptor (vector
/// VReg + integer VReg).  Does not accept half vectors, i64/other
/// exponent widths, or change the scalar powi helper.  Call site must
/// be CallingConv::C, exact non-vararg FunctionType, formal type
/// equality (base matches the vector result; exponent formal is i32).
/// Ordinary tail, musttail, bundles, noreturn, returns_twice, and
/// complex ABI stay out.  The i32 exponent may be an ordinary SSA
/// value; a ConstantInt exponent is kept as a true immediate on
/// replay when ImmArg.  No dedicated VM opcode and no +fullfp16 gate.
/// Fast-math forms are whitelisted by the intrinsic FMF gate.
static bool isSupportedF32F64VectorPowiIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::powi)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedF32F64VectorType(ResultTy))
    return false;
  if (!isSupportedScalarFPMathCallSite(Call, ResultTy, 2))
    return false;
  const Value *Base = Call.getArgOperand(0);
  const Value *Exp = Call.getArgOperand(1);
  Type *I32Ty = Type::getInt32Ty(Call.getContext());
  if (!scalarFPMathFormalMatches(Call, 0, ResultTy) ||
      !isSupportedOrdinaryCallOperand(Base))
    return false;
  if (!scalarFPMathFormalMatches(Call, 1, I32Ty) ||
      !isSupportedOrdinaryCallOperand(Exp))
    return false;
  return true;
}

/// Generic llvm.sin/cos/exp/exp2/log/log2/log10 on fixed f32/f64
/// vectors only (total width 1..128).  Re-emitted via CallDescriptor /
/// vector VRegs.  Does not accept half vectors — those stay on the
/// existing last-token +fullfp16 half-vector math path — and does not
/// change the scalar transcendental helpers.  Does not open vector
/// pow/powi/canonicalize or any unlisted ID.  Call site must be
/// CallingConv::C and non-vararg.  Ordinary tail is not rejected
/// Ordinary tail, musttail, bundles, noreturn, returns_twice, and
/// complex ABI stay out.  No dedicated VM opcode and no +fullfp16 gate.
/// bfloat/fp128/scalable/>128/constrained/fastcc stay rejected.
/// Fast-math forms are whitelisted by the intrinsic FMF gate.
static bool isSupportedF32F64VectorTranscendentalIntrinsic(
    const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  if (ID != Intrinsic::sin && ID != Intrinsic::cos && ID != Intrinsic::exp &&
      ID != Intrinsic::exp2 && ID != Intrinsic::log && ID != Intrinsic::log2 &&
      ID != Intrinsic::log10)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedF32F64VectorType(ResultTy))
    return false;
  if (!isSupportedScalarFPMathCallSite(Call, ResultTy, 1) ||
      !scalarFPMathFormalMatches(Call, 0, ResultTy))
    return false;
  return isSupportedOrdinaryCallOperand(Call.getArgOperand(0));
}

/// Generic llvm.fptosi.sat / llvm.fptoui.sat on same-lane fixed
/// f32/f64 sources to i8/i16/i32/i64 destinations (each side total
/// width independently 1..128).  Re-emitted via CallDescriptor /
/// vector VRegs.  Does not change ordinary vector fptosi/fptoui
/// instructions, the scalar sat helpers, or the half feature gate.
/// Rejects half/bfloat/fp128, scalable, >128 on either side, i1 or
/// other dest element widths, lane mismatch, and constrained / other
/// IDs.  Call site must be CallingConv::C, exact non-vararg
/// FunctionType, formal type equality.  Ordinary tail, musttail,
/// bundles, noreturn, returns_twice, and complex ABI stay out.  No
/// dedicated VM opcode.
static bool isSupportedF32F64VectorSatConvertIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  if (ID != Intrinsic::fptosi_sat && ID != Intrinsic::fptoui_sat)
    return false;
  Type *ResultTy = Call.getType();
  const auto *FixedResult = dyn_cast<FixedVectorType>(ResultTy);
  if (!FixedResult || !isSupportedIntegerVectorType(FixedResult))
    return false;
  Type *ResultElt = FixedResult->getElementType();
  if (!ResultElt->isIntegerTy(8) && !ResultElt->isIntegerTy(16) &&
      !ResultElt->isIntegerTy(32) && !ResultElt->isIntegerTy(64))
    return false;
  if (!isSupportedScalarFPMathCallSite(Call, ResultTy, 1))
    return false;
  const Value *Arg = Call.getArgOperand(0);
  if (!Arg || !scalarFPMathFormalMatches(Call, 0, Arg->getType()) ||
      !isSupportedOrdinaryCallOperand(Arg))
    return false;
  const auto *ArgTy = dyn_cast<FixedVectorType>(Arg->getType());
  if (!ArgTy || !isSupportedF32F64VectorType(ArgTy))
    return false;
  return ArgTy->getNumElements() == FixedResult->getNumElements();
}

/// Generic llvm.ctpop / llvm.bswap / llvm.bitreverse / llvm.ctlz /
/// llvm.cttz on fixed i8/i16/i32/i64 vectors only (total width 1..128).
/// Re-emitted via CallDescriptor / vector VRegs.  ctpop/bswap/bitreverse
/// are unary and same-typed; ctlz/cttz take the same-typed vector plus
/// an i1 ConstantInt ImmArg is_zero_undef flag kept on
/// ImmediateArguments.  bswap additionally requires an even-byte
/// element (i16/i32/i64); i8 bswap is not well-formed LLVM IR.
/// Does not change the scalar bit helpers, restricted scalar i128 bit
/// helpers, ordinary vector arithmetic, or the half feature gate.
/// Rejects i1/i128 elements, float/half/bfloat, scalable, pointer,
/// aggregate, and >128.  Call site must be CallingConv::C with an
/// exact non-vararg FunctionType and formal parameter type equality.
/// Ordinary tail, musttail, bundles, noreturn, returns_twice, and
/// complex ABI stay out.  No dedicated VM opcode and no FastMathFlags
/// path.
static bool isSupportedIntegerVectorBitIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  const bool IsUnary = ID == Intrinsic::ctpop || ID == Intrinsic::bswap ||
                       ID == Intrinsic::bitreverse;
  const bool IsCountZero = ID == Intrinsic::ctlz || ID == Intrinsic::cttz;
  if (!IsUnary && !IsCountZero)
    return false;

  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;

  Type *ResultTy = Call.getType();
  if (!isSupportedIntegerVectorBitOpType(ResultTy))
    return false;
  // llvm.bswap requires an even number of bytes per element.
  if (ID == Intrinsic::bswap &&
      cast<FixedVectorType>(ResultTy)->getElementType()->isIntegerTy(8))
    return false;

  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy)
    return false;

  if (IsUnary) {
    if (Call.arg_size() != 1 || FTy->getNumParams() != 1)
      return false;
    const Value *Arg = Call.getArgOperand(0);
    return Arg && Arg->getType() == ResultTy &&
           Arg->getType() == FTy->getParamType(0) &&
           isSupportedOrdinaryCallOperand(Arg);
  }

  if (Call.arg_size() != 2 || FTy->getNumParams() != 2)
    return false;
  const Value *Arg = Call.getArgOperand(0);
  if (!Arg || Arg->getType() != ResultTy ||
      Arg->getType() != FTy->getParamType(0) ||
      !isSupportedOrdinaryCallOperand(Arg))
    return false;
  const Value *Flag = Call.getArgOperand(1);
  if (!Flag || Flag->getType() != FTy->getParamType(1) ||
      !Flag->getType()->isIntegerTy(1) || !isCallImmediateArgument(Call, 1))
    return false;
  const auto *IsZeroPoison = dyn_cast<ConstantInt>(Flag);
  return IsZeroPoison && IsZeroPoison->getType()->isIntegerTy(1);
}

/// Generic llvm.fshl / llvm.fshr on three identical fixed i8/i16/i32/i64
/// vectors (total width 1..128).  Ordinary two-operand funnel is accepted
/// (A and B need not be the same SSA value); this is not tightened to
/// rotate.  Re-emitted via CallDescriptor / vector VRegs.  Does not
/// change scalar funnel, restricted scalar i128 funnel, or
/// VMP's internal bytecode-decode fshl.  Call site must be
/// CallingConv::C with an exact non-vararg FunctionType and formal
/// parameter type equality.  Ordinary tail, musttail, bundles,
/// noreturn, returns_twice, and complex ABI stay out.  No dedicated
/// VM opcode and no FastMathFlags path.
static bool isSupportedIntegerVectorFunnelShiftIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  if (ID != Intrinsic::fshl && ID != Intrinsic::fshr)
    return false;

  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;

  Type *ResultTy = Call.getType();
  if (!isSupportedIntegerVectorBitOpType(ResultTy))
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 3)
    return false;
  if (Call.arg_size() != 3)
    return false;
  const Value *A = Call.getArgOperand(0);
  const Value *B = Call.getArgOperand(1);
  const Value *Amt = Call.getArgOperand(2);
  if (!A || !B || !Amt)
    return false;
  if (A->getType() != ResultTy || B->getType() != ResultTy ||
      Amt->getType() != ResultTy)
    return false;
  if (A->getType() != FTy->getParamType(0) ||
      B->getType() != FTy->getParamType(1) ||
      Amt->getType() != FTy->getParamType(2))
    return false;
  return isSupportedOrdinaryCallOperand(A) &&
         isSupportedOrdinaryCallOperand(B) &&
         isSupportedOrdinaryCallOperand(Amt);
}

/// Generic llvm.abs on fixed i8/i16/i32/i64 vectors only (total width
/// 1..128).  Same-typed vector plus i1 ConstantInt ImmArg
/// is_int_min_poison, kept on ImmediateArguments.  Re-emitted via
/// CallDescriptor / vector VRegs.  Does not change the scalar abs
/// helper, restricted scalar i128 abs, NEON sat, or ordinary vector
/// arithmetic.  Rejects i1/i128 elements, float/half/bfloat, scalable,
/// and >128.  Call site must be CallingConv::C with an exact
/// non-vararg FunctionType and formal parameter type equality.
/// Ordinary tail, musttail, bundles, noreturn, returns_twice, and
/// complex ABI stay out.  No dedicated VM opcode and no FastMathFlags
/// path.
static bool isSupportedIntegerVectorAbsIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::abs)
    return false;

  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;

  Type *ResultTy = Call.getType();
  if (!isSupportedIntegerVectorBitOpType(ResultTy))
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 2)
    return false;
  if (Call.arg_size() != 2)
    return false;
  const Value *Arg = Call.getArgOperand(0);
  if (!Arg || Arg->getType() != ResultTy ||
      Arg->getType() != FTy->getParamType(0) ||
      !isSupportedOrdinaryCallOperand(Arg))
    return false;
  const Value *Flag = Call.getArgOperand(1);
  if (!Flag || Flag->getType() != FTy->getParamType(1) ||
      !Flag->getType()->isIntegerTy(1) || !isCallImmediateArgument(Call, 1))
    return false;
  const auto *IsIntMinPoison = dyn_cast<ConstantInt>(Flag);
  return IsIntMinPoison && IsIntMinPoison->getType()->isIntegerTy(1);
}

/// Generic llvm.sadd/uadd/ssub/usub/sshl/ushl.sat on two identical
/// fixed i8/i16/i32/i64 vectors (total width 1..128).  Re-emitted via
/// CallDescriptor / vector VRegs.  Does not change scalar saturating
/// helpers, restricted scalar i128 sat, AArch64 NEON sqadd/uqadd/
/// sqsub/uqsub, or ordinary vector arithmetic.  Call site must be
/// CallingConv::C with an exact non-vararg FunctionType and formal
/// parameter type equality.  Ordinary tail, musttail, bundles,
/// noreturn, returns_twice, and complex ABI stay out.  No dedicated
/// VM opcode and no FastMathFlags path.
static bool isSupportedIntegerVectorSaturatingIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  switch (II->getIntrinsicID()) {
  case Intrinsic::sadd_sat:
  case Intrinsic::uadd_sat:
  case Intrinsic::ssub_sat:
  case Intrinsic::usub_sat:
  case Intrinsic::sshl_sat:
  case Intrinsic::ushl_sat:
    break;
  default:
    return false;
  }

  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;

  Type *ResultTy = Call.getType();
  if (!isSupportedIntegerVectorBitOpType(ResultTy))
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 2)
    return false;
  if (Call.arg_size() != 2)
    return false;
  const Value *LHS = Call.getArgOperand(0);
  const Value *RHS = Call.getArgOperand(1);
  if (!LHS || !RHS)
    return false;
  if (LHS->getType() != ResultTy || RHS->getType() != ResultTy)
    return false;
  if (LHS->getType() != FTy->getParamType(0) ||
      RHS->getType() != FTy->getParamType(1))
    return false;
  return isSupportedOrdinaryCallOperand(LHS) &&
         isSupportedOrdinaryCallOperand(RHS);
}

/// Fixed i8/i16/i32/i64 vectors whose total primitive width is exactly
/// 64 or 128.  Used only by vector smul/umul/sdiv/udiv.fix and
/// .fix.sat: AArch64 ISel is stable on these widths and crashes on
/// leftover widths such as <3 x i32> (96).
static bool isSupportedIntegerVectorFixPointType(const Type *Ty) {
  if (!isSupportedIntegerVectorBitOpType(Ty))
    return false;
  const unsigned Bits =
      cast<FixedVectorType>(Ty)->getPrimitiveSizeInBits().getFixedValue();
  return Bits == 64 || Bits == 128;
}

/// Restricted llvm.smul/umul/sdiv/udiv.fix and .fix.sat on identical
/// fixed i8/i16/i32/i64 vectors (total width exactly 64 or 128).
/// Scale is an i32 ConstantInt ImmArg kept on ImmediateArguments.
/// Re-emitted via CallDescriptor / vector VRegs.  Does not change
/// scalar fixed-point, vector bit/sat, half, or add a VM opcode.
/// Non-64/128 leftover widths stay rejected so AArch64 llc cannot
/// crash.  Call site must be CallingConv::C with an exact non-vararg
/// FunctionType and formal parameter type equality.  Ordinary tail,
/// musttail, bundles, noreturn, returns_twice, and complex ABI stay
/// out.
static bool isSupportedIntegerVectorFixPointIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  switch (II->getIntrinsicID()) {
  case Intrinsic::smul_fix:
  case Intrinsic::umul_fix:
  case Intrinsic::sdiv_fix:
  case Intrinsic::udiv_fix:
  case Intrinsic::smul_fix_sat:
  case Intrinsic::umul_fix_sat:
  case Intrinsic::sdiv_fix_sat:
  case Intrinsic::udiv_fix_sat:
    break;
  default:
    return false;
  }

  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;

  Type *ResultTy = Call.getType();
  if (!isSupportedIntegerVectorFixPointType(ResultTy))
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 3)
    return false;
  if (Call.arg_size() != 3)
    return false;
  const Value *LHS = Call.getArgOperand(0);
  const Value *RHS = Call.getArgOperand(1);
  const Value *Scale = Call.getArgOperand(2);
  if (!LHS || !RHS || !Scale)
    return false;
  if (LHS->getType() != ResultTy || RHS->getType() != ResultTy)
    return false;
  if (LHS->getType() != FTy->getParamType(0) ||
      RHS->getType() != FTy->getParamType(1) ||
      Scale->getType() != FTy->getParamType(2))
    return false;
  if (!isSupportedOrdinaryCallOperand(LHS) ||
      !isSupportedOrdinaryCallOperand(RHS))
    return false;
  if (!Scale->getType()->isIntegerTy(32) || !isa<ConstantInt>(Scale) ||
      !isCallImmediateArgument(Call, 2))
    return false;
  return true;
}

/// Generic llvm.canonicalize on fixed f32/f64 vectors only (total
/// width 1..128).  Eligibility only: planning lowers it to
/// VectorFMul(x, splat 1.0) with packVectorVariant carrying the exact
/// FastMathFlags, matching the scalar FMul(x, 1.0) expansion.  Never
/// re-emits llvm.canonicalize (AArch64/X86 cannot select it).  Does
/// not accept half vectors, does not change the scalar canonicalize
/// helper, and does not add a VM opcode.  Call site must be
/// CallingConv::C, exact non-vararg FunctionType, formal type
/// equality.  Ordinary tail, musttail, bundles, noreturn,
/// returns_twice, and complex ABI stay out before VectorFMul
/// lowering.  bfloat/fp128/scalable/>128/constrained/fastcc stay
/// rejected.
static bool isSupportedF32F64VectorCanonicalizeIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::canonicalize)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedF32F64VectorType(ResultTy))
    return false;
  if (!isSupportedScalarFPMathCallSite(Call, ResultTy, 1) ||
      !scalarFPMathFormalMatches(Call, 0, ResultTy))
    return false;
  return isSupportedOrdinaryCallOperand(Call.getArgOperand(0));
}

/// Generic llvm.is.fpclass on fixed f32/f64 vectors only (total width
/// 1..128).  Result is a same-lane <N x i1> mask.  The class test
/// (arg 1) must be an i32 ConstantInt ImmArg and is kept on the
/// CallDescriptor, never a VReg.  Re-emitted via CallDescriptor /
/// vector VRegs.  Does not change the scalar is.fpclass helper, the
/// half feature gate, or add a VM opcode.  Call site must be
/// CallingConv::C, exact non-vararg FunctionType, formal type
/// equality.  Ordinary tail, musttail, bundles, noreturn,
/// returns_twice, and complex ABI stay out.  The class mask must be a
/// true i32 ImmArg ConstantInt.  half/bfloat/fp128/scalable/>128,
/// mismatched mask width, dynamic or non-i32 masks, constrained, and
/// fastcc stay rejected.
static bool isSupportedF32F64VectorFPClassIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::is_fpclass)
    return false;
  Type *ResultTy = Call.getType();
  const auto *FixedResult = dyn_cast<FixedVectorType>(ResultTy);
  if (!FixedResult || !isSupportedI1VectorType(FixedResult))
    return false;
  if (!isSupportedScalarFPMathCallSite(Call, ResultTy, 2))
    return false;
  const Value *Arg = Call.getArgOperand(0);
  const Value *Mask = Call.getArgOperand(1);
  if (!Arg || !Mask ||
      !scalarFPMathFormalMatches(Call, 0, Arg->getType()) ||
      !isSupportedOrdinaryCallOperand(Arg))
    return false;
  const auto *ArgTy = dyn_cast<FixedVectorType>(Arg->getType());
  if (!ArgTy || !isSupportedF32F64VectorType(ArgTy))
    return false;
  if (ArgTy->getNumElements() != FixedResult->getNumElements())
    return false;
  Type *I32Ty = Type::getInt32Ty(Call.getContext());
  if (!scalarFPMathFormalMatches(Call, 1, I32Ty) ||
      !Mask->getType()->isIntegerTy(32) || !isa<ConstantInt>(Mask))
    return false;
  return isCallImmediateArgument(Call, 1);
}

/// Listed f32/f64 vector math/helper IDs.  Half / bfloat / fp128 /
/// scalable stay on their own helpers and feature gates.
static bool isListedF32F64VectorIntrinsicID(Intrinsic::ID ID) {
  return isListedScalarFPMathIntrinsicID(ID) ||
         isListedScalarFPHelperIntrinsicID(ID);
}

static const char *f32F64VectorUnsupportedReason(Intrinsic::ID ID) {
  if (const char *Reason = scalarFPMathUnsupportedReason(ID))
    return Reason;
  return scalarFPHelperUnsupportedReason(ID);
}

static bool typeBlocksF32F64VectorDedicatedSkip(const Type *Ty) {
  if (!Ty)
    return false;
  if (isa<ScalableVectorType>(Ty))
    return true;
  const auto *VTy = dyn_cast<VectorType>(Ty);
  if (!VTy)
    return false;
  Type *Elt = VTy->getElementType();
  return Elt->isHalfTy() || Elt->isBFloatTy() || Elt->isFP128Ty() ||
         Elt->isPPC_FP128Ty();
}

/// Dedicated f32/f64 vector skips must not steal half-vector feature
/// gates or bfloat/fp128/scalable surfaces.  The listed-ID table is
/// shared with scalar math, so a scalar IEEE fp128 / bfloat / half
/// call must also fall through; only actual fixed f32/f64 vector
/// calls take these skip strings.
static bool shouldDeferF32F64VectorDedicatedSkip(const CallInst &Call) {
  if (typeBlocksF32F64VectorDedicatedSkip(Call.getType()))
    return true;
  for (unsigned Index = 0, E = Call.arg_size(); Index != E; ++Index)
    if (typeBlocksF32F64VectorDedicatedSkip(
            Call.getArgOperand(Index)->getType()))
      return true;
  if (isSupportedF32F64VectorType(Call.getType()))
    return false;
  for (unsigned Index = 0, E = Call.arg_size(); Index != E; ++Index)
    if (isSupportedF32F64VectorType(Call.getArgOperand(Index)->getType()))
      return false;
  return true;
}

/// Well-shaped llvm.is.fpclass on a fixed half vector (same-lane
/// <N x i1>, i32 ConstantInt mask).  No feature and no ABI.  Missing
/// or last-token -fullfp16 reports "unsupported target feature".
/// bfloat/scalable/>128/non-constant or non-i32 masks stay generic.
static bool isHalfVectorFPClassShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::is_fpclass)
    return false;
  if (Call.arg_size() != 2)
    return false;
  const auto *ResultTy = dyn_cast<FixedVectorType>(Call.getType());
  if (!ResultTy || !isSupportedI1VectorType(ResultTy))
    return false;
  const Value *Arg = Call.getArgOperand(0);
  if (!Arg)
    return false;
  const auto *ArgTy = dyn_cast<FixedVectorType>(Arg->getType());
  if (!ArgTy || !isSupportedHalfVectorType(ArgTy))
    return false;
  if (ArgTy->getNumElements() != ResultTy->getNumElements())
    return false;
  const Value *Mask = Call.getArgOperand(1);
  return Mask && Mask->getType()->isIntegerTy(32) && isa<ConstantInt>(Mask);
}

/// Restricted llvm.is.fpclass on fixed IEEE half vectors (total width
/// 1..128).  Result is a same-lane <N x i1>.  The class test is an
/// i32 ConstantInt ImmArg kept on the CallDescriptor.  Requires
/// last-token function +fullfp16.  Does not change the scalar
/// is.fpclass helper, the f32/f64 vector helper, listed half-vector
/// math, or add a VM opcode.  Ordinary tail is not rejected here;
/// musttail stays out.  No FastMathFlags path.
static bool isSupportedHalfVectorFPClassIntrinsic(const CallInst &Call) {
  if (!isHalfVectorFPClassShapeSupported(Call))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.getFunctionType()->isVarArg())
    return false;
  const Function *Parent = Call.getFunction();
  if (!Parent || !functionHasExplicitFullFP16Enabled(*Parent))
    return false;
  const Value *Arg = Call.getArgOperand(0);
  if (!isSupportedOrdinaryCallOperand(Arg))
    return false;
  return isCallImmediateArgument(Call, 1);
}

/// Well-shaped scalar llvm.is.fpclass.f16 (i1 result, half operand,
/// i32 ConstantInt mask).  No feature and no ABI.  Missing or
/// last-token -fullfp16 reports "unsupported target feature".
/// bfloat/fp128/vector/non-constant or non-i32 masks stay generic.
static bool isScalarHalfFPClassShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::is_fpclass)
    return false;
  if (Call.arg_size() != 2)
    return false;
  if (!Call.getType()->isIntegerTy(1))
    return false;
  const Value *Arg = Call.getArgOperand(0);
  if (!Arg || !Arg->getType()->isHalfTy())
    return false;
  const Value *Mask = Call.getArgOperand(1);
  return Mask && Mask->getType()->isIntegerTy(32) && isa<ConstantInt>(Mask);
}

/// Restricted scalar llvm.is.fpclass.f16.  i1 result; half operand;
/// i32 ConstantInt ImmArg mask kept on CallDescriptor ImmediateArguments.
/// Requires last-token function +fullfp16.  Does not change the scalar
