/// Scalar llvm.sqrt.f16/f32/f64 only (Intrinsic::sqrt + matching scalar
/// half/float/double result/arg).  C, exact non-vararg FunctionType,
/// formal type equality.  Ordinary tail, musttail, bundles, noreturn,
/// returns_twice, and complex ABI stay out.  Re-emitted through the
/// normal call handler; no dedicated VM opcode.  bfloat/vector/constrained
/// and other math intrinsics stay rejected.  Listed scalar IEEE fp128
/// sqrt uses isSupportedFP128MathIntrinsic.  Fast-math forms are
/// whitelisted by the intrinsic FMF gate (flags restored via the
/// CallDescriptor mask).
static bool isSupportedSqrtIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::sqrt)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedScalarFPType(ResultTy))
    return false;
  if (!isSupportedScalarFPMathCallSite(Call, ResultTy, 1) ||
      !scalarFPMathFormalMatches(Call, 0, ResultTy))
    return false;
  const Value *Arg = Call.getArgOperand(0);
  return isSupportedOrdinaryCallOperand(Arg) &&
         isScalarHalfMathFeatureOK(Call, ResultTy);
}

