/// Scalar llvm.powi.f16.i32 / llvm.powi.f32.i32 / llvm.powi.f64.i32 only
/// (Intrinsic::powi, matching scalar half/float/double base, strictly i32
/// exponent).  Half requires last-token function +fullfp16.  C, exact
/// non-vararg FunctionType, formal type equality (base matches result;
/// exponent formal is i32).  Ordinary tail, musttail, bundles, noreturn,
/// returns_twice, and complex ABI stay out.  Re-emitted through the
/// normal call handler using existing float and integer virtual
/// registers; no dedicated VM opcode.  i64/other exponent widths,
/// bfloat/vector, constrained, and other forms stay rejected.
/// Listed scalar IEEE fp128 powi uses isSupportedFP128PowiIntrinsic.
/// Fast-math forms with an i32 exponent are whitelisted by the intrinsic
/// FMF gate.  canonicalize is separately whitelisted: its FMul lowering
/// carries the exact flags in the opcode Variant.
static bool isSupportedPowiIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::powi)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedScalarFPType(ResultTy))
    return false;
  if (!isSupportedScalarFPMathCallSite(Call, ResultTy, 2))
    return false;
  const Value *Base = Call.getArgOperand(0);
  const Value *Exp = Call.getArgOperand(1);
  Type *I32Ty = Type::getInt32Ty(Call.getContext());
  // Base must match the scalar half/float/double result type.
  if (!scalarFPMathFormalMatches(Call, 0, ResultTy) ||
      !isSupportedOrdinaryCallOperand(Base))
    return false;
  // Exponent must be exactly i32 (not i64 or other widths).
  if (!scalarFPMathFormalMatches(Call, 1, I32Ty) ||
      !isSupportedOrdinaryCallOperand(Exp))
    return false;
  return isScalarHalfMathFeatureOK(Call, ResultTy);
}

/// Scalar llvm.pow.f16/f32/f64 only (Intrinsic::pow + matching scalar half/
/// float/double result/args).  Half requires last-token function +fullfp16.
/// C, exact non-vararg FunctionType, formal type equality.  Ordinary tail,
/// musttail, bundles, noreturn, returns_twice, and complex ABI stay out.
/// Re-emitted through the normal call handler; no dedicated VM opcode.
/// bfloat/vector, mixed types, constrained, and other forms stay
/// rejected.  Listed scalar IEEE fp128 pow uses
/// isSupportedFP128PowIntrinsic.  Fast-math forms are whitelisted by
/// the intrinsic FMF gate.
static bool isSupportedPowIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::pow)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedScalarFPType(ResultTy))
    return false;
  if (!isSupportedScalarFPMathCallSite(Call, ResultTy, 2))
    return false;
  for (unsigned Index = 0; Index < 2; ++Index) {
    if (!scalarFPMathFormalMatches(Call, Index, ResultTy) ||
        !isSupportedOrdinaryCallOperand(Call.getArgOperand(Index)))
      return false;
  }
  return isScalarHalfMathFeatureOK(Call, ResultTy);
}

/// Listed llvm.*.vNf16 IDs for the restricted half-vector math surface.
/// powi is the LangRef vector form: matching half vector + scalar integer
/// exponent.  Other IDs stay out.
static bool isListedHalfVectorMathID(Intrinsic::ID ID,
                                     unsigned &ExpectedVecArgs,
                                     bool &HasI32PowiExp) {
  HasI32PowiExp = false;
  switch (ID) {
  case Intrinsic::sqrt:
  case Intrinsic::fabs:
  case Intrinsic::ceil:
  case Intrinsic::floor:
  case Intrinsic::trunc:
  case Intrinsic::round:
  case Intrinsic::rint:
  case Intrinsic::nearbyint:
  case Intrinsic::roundeven:
  case Intrinsic::sin:
  case Intrinsic::cos:
  case Intrinsic::exp:
  case Intrinsic::exp2:
  case Intrinsic::log:
  case Intrinsic::log2:
  case Intrinsic::log10:
    ExpectedVecArgs = 1;
    return true;
  case Intrinsic::minnum:
  case Intrinsic::maxnum:
  case Intrinsic::minimum:
  case Intrinsic::maximum:
  case Intrinsic::copysign:
  case Intrinsic::pow:
    ExpectedVecArgs = 2;
    return true;
  case Intrinsic::fma:
  case Intrinsic::fmuladd:
    ExpectedVecArgs = 3;
    return true;
  case Intrinsic::powi:
    // LangRef: vector float base, second argument remains a scalar integer.
    // Only the C int-width i32 exponent is accepted.
    ExpectedVecArgs = 1;
    HasI32PowiExp = true;
    return true;
  default:
    return false;
  }
}

/// Well-shaped listed fixed half-vector math (no feature, no ABI).
/// Missing/final -fullfp16 reports "unsupported target feature".
/// Scalable/bfloat/>128/unlisted/wrong powi width stay generic.
static bool isHalfVectorMathShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedHalfVectorType(ResultTy))
    return false;
  unsigned ExpectedVecArgs = 0;
  bool HasI32PowiExp = false;
  if (!isListedHalfVectorMathID(II->getIntrinsicID(), ExpectedVecArgs,
                                HasI32PowiExp))
    return false;
  const unsigned ExpectedArgs =
      ExpectedVecArgs + (HasI32PowiExp ? 1u : 0u);
  if (Call.arg_size() != ExpectedArgs)
    return false;
  for (unsigned Index = 0; Index < ExpectedVecArgs; ++Index) {
    const Value *Arg = Call.getArgOperand(Index);
    if (!Arg || Arg->getType() != ResultTy)
      return false;
  }
  if (HasI32PowiExp) {
    const Value *Exp = Call.getArgOperand(ExpectedVecArgs);
    if (!Exp || !Exp->getType()->isIntegerTy(32))
      return false;
  }
  return true;
}

/// Restricted listed llvm.*.vNf16 on a supported fixed half vector
/// (total width 1..128).  Re-emitted through CallDescriptor (vector
/// VRegs, F16 encoding, FastMathFlags mask).  Requires last-token
/// function +fullfp16.  Does not open f32/f64 vectors, scalar helpers,
/// constrained forms, or unlisted IDs.
static bool isSupportedHalfVectorMathIntrinsic(const CallInst &Call) {
  if (!isHalfVectorMathShapeSupported(Call))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.getFunctionType()->isVarArg())
    return false;
  const Function *Parent = Call.getFunction();
  if (!Parent || !functionHasExplicitFullFP16Enabled(*Parent))
    return false;
  for (const Value *Arg : Call.args()) {
    if (!isSupportedOrdinaryCallOperand(Arg))
      return false;
  }
  return true;
}

/// Scalar llvm.fabs.f16/f32/f64 only (Intrinsic::fabs + matching scalar
/// half/float/double result/arg).  C, exact non-vararg FunctionType,
/// formal type equality.  Ordinary tail, musttail, bundles, noreturn,
/// returns_twice, and complex ABI stay out.  Re-emitted through the
/// normal call handler; no dedicated VM opcode.  bfloat/vector/constrained
/// and other math intrinsics stay rejected.  Listed scalar IEEE fp128
/// fabs uses isSupportedFP128MathIntrinsic.  Fast-math forms are
/// whitelisted by the intrinsic FMF gate (flags restored via the
/// CallDescriptor mask).
static bool isSupportedFAbsIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::fabs)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedScalarFPType(ResultTy))
    return false;
  if (!isSupportedScalarFPMathCallSite(Call, ResultTy, 1) ||
      !scalarFPMathFormalMatches(Call, 0, ResultTy))
    return false;
  const Value *Arg = Call.getArgOperand(0);
  return isSupportedOrdinaryCallOperand(Arg) &&
         isScalarHalfMathFeatureOK(Call, ResultTy);
}

/// Shape only: listed same-type bfloat math plus llvm.pow (matching
/// bfloat operands), llvm.powi (bfloat scalar/vector base + scalar
/// i32 exponent), and llvm.fmuladd (same ternary shape as fma;
/// legalize is f32 llvm.fma + RNE).  Constrained, non-i32 / vector
/// exponents, half/f32/f64, scalable, and overwide stay out.
/// last-token +bf16, FMF, and ABI are checked by eligibility /
/// isSupportedBFloatMathIntrinsic.
static bool isBFloatMathIntrinsicShape(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  Type *Ty = Call.getType();
  if (!isSupportedScalarBFloatType(Ty) && !isSupportedBFloatVectorType(Ty))
    return false;
  if (II->getIntrinsicID() == Intrinsic::powi) {
    if (Call.arg_size() != 2)
      return false;
    const Value *Base = Call.getArgOperand(0);
    const Value *Exp = Call.getArgOperand(1);
    if (!Base || Base->getType() != Ty || !isSupportedOperand(Base))
      return false;
    return Exp && Exp->getType()->isIntegerTy(32) && isSupportedOperand(Exp);
  }
  unsigned ExpectedArgs = 0;
  switch (II->getIntrinsicID()) {
  case Intrinsic::fabs:
  case Intrinsic::sqrt:
  case Intrinsic::ceil:
  case Intrinsic::floor:
  case Intrinsic::trunc:
  case Intrinsic::round:
  case Intrinsic::roundeven:
  case Intrinsic::rint:
  case Intrinsic::nearbyint:
  case Intrinsic::sin:
  case Intrinsic::cos:
  case Intrinsic::exp:
  case Intrinsic::exp2:
  case Intrinsic::log:
  case Intrinsic::log2:
  case Intrinsic::log10:
    ExpectedArgs = 1;
    break;
  case Intrinsic::minnum:
  case Intrinsic::maxnum:
  case Intrinsic::minimum:
  case Intrinsic::maximum:
  case Intrinsic::copysign:
  case Intrinsic::pow:
    ExpectedArgs = 2;
    break;
  case Intrinsic::fma:
  case Intrinsic::fmuladd:
    ExpectedArgs = 3;
    break;
  default:
    return false;
  }
  if (Call.arg_size() != ExpectedArgs)
    return false;
  for (unsigned Index = 0; Index < ExpectedArgs; ++Index) {
    const Value *Arg = Call.getArgOperand(Index);
    if (!Arg || Arg->getType() != Ty || !isSupportedOperand(Arg))
      return false;
  }
  return true;
}

/// last-token +bf16 listed same-type bfloat math on scalar bfloat or
/// a supported fixed bfloat vector.  C, non-vararg, no musttail /
/// bundles / noreturn / complex ABI.  Any representable FastMathFlags
/// are rejected (legalize through f32 / i16 must not drop or apply
/// them).  Replayed via CallDescriptor.LegalizeBFloatMath — never as
/// a native bfloat intrinsic.
static bool isSupportedBFloatMathIntrinsic(const CallInst &Call) {
  if (!isBFloatMathIntrinsicShape(Call))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.getFunctionType()->isVarArg())
    return false;
  return parentHasExplicitBF16Enabled(Call) &&
         bfloatVectorAllowsFastMathFlags(Call);
}

/// Shape only: llvm.fptosi.sat / llvm.fptoui.sat from scalar bfloat to
/// i8/i16/i32/i64, or from a supported fixed bfloat vector to a
/// same-lane i8/i16/i32/i64 vector whose total width is independently
/// 1..128.  i1/i128, lane mismatch, scalable, overwide, and
/// non-saturating fptosi/fptoui stay out.
static bool isBFloatSatConvertShape(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  if (ID != Intrinsic::fptosi_sat && ID != Intrinsic::fptoui_sat)
    return false;
  if (Call.arg_size() != 1)
    return false;
  const Value *Arg = Call.getArgOperand(0);
  if (!Arg || !isSupportedOperand(Arg))
    return false;
  Type *SrcTy = Arg->getType();
  Type *DstTy = Call.getType();
  if (isSupportedScalarBFloatType(SrcTy)) {
    if (!DstTy->isIntegerTy())
      return false;
    const unsigned Bits = DstTy->getIntegerBitWidth();
    return Bits == 8 || Bits == 16 || Bits == 32 || Bits == 64;
  }
  if (!isSupportedBFloatVectorType(SrcTy))
    return false;
  if (!isSupportedIntegerVectorBitOpType(DstTy))
    return false;
  return cast<FixedVectorType>(SrcTy)->getNumElements() ==
         cast<FixedVectorType>(DstTy)->getNumElements();
}

/// last-token +bf16 llvm.fptosi.sat / llvm.fptoui.sat from scalar or
/// fixed bfloat (1..128) to i8/i16/i32/i64 (scalar or same-lane
/// vector, dest independently 1..128).  C, non-vararg, no musttail /
/// bundles / noreturn.  Integer results are not FPMathOperators; any
/// representable FMF is still rejected.  Legalized via
/// CallDescriptor.LegalizeBFloatMath — never as a native bfloat sat
/// intrinsic.
static bool isSupportedBFloatSatConvertIntrinsic(const CallInst &Call) {
  if (!isBFloatSatConvertShape(Call))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.getFunctionType()->isVarArg())
    return false;
  if (isa<FPMathOperator>(Call) && Call.getFastMathFlags().any())
    return false;
  return parentHasExplicitBF16Enabled(Call);
}

/// Shape only: llvm.is.fpclass from scalar bfloat to i1, or from a
/// supported fixed bfloat vector to a same-lane <N x i1>, plus an
/// i32 ConstantInt class mask.  Feature, ABI, ImmArg, and FMF are
/// checked by isSupportedBFloatFPClassIntrinsic.  Non-constant /
/// non-i32 masks, scalable, overwide, and constrained stay out.
static bool isBFloatFPClassShape(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::is_fpclass)
    return false;
  if (Call.arg_size() != 2)
    return false;
  const Value *Arg = Call.getArgOperand(0);
  const Value *Mask = Call.getArgOperand(1);
  if (!Arg || !Mask || !isSupportedOperand(Arg))
    return false;
  if (!Mask->getType()->isIntegerTy(32) || !isa<ConstantInt>(Mask))
    return false;
  Type *SrcTy = Arg->getType();
  Type *DstTy = Call.getType();
  if (isSupportedScalarBFloatType(SrcTy))
    return DstTy->isIntegerTy(1);
  if (!isSupportedBFloatVectorType(SrcTy) || !isSupportedI1VectorType(DstTy))
    return false;
  return cast<FixedVectorType>(SrcTy)->getNumElements() ==
         cast<FixedVectorType>(DstTy)->getNumElements();
}

/// last-token +bf16 llvm.is.fpclass on scalar bfloat or a supported
/// fixed bfloat vector.  The i32 class mask stays a CallDescriptor
/// ImmArg.  C, non-vararg, no musttail / bundles / noreturn.  Integer
/// results are not FPMathOperators; any representable FMF is still
/// rejected.  Legalized via CallDescriptor.LegalizeBFloatMath — never
/// as a native bfloat is.fpclass.
static bool isSupportedBFloatFPClassIntrinsic(const CallInst &Call) {
  if (!isBFloatFPClassShape(Call))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.getFunctionType()->isVarArg())
    return false;
  if (isa<FPMathOperator>(Call) && Call.getFastMathFlags().any())
    return false;
  if (!parentHasExplicitBF16Enabled(Call))
    return false;
  return isCallImmediateArgument(Call, 1);
}

/// Shape only: llvm.canonicalize on scalar bfloat or a supported
/// fixed bfloat vector (same-type single operand).  Feature, ABI, and
/// FMF are checked by isSupportedBFloatCanonicalizeIntrinsic.
static bool isBFloatCanonicalizeShape(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::canonicalize)
    return false;
  Type *Ty = Call.getType();
  if (!isSupportedScalarBFloatType(Ty) && !isSupportedBFloatVectorType(Ty))
    return false;
  if (Call.arg_size() != 1)
    return false;
  const Value *Arg = Call.getArgOperand(0);
  return Arg && Arg->getType() == Ty && isSupportedOperand(Arg);
}

/// last-token +bf16 llvm.canonicalize on scalar bfloat or a supported
/// fixed bfloat vector.  C, non-vararg, no musttail / bundles /
/// noreturn.  Any representable FastMathFlags are rejected.  Legalized
/// via CallDescriptor.LegalizeBFloatMath using the validated f32
/// fmul x, 1.0 lowering plus RNE — never as llvm.canonicalize.bf16
/// or llvm.canonicalize.f32.
static bool isSupportedBFloatCanonicalizeIntrinsic(const CallInst &Call) {
  if (!isBFloatCanonicalizeShape(Call))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.getFunctionType()->isVarArg())
    return false;
  return parentHasExplicitBF16Enabled(Call) &&
         bfloatVectorAllowsFastMathFlags(Call);
}

static bool isBFloatVectorReduceShape(const CallInst &Call);
static bool isBFloatMaskedMemoryShape(const CallInst &Call);

static bool isBFloatLegalizeIntrinsicShape(const CallInst &Call) {
  return isBFloatMathIntrinsicShape(Call) || isBFloatSatConvertShape(Call) ||
         isBFloatFPClassShape(Call) || isBFloatCanonicalizeShape(Call) ||
         isBFloatVectorReduceShape(Call) || isBFloatMaskedMemoryShape(Call);
}

/// Scalar llvm.copysign.f16/f32/f64 only (Intrinsic::copysign + matching
/// scalar half/float/double result/args).  C, exact non-vararg
/// FunctionType, formal type equality.  Ordinary tail, musttail, bundles,
/// noreturn, returns_twice, and complex ABI stay out.  Re-emitted through
/// the normal call handler; no dedicated VM opcode.  bfloat/vector/
/// constrained and other math intrinsics stay rejected.  Listed scalar
/// IEEE fp128 copysign uses isSupportedFP128CopySignIntrinsic.  Fast-math
/// forms are whitelisted by the intrinsic FMF gate (CallDescriptor mask).
static bool isSupportedCopySignIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::copysign)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedScalarFPType(ResultTy))
    return false;
  if (!isSupportedScalarFPMathCallSite(Call, ResultTy, 2))
    return false;
  for (unsigned Index = 0; Index < 2; ++Index) {
    if (!scalarFPMathFormalMatches(Call, Index, ResultTy) ||
        !isSupportedOrdinaryCallOperand(Call.getArgOperand(Index)))
      return false;
  }
  return isScalarHalfMathFeatureOK(Call, ResultTy);
}

/// Scalar llvm.minnum.f16/f32/f64 / llvm.maxnum.f16/f32/f64 only
