/// Scalar llvm.arithmetic.fence.f32/f64 only (Intrinsic::arithmetic_fence,
/// exactly one argument whose type matches the result, f32 or f64 only,
/// ordinary supported operand).  Re-emitted through the normal call handler
/// — never lowered to a Move or deleted: the fence blocks fast-math
/// reassociation across the point, and SelectionDAG lowers it to
/// TargetOpcode::ARITH_FENCE (a no-op comment in the asm stream).  Vector,
/// half/bfloat/fp128, wrong shape and other intrinsic forms stay rejected.
/// Fast-math llvm.arithmetic.fence.f32/f64 is explicitly whitelisted by the
/// intrinsic FMF gate (flags restored via the CallDescriptor mask);
/// musttail/operand bundles/noreturn/returns_twice/unsupported ABI
/// attributes are rejected here and again by the generic call gate.
static bool isSupportedArithmeticFenceIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::arithmetic_fence)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedScalarF32F64Type(ResultTy))
    return false;
  if (Call.arg_size() != 1)
    return false;
  const Value *Arg = Call.getArgOperand(0);
  return Arg->getType() == ResultTy &&
         isSupportedOrdinaryCallOperand(Arg);
}

