/// Shared shape for scalar float->i64 rounding intrinsics re-emitted as Call:
/// exact Intrinsic::ID, result strictly i64, single supported scalar f32 or
/// f64 arg.  C, exact non-vararg FunctionType, formal type equality.
/// Ordinary tail, musttail, bundles, noreturn, returns_twice, and complex
/// ABI stay out.  i32/other widths, half/vector, and constrained variants
/// stay out.
static bool isSupportedFloatToI64RoundIntrinsic(const CallInst &Call,
                                                Intrinsic::ID ExpectedID) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != ExpectedID)
    return false;
  // Result must be exactly i64 (not i32 or any other integer width).
  Type *ResultTy = Call.getType();
  if (!ResultTy || !ResultTy->isIntegerTy(64))
    return false;
  if (!isSupportedScalarFPMathCallSite(Call, ResultTy, 1))
    return false;
  const Value *Arg = Call.getArgOperand(0);
  return Arg && isSupportedScalarF32F64Type(Arg->getType()) &&
         scalarFPMathFormalMatches(Call, 0, Arg->getType()) &&
         isSupportedOrdinaryCallOperand(Arg);
}

/// Scalar llvm.lround.i64.f32/i64.f64 only (Intrinsic::lround).
/// Half-away-from-zero.  Re-emitted via normal call handler; no dedicated VM
/// opcode.
static bool isSupportedLRoundIntrinsic(const CallInst &Call) {
  return isSupportedFloatToI64RoundIntrinsic(Call, Intrinsic::lround);
}

/// Scalar llvm.llround.i64.f32/i64.f64 only (Intrinsic::llround).
/// Half-away-from-zero.  Re-emitted via normal call handler; no dedicated VM
/// opcode.
static bool isSupportedLLRoundIntrinsic(const CallInst &Call) {
  return isSupportedFloatToI64RoundIntrinsic(Call, Intrinsic::llround);
}

/// Scalar llvm.lrint.i64.f32/i64.f64 only (Intrinsic::lrint).  Current
/// rounding mode.  Re-emitted via normal call handler; no dedicated VM opcode.
static bool isSupportedLRintIntrinsic(const CallInst &Call) {
  return isSupportedFloatToI64RoundIntrinsic(Call, Intrinsic::lrint);
}

/// Scalar llvm.llrint.i64.f32/i64.f64 only (Intrinsic::llrint).  Current
/// rounding mode.  Re-emitted via normal call handler; no dedicated VM opcode.
static bool isSupportedLLRintIntrinsic(const CallInst &Call) {
  return isSupportedFloatToI64RoundIntrinsic(Call, Intrinsic::llrint);
}

/// Well-shaped scalar llvm.lround / llvm.llround / llvm.lrint /
/// llvm.llrint from IEEE half to i64.  No feature and no ABI.
/// Missing or last-token -fullfp16 reports "unsupported target
/// feature".  i32/other dest widths, bfloat/fp128, f32/f64, and
/// vectors stay generic.
static bool isScalarHalfFloatToI64RoundShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  if (ID != Intrinsic::lround && ID != Intrinsic::llround &&
      ID != Intrinsic::lrint && ID != Intrinsic::llrint)
    return false;
  if (!Call.getType()->isIntegerTy(64))
    return false;
  if (Call.arg_size() != 1)
    return false;
  const Value *Arg = Call.getArgOperand(0);
  return Arg && Arg->getType()->isHalfTy();
}

/// Restricted scalar llvm.lround.i64.f16 / llvm.llround.i64.f16 /
/// llvm.lrint.i64.f16 / llvm.llrint.i64.f16.  Re-emitted via
/// CallDescriptor / integer and float VRegs.  Requires last-token
/// function +fullfp16.  Does not change f32/f64 lround/llround/
/// lrint/llrint, half math, half sat, or add a VM opcode.  Ordinary
/// tail is not rejected here; musttail stays out.  No FastMathFlags
/// path (integer result).
static bool isSupportedHalfScalarFloatToI64RoundIntrinsic(
    const CallInst &Call) {
  if (!isScalarHalfFloatToI64RoundShapeSupported(Call))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.getFunctionType()->isVarArg())
    return false;
  const Function *Parent = Call.getFunction();
  if (!Parent || !functionHasExplicitFullFP16Enabled(*Parent))
    return false;
  return isSupportedOrdinaryCallOperand(Call.getArgOperand(0));
}

/// Listed scalar rounding / canonicalize / lround family / is.fpclass /
/// fptosi.sat / fptoui.sat IDs.  Vector / fp128 / bfloat / constrained
/// stay on their own helpers.
static bool isListedScalarFPHelperIntrinsicID(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::ceil:
  case Intrinsic::floor:
  case Intrinsic::trunc:
  case Intrinsic::round:
  case Intrinsic::rint:
  case Intrinsic::nearbyint:
  case Intrinsic::roundeven:
  case Intrinsic::canonicalize:
  case Intrinsic::lround:
  case Intrinsic::llround:
  case Intrinsic::lrint:
  case Intrinsic::llrint:
  case Intrinsic::is_fpclass:
  case Intrinsic::fptosi_sat:
  case Intrinsic::fptoui_sat:
    return true;
  default:
    return false;
  }
}

static const char *scalarFPHelperUnsupportedReason(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::ceil:
    return "unsupported ceil";
  case Intrinsic::floor:
    return "unsupported floor";
  case Intrinsic::trunc:
    return "unsupported trunc";
  case Intrinsic::round:
    return "unsupported round";
  case Intrinsic::rint:
    return "unsupported rint";
  case Intrinsic::nearbyint:
    return "unsupported nearbyint";
  case Intrinsic::roundeven:
    return "unsupported roundeven";
  case Intrinsic::canonicalize:
    return "unsupported canonicalize";
  case Intrinsic::lround:
    return "unsupported lround";
  case Intrinsic::llround:
    return "unsupported llround";
  case Intrinsic::lrint:
    return "unsupported lrint";
  case Intrinsic::llrint:
    return "unsupported llrint";
  case Intrinsic::is_fpclass:
    return "unsupported is.fpclass";
  case Intrinsic::fptosi_sat:
    return "unsupported fptosi.sat";
  case Intrinsic::fptoui_sat:
    return "unsupported fptoui.sat";
  default:
    return nullptr;
  }
}

/// Dedicated helper-family skips must not steal vector / fp128 / bfloat
/// surfaces or well-shaped half waiting on last-token +fullfp16.
static bool shouldDeferScalarFPHelperDedicatedSkip(const CallInst &Call,
                                                   const Function &F) {
  Type *Ty = Call.getType();
  if (Ty && (Ty->isVectorTy() || Ty->isFP128Ty() || Ty->isPPC_FP128Ty() ||
             Ty->isBFloatTy()))
    return true;
  if (Call.arg_size() >= 1) {
    Type *ArgTy = Call.getArgOperand(0)->getType();
    if (ArgTy && (ArgTy->isVectorTy() || ArgTy->isFP128Ty() ||
                  ArgTy->isPPC_FP128Ty() || ArgTy->isBFloatTy()))
      return true;
  }
  if (isScalarHalfPureMathShapeSupported(Call) &&
      !functionHasExplicitFullFP16Enabled(F))
    return true;
  if (isScalarHalfFPClassShapeSupported(Call) &&
      !functionHasExplicitFullFP16Enabled(F))
    return true;
  if (isScalarHalfSatConvertShapeSupported(Call) &&
      !functionHasExplicitFullFP16Enabled(F))
    return true;
  if (isScalarHalfFloatToI64RoundShapeSupported(Call) &&
      !functionHasExplicitFullFP16Enabled(F))
    return true;
  return false;
}

/// Scalar llvm.is.fpclass.f32/f64 only (Intrinsic::is_fpclass + i1 result,
/// scalar float/double operand, i32 ConstantInt immarg mask, exactly two
/// arguments).  C, exact non-vararg FunctionType, formal type equality.
/// Ordinary tail, musttail, bundles, noreturn, returns_twice, and complex
/// ABI stay out.  Re-emitted through the normal call handler; the immarg
/// mask travels on the CallDescriptor (ImmediateArguments) and stays a
/// true i32 constant on re-emit, never a VReg.  half/bfloat/vector
/// operands, non-constant or wrong-width masks, constrained and other
/// intrinsics stay rejected.  Listed scalar IEEE fp128 is.fpclass uses
/// isSupportedFP128FPClassIntrinsic.
static bool isSupportedFPClassIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::is_fpclass)
    return false;
  Type *ResultTy = Call.getType();
  if (!ResultTy || !ResultTy->isIntegerTy(1))
    return false;
  if (!isSupportedScalarFPMathCallSite(Call, ResultTy, 2))
    return false;
  const Value *Arg = Call.getArgOperand(0);
  const Value *Mask = Call.getArgOperand(1);
  if (!Arg || !Mask || !isSupportedScalarF32F64Type(Arg->getType()) ||
      !scalarFPMathFormalMatches(Call, 0, Arg->getType()) ||
      !isSupportedOrdinaryCallOperand(Arg))
    return false;
  Type *I32Ty = Type::getInt32Ty(Call.getContext());
  if (!scalarFPMathFormalMatches(Call, 1, I32Ty) ||
      !Mask->getType()->isIntegerTy(32) || !isa<ConstantInt>(Mask))
    return false;
  return isCallImmediateArgument(Call, 1);
}

/// Shared shape for scalar float->integer saturating conversion intrinsics
/// re-emitted as Call: exact Intrinsic::ID, result strictly ExpectedBitWidth,
/// single supported scalar f32 or f64 arg.  C, exact non-vararg FunctionType,
/// formal type equality.  Ordinary tail, musttail, bundles, noreturn,
/// returns_twice, and complex ABI stay out.  Other integer widths,
/// half/vector, and constrained variants stay out unless a wrapper opts
/// them in.
static bool isSupportedFloatToIntSatIntrinsic(const CallInst &Call,
                                              Intrinsic::ID ExpectedID,
                                              unsigned ExpectedBitWidth) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != ExpectedID)
    return false;
  Type *ResultTy = Call.getType();
  if (!ResultTy || !ResultTy->isIntegerTy(ExpectedBitWidth))
    return false;
  if (!isSupportedScalarFPMathCallSite(Call, ResultTy, 1))
    return false;
  const Value *Arg = Call.getArgOperand(0);
  return Arg && isSupportedScalarF32F64Type(Arg->getType()) &&
         scalarFPMathFormalMatches(Call, 0, Arg->getType()) &&
         isSupportedOrdinaryCallOperand(Arg);
}

/// Scalar llvm.fptosi.sat.i32.f32/i32.f64 only (Intrinsic::fptosi_sat, result
/// i32).  Saturating toward-zero signed conversion.  Re-emitted via normal
/// call handler; no dedicated VM opcode.
static bool isSupportedFPToSISatIntrinsic(const CallInst &Call) {
  return isSupportedFloatToIntSatIntrinsic(Call, Intrinsic::fptosi_sat, 32);
}

/// Scalar llvm.fptoui.sat.i32.f32/i32.f64 only (Intrinsic::fptoui_sat, result
/// i32).  Saturating toward-zero unsigned conversion (negative clamps to zero).
/// Re-emitted via normal call handler; no dedicated VM opcode.
static bool isSupportedFPToUISatIntrinsic(const CallInst &Call) {
  return isSupportedFloatToIntSatIntrinsic(Call, Intrinsic::fptoui_sat, 32);
}

/// Scalar llvm.fptosi.sat.i64.f32/i64.f64 only (Intrinsic::fptosi_sat, result
/// strictly i64).  Saturating toward-zero signed conversion.  Re-emitted via
/// normal call handler; no dedicated VM opcode.  Other widths, half/
/// vector, and constrained variants stay rejected here; i8/i16 use the
/// narrow wrappers below.
static bool isSupportedFPToSISatI64Intrinsic(const CallInst &Call) {
  return isSupportedFloatToIntSatIntrinsic(Call, Intrinsic::fptosi_sat, 64);
}

/// Scalar llvm.fptoui.sat.i64.f32/i64.f64 only (Intrinsic::fptoui_sat, result
/// strictly i64).  Saturating toward-zero unsigned conversion (negative clamps
/// to zero).  Re-emitted via normal call handler; no dedicated VM opcode.
/// Other widths, half/vector, and constrained variants stay rejected here;
/// i8/i16 use the narrow wrappers below.
static bool isSupportedFPToUISatI64Intrinsic(const CallInst &Call) {
  return isSupportedFloatToIntSatIntrinsic(Call, Intrinsic::fptoui_sat, 64);
}

/// Scalar llvm.fptosi.sat / llvm.fptoui.sat from f32/f64 to i8 or i16.
/// Re-emitted via CallDescriptor.  Does not change vector sat convert,
/// ordinary fptosi/fptoui, or the half feature gate.  C, exact
/// non-vararg FunctionType, formal type equality, and ordinary-tail
/// rejection come from isSupportedFloatToIntSatIntrinsic.  No dedicated
/// VM opcode.
static bool isSupportedNarrowFPToIntSatIntrinsic(const CallInst &Call,
                                                 Intrinsic::ID ExpectedID) {
  return isSupportedFloatToIntSatIntrinsic(Call, ExpectedID, 8) ||
         isSupportedFloatToIntSatIntrinsic(Call, ExpectedID, 16);
}

static bool isSupportedFPToSISatNarrowIntrinsic(const CallInst &Call) {
  return isSupportedNarrowFPToIntSatIntrinsic(Call, Intrinsic::fptosi_sat);
}

static bool isSupportedFPToUISatNarrowIntrinsic(const CallInst &Call) {
  return isSupportedNarrowFPToIntSatIntrinsic(Call, Intrinsic::fptoui_sat);
}

/// Fold llvm.objectsize at VMP time on the original pointer.
///
/// CallDescriptor replay is unsound: the interpreter reloads the
/// pointer from a VReg, so ObjectSizeOffsetVisitor can no longer see
/// the alloca/global and a known size becomes LangRef-unknown (0/-1).
/// Host IntrinsicLowering has no objectsize case (lli fatals).
///
/// Only the LangRef i32/i64 AS0 static form is accepted, and only
/// when LLVM 15 getObjectSize / specified-null rules produce a
/// definite integer.  dynamic=true stays out (ObjectSizeOffsetEvaluator
/// may insert runtime IR).  Analysis failure (argument, inttoptr,
/// load, malloc without TLI, nonzero AS) is a skip — never MustSucceed
/// 0/-1.  AS0 null is LangRef-specified: 0 if nullunknown=false, else
/// 0/-1 from min.  EvalMode is Min/Max from the min ImmArg so select/
/// phi of two known objects honors min.  RoundToAlign stays false
/// (same as lowerObjectSizeCall).  Size uses Module DataLayout
/// getTypeAllocSize.
static ConstantInt *evaluateObjectSizeConstant(const CallInst &Call) {
  if (Call.getIntrinsicID() != Intrinsic::objectsize)
    return nullptr;
  IntegerType *Ty = dyn_cast<IntegerType>(Call.getType());
  if (!Ty || (Ty->getBitWidth() != 32 && Ty->getBitWidth() != 64))
    return nullptr;
  if (Call.arg_size() != 4)
    return nullptr;
  const Value *Ptr = Call.getArgOperand(0);
  const auto *MinC = dyn_cast<ConstantInt>(Call.getArgOperand(1));
  const auto *NullC = dyn_cast<ConstantInt>(Call.getArgOperand(2));
  const auto *DynC = dyn_cast<ConstantInt>(Call.getArgOperand(3));
  if (!Ptr || !MinC || !NullC || !DynC || !MinC->getType()->isIntegerTy(1) ||
      !NullC->getType()->isIntegerTy(1) || !DynC->getType()->isIntegerTy(1))
    return nullptr;
  if (DynC->isOne())
    return nullptr;
  const bool Min = MinC->isOne();
  const bool NullUnknown = NullC->isOne();
  if (isa<ConstantPointerNull>(Ptr) && isSupportedPointerType(Ptr->getType())) {
    if (NullUnknown)
      return Min ? ConstantInt::get(Ty, 0) : cast<ConstantInt>(
                                                 ConstantInt::getAllOnesValue(Ty));
    return ConstantInt::get(Ty, 0);
  }
  const Function *Fn = Call.getFunction();
  if (!Fn || !Fn->getParent())
    return nullptr;
  const DataLayout &DL = Fn->getParent()->getDataLayout();
  ObjectSizeOpts Opts;
  Opts.EvalMode =
      Min ? ObjectSizeOpts::Mode::Min : ObjectSizeOpts::Mode::Max;
  Opts.NullIsUnknownSize = NullUnknown;
  uint64_t Size = 0;
  if (!getObjectSize(Ptr, Size, DL, /*TLI=*/nullptr, Opts))
    return nullptr;
  if (!isUIntN(Ty->getBitWidth(), Size))
    return nullptr;
  return ConstantInt::get(Ty, Size);
}

/// Scalar llvm.objectsize only when evaluateObjectSizeConstant succeeds.
/// Planned as Move of that constant (not CallDescriptor, never
/// re-emitted).  Ordinary tail is not rejected here.
static bool isSupportedObjectSizeIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::objectsize)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  Type *ResultTy = Call.getType();
  if (!ResultTy->isIntegerTy(32) && !ResultTy->isIntegerTy(64))
    return false;
  if (Call.arg_size() != 4)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 4)
    return false;
  const Value *Ptr = Call.getArgOperand(0);
  if (!Ptr || !isSupportedPointerType(Ptr->getType()) ||
      Ptr->getType() != FTy->getParamType(0) || !isSupportedOperand(Ptr))
    return false;
  for (unsigned Index = 1; Index < 4; ++Index) {
    if (!FTy->getParamType(Index)->isIntegerTy(1))
      return false;
    const auto *Flag = dyn_cast<ConstantInt>(Call.getArgOperand(Index));
    if (!Flag || !Flag->getType()->isIntegerTy(1))
      return false;
  }
  return evaluateObjectSizeConstant(Call) != nullptr;
}

/// Scalar llvm.ptrmask.p0.i64 only (Intrinsic::ptrmask, AS0 pointer result and
/// arg0, strictly i64 mask).  Re-emitted through the normal call handler using
/// existing pointer and integer virtual registers; no dedicated VM opcode.
/// i32/other mask widths, non-AS0 pointers, and other forms stay rejected.
static bool isSupportedPtrMaskIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::ptrmask)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedPointerType(ResultTy))
    return false;
  if (Call.arg_size() != 2)
    return false;
  const Value *Ptr = Call.getArgOperand(0);
  if (Ptr->getType() != ResultTy || !isSupportedOrdinaryCallOperand(Ptr))
    return false;
  const Value *Mask = Call.getArgOperand(1);
  // Mask must be exactly i64.
  if (!Mask->getType()->isIntegerTy(64) ||
      !isSupportedOrdinaryCallOperand(Mask))
    return false;
  return true;
}

/// Shared shape for scalar AS0 llvm.launder.invariant.group /
/// llvm.strip.invariant.group.  LangRef: the result aliases the
/// argument and is not a runtime memory operation (speculatable;
/// launder is inaccessiblememonly so two launders of the same pointer
/// do not CSE; strip is readnone).  ISel / CodeGenPrepare / FastISel
/// drop both to identity.  Host IntrinsicLowering has no case and
/// fatals, so these must not be CallDescriptor-replayed.
///
/// Accept only exact scalar AS0 pointer identity: one non-poison /
/// non-undef pointer operand and result, matching FunctionType, C,
/// non-vararg.  LLVM 15 DefaultAttrs puts nocallback on the
/// declaration; rejecting that attribute would close the surface.
/// User noreturn / returns_twice / musttail / bundles / complex ABI /
/// non-C / nonzero address spaces stay out.  Ordinary tail is not
/// rejected here.
static bool isSupportedAS0PointerIdentityIntrinsic(const CallInst &Call,
                                                   Intrinsic::ID ExpectedID) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != ExpectedID)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.arg_size() != 1)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedPointerType(ResultTy))
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 1 || FTy->getParamType(0) != ResultTy)
    return false;
  const Value *Ptr = Call.getArgOperand(0);
  if (!Ptr || Ptr->getType() != ResultTy || !isSupportedOperand(Ptr))
    return false;
  return true;
}

/// Scalar llvm.launder.invariant.group only.  Planned as PointerMove
/// of operand 0 into the pointer VReg (not CallDescriptor, never
/// re-emitted).  Debug locations stay on subsequent memory ops via
/// MemoryDescriptor; the shared PointerMove handler has no per-op
/// location (same as integer Move).
static bool isSupportedLaunderInvariantGroupIntrinsic(const CallInst &Call) {
  return isSupportedAS0PointerIdentityIntrinsic(
      Call, Intrinsic::launder_invariant_group);
}

/// Scalar llvm.strip.invariant.group only.  Same PointerMove lowering
/// as launder; never CallDescriptor.
static bool isSupportedStripInvariantGroupIntrinsic(const CallInst &Call) {
  return isSupportedAS0PointerIdentityIntrinsic(
      Call, Intrinsic::strip_invariant_group);
}

static bool isInvariantGroupPointerMoveIntrinsic(const CallInst &Call) {
  return isSupportedLaunderInvariantGroupIntrinsic(Call) ||
         isSupportedStripInvariantGroupIntrinsic(Call);
}

/// Shared call-safety for a droppable invariant.start / end marker.
/// Ordinary tail is allowed.  musttail / bundles / noreturn /
/// returns_twice / complex ABI / non-C / vararg stay out.
static bool isInvariantMarkerCallSafe(const CallInst &Call) {
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  return FTy && !FTy->isVarArg();
}

/// Shape-only llvm.invariant.end (does not require a droppable start).
static bool isWellFormedInvariantEndShape(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::invariant_end)
    return false;
  if (!isInvariantMarkerCallSafe(Call))
    return false;
  if (Call.arg_size() != 3 || !Call.getType()->isVoidTy())
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->getNumParams() != 3 || !FTy->getReturnType()->isVoidTy() ||
      !FTy->getParamType(1)->isIntegerTy(64))
    return false;
  const Value *Scope = Call.getArgOperand(0);
  const Value *Size = Call.getArgOperand(1);
  const Value *Data = Call.getArgOperand(2);
  if (!Scope || !isSupportedPointerType(Scope->getType()) ||
      Scope->getType() != FTy->getParamType(0) || isa<UndefValue>(Scope) ||
      isa<PoisonValue>(Scope))
    return false;
  if (!Size || !Size->getType()->isIntegerTy(64) || !isa<ConstantInt>(Size))
    return false;
  if (!Data || !isSupportedPointerType(Data->getType()) ||
      Data->getType() != FTy->getParamType(2) || !isSupportedOperand(Data))
    return false;
  return true;
}

/// Shape-only llvm.invariant.start (does not inspect users).
static bool isWellFormedInvariantStartShape(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::invariant_start)
    return false;
  if (!isInvariantMarkerCallSafe(Call))
    return false;
  if (Call.arg_size() != 2)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedPointerType(ResultTy))
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->getNumParams() != 2 || FTy->getReturnType() != ResultTy ||
      !FTy->getParamType(0)->isIntegerTy(64) ||
      FTy->getParamType(1) != ResultTy)
    return false;
  const Value *Size = Call.getArgOperand(0);
  const Value *Data = Call.getArgOperand(1);
  if (!Size || !Size->getType()->isIntegerTy(64) || !isa<ConstantInt>(Size))
    return false;
  if (!Data || !isSupportedPointerType(Data->getType()) ||
      Data->getType() != FTy->getParamType(1) || !isSupportedOperand(Data))
    return false;
  return true;
}

/// Token does not escape: every non-dbg user is a well-formed end.
static bool invariantStartTokenIsLocal(const CallInst &Start) {
  for (const User *U : Start.users()) {
    if (const auto *UI = dyn_cast<Instruction>(U)) {
      if (isa<DbgInfoIntrinsic>(UI))
        continue;
    }
    const auto *UC = dyn_cast<CallInst>(U);
    if (!UC || !isWellFormedInvariantEndShape(*UC))
      return false;
  }
  return true;
}

/// LangRef: start/end are unchanging/mutable markers, not runtime
/// memory ops.  ISel and IntrinsicLowering discard them (start →
/// undef).  Safe to consume without replay in the post-opt interpreter
/// iff the token does not escape.  CallDescriptor replay would invent
/// interpreter calls whose !invariant.load / scoped-AA metadata on
/// shared handlers would be invalid.  applyMetadata strips those kinds.
static bool isDroppableInvariantMarker(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  if (ID == Intrinsic::invariant_start)
    return isWellFormedInvariantStartShape(Call) &&
           invariantStartTokenIsLocal(Call);
  if (ID == Intrinsic::invariant_end) {
    if (!isWellFormedInvariantEndShape(Call))
      return false;
    const auto *Start = dyn_cast<CallInst>(Call.getArgOperand(0));
    return Start && isWellFormedInvariantStartShape(*Start) &&
           invariantStartTokenIsLocal(*Start);
  }
  return false;
}

/// Compile-time annotation operand: AS0 pointer that is a supported
/// pointer Constant (null, GlobalValue, blockaddress, GEP/bitcast of
/// those) or a constant-index GEP/bitcast instruction of one.  Clang
/// emits in-function GEPs of private unnamed_addr string globals, not
/// ConstantExprs.  Runtime SSA, poison/undef, inttoptr, loads, and
/// nonzero address spaces stay out so we never drop a non-constant
/// string / extra-arg pointer.
static bool isCompileTimeAnnotationPointer(const Value *V) {
  if (!V || !isSupportedPointerType(V->getType()))
    return false;
  if (isa<UndefValue>(V) || isa<PoisonValue>(V))
    return false;
  if (const auto *C = dyn_cast<Constant>(V))
    return isSupportedPointerConstant(C);
  if (const auto *GEP = dyn_cast<GetElementPtrInst>(V)) {
    if (!GEP->hasAllConstantIndices())
      return false;
    return isCompileTimeAnnotationPointer(GEP->getPointerOperand());
  }
  if (const auto *BC = dyn_cast<BitCastInst>(V))
    return isCompileTimeAnnotationPointer(BC->getOperand(0));
  return false;
}

/// Scalar AS0 llvm.ptr.annotation only.  LangRef: returns operand 0;
/// ISel / IntrinsicLowering drop the call and forward the pointer.
/// Annotation text, unit, i32 line, and the LLVM 15 extra arg pointer
/// are discarded only when they are compile-time constants (frontend
/// unnamed_addr string GEPs / null / ConstantInt line / optional
/// constant args struct).  Planned as PointerMove of arg0 — never
/// CallDescriptor.  Non-constant or escaped strings, nonzero AS,
/// poison/undef, musttail / bundles / noreturn / returns_twice /
/// complex ABI / non-C / vararg stay out.  llvm.annotation /
/// llvm.var.annotation / codeview.annotation are not opened here.
static bool isSupportedPtrAnnotationIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::ptr_annotation)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.arg_size() != 5)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedPointerType(ResultTy))
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 5)
    return false;
  const Value *Ptr = Call.getArgOperand(0);
  if (!Ptr || Ptr->getType() != ResultTy ||
      Ptr->getType() != FTy->getParamType(0) || !isSupportedOperand(Ptr))
    return false;
  for (unsigned Index : {1u, 2u, 4u}) {
    const Value *Arg = Call.getArgOperand(Index);
    if (!Arg || !isSupportedPointerType(Arg->getType()) ||
        Arg->getType() != FTy->getParamType(Index) ||
        !isCompileTimeAnnotationPointer(Arg))
      return false;
  }
  const auto *Line = dyn_cast<ConstantInt>(Call.getArgOperand(3));
  if (!Line || !Line->getType()->isIntegerTy(32) ||
      !FTy->getParamType(3)->isIntegerTy(32))
    return false;
  return true;
}

/// Address-space-zero llvm.var.annotation only.  LangRef: annotates a
/// local with strings; ignored by codegen and optimization.  ISel,
/// FastISel-adjacent IRTranslator, and IntrinsicLowering discard it
/// (void; no forwarded value).  Consumed as a no-op marker like
/// lifetime — never CallDescriptor.  The annotated AS0 data pointer is
/// a supported operand (typically an alloca).  Annotation text, unit,
/// extra arg, and i32 line must be compile-time constants so dropping
/// the call cannot discard a runtime-side-effect expression.  Ordinary
/// tail is a hint; musttail, bundles, noreturn,
/// returns_twice, complex ABI, non-C, and vararg stay out.
/// llvm.annotation / codeview.annotation are not opened here.
static bool isDroppableVarAnnotation(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::var_annotation)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (!Call.getType()->isVoidTy() || Call.arg_size() != 5)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || !FTy->getReturnType()->isVoidTy() ||
      FTy->getNumParams() != 5)
    return false;
  const Value *Data = Call.getArgOperand(0);
  if (!Data || !isSupportedPointerType(Data->getType()) ||
      Data->getType() != FTy->getParamType(0) || !isSupportedOperand(Data))
    return false;
  for (unsigned Index : {1u, 2u, 4u}) {
    const Value *Arg = Call.getArgOperand(Index);
    if (!Arg || !isSupportedPointerType(Arg->getType()) ||
        Arg->getType() != FTy->getParamType(Index) ||
        !isCompileTimeAnnotationPointer(Arg))
      return false;
  }
  const auto *Line = dyn_cast<ConstantInt>(Call.getArgOperand(3));
  if (!Line || !Line->getType()->isIntegerTy(32) ||
      !FTy->getParamType(3)->isIntegerTy(32))
    return false;
  return true;
}

/// Scalar llvm.annotation only.  LangRef: returns operand 0; ISel and
/// IntrinsicLowering drop the call and forward the integer.  Result and
/// arg0 are the same VMP scalar integer (i1/i8/i16/i32/i64 or restricted
/// i128).  Annotation text, unit, and i32 line are discarded only when
/// they are compile-time constants.  Planned as Move of arg0 into the
/// matching integer / i128 VReg — never CallDescriptor.  Pointers /
/// floats / vectors, i2/other widths, runtime or escaped strings, tail /
/// musttail, bundles, noreturn, returns_twice, complex ABI, non-C, and
/// vararg stay out.  ptr.annotation / var.annotation are separate
/// surfaces.  i128 is not folded into isSupportedIntegerType.
static bool isSupportedAnnotationIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::annotation)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.arg_size() != 4)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedScalarIntegerType(ResultTy))
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 4 || FTy->getParamType(0) != ResultTy)
    return false;
  const Value *AnnotatedValue = Call.getArgOperand(0);
  if (!AnnotatedValue || AnnotatedValue->getType() != ResultTy ||
      !isSupportedOperand(AnnotatedValue))
    return false;
  const Value *Text = Call.getArgOperand(1);
  const Value *Unit = Call.getArgOperand(2);
  if (!Text || !isSupportedPointerType(Text->getType()) ||
      Text->getType() != FTy->getParamType(1) ||
      !isCompileTimeAnnotationPointer(Text))
    return false;
  if (!Unit || !isSupportedPointerType(Unit->getType()) ||
      Unit->getType() != FTy->getParamType(2) ||
      !isCompileTimeAnnotationPointer(Unit))
    return false;
  const auto *Line = dyn_cast<ConstantInt>(Call.getArgOperand(3));
  if (!Line || !Line->getType()->isIntegerTy(32) ||
      !FTy->getParamType(3)->isIntegerTy(32))
    return false;
  return true;
}

/// Scalar llvm.clear_cache only.  LangRef: make [begin, end) visible
/// to the execution unit.  On AArch64 (split I/D cache) ISel lowers
/// the intrinsic to the __clear_cache libcall; it is not a no-op.
/// Replayed via CallDescriptor: original Function*, FunctionType
/// void(ptr, ptr), C calling convention, AttributeList, DebugLoc and
/// remaining metadata, both range pointers from the pointer VReg
/// frame.  Ordinary tail is accepted and lowered as a normal call
/// (CreateCall is TCK_None).  musttail / bundles / noreturn /
/// returns_twice / complex ABI / non-C / vararg / poison / undef /
/// non-AS0 stay out.  Never dropped, never replaced by a Move.
static bool isSupportedClearCacheIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::clear_cache)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (!Call.getType()->isVoidTy() || Call.arg_size() != 2)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || !FTy->getReturnType()->isVoidTy() ||
      FTy->getNumParams() != 2)
    return false;
  for (unsigned Index = 0; Index < 2; ++Index) {
    const Value *Ptr = Call.getArgOperand(Index);
    if (!Ptr || !isSupportedPointerType(Ptr->getType()) ||
        Ptr->getType() != FTy->getParamType(Index) ||
        !isSupportedOperand(Ptr))
      return false;
  }
  return true;
}

/// Scalar llvm.thread.pointer only.  LangRef: pointer to the current
/// thread's TLS area (target-specific).  AArch64 ISel lowers it to
/// AArch64ISD::THREAD_POINTER / MRS TPIDR_EL0.  Never folded to a
/// constant or global: replayed via CallDescriptor (original
/// Function*, FunctionType ptr(), C, AttributeList, DebugLoc) with
/// the result stored in the pointer VReg frame.  Zero args.
/// musttail / bundles / noreturn / returns_twice / complex ABI /
/// non-C / vararg / non-AS0 result stay out.  Host IntrinsicLowering
/// has no case (lli fatals); do not pre-constantize.
static bool isSupportedThreadPointerIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::thread_pointer)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.arg_size() != 0)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedPointerType(ResultTy))
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 0)
    return false;
  return true;
}

/// Exact llvm.get.dynamic.area.offset.i64 only (Intrinsic::
/// get_dynamic_area_offset, result strictly i64, zero args, C).
/// LangRef: offset from native SP to the most recent dynamic alloca;
/// most targets (including AArch64 / x86_64) lower it to zero, PowerPC
/// to a compile-time constant.  Never pre-folded to 0 / Move: replayed
/// via CallDescriptor (original Function*, FunctionType i64(), C,
/// AttributeList, DebugLoc) with the i64 result stored in the integer
/// VReg frame so target lowering stays the source of truth.
/// Entry dynamic alloca in the same function is rejected earlier as
/// "dynamic stack state".  stacksave / stackrestore without a dynamic
/// alloca may coexist.  i32 / other widths, extra args, ordinary tail, musttail,
/// bundles, noreturn, returns_twice, non-C, vararg, and complex ABI
/// stay out.
static bool isSupportedDynamicAreaOffsetIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::get_dynamic_area_offset)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.arg_size() != 0)
    return false;
  Type *ResultTy = Call.getType();
  if (!ResultTy || !ResultTy->isIntegerTy(64))
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 0)
    return false;
  return true;
}

/// Exact llvm.returnaddress(i32 0) only (Intrinsic::returnaddress, AS0
/// pointer result, exactly one argument that must be an i32 ConstantInt
/// with the strict value 0 AND carry the ImmArg parameter attribute — the
/// strict shape is required defensively because isCallImmediateArgument
/// keys the true-immediate preservation on that ImmArg attribute, and a
/// non-canonical declaration/call would otherwise route the depth through
/// virtual registers and the backend would no longer see the level
/// immediate; AArch64 LowerRETURNADDR does cast<ConstantSDNode>).
/// Depth 0 is the current function's incoming LR.  VMP rewrites this
/// function in place (interpreter + VReg allocas); post-CFF also stays
/// in the same Function, so depth 0 still names this function's saved
/// LR and must be replayed as the original intrinsic — never folded or
/// synthesized.  Depth > 0 walks the FP chain and is not trustworthy
/// after VMP/CFF frame changes.  Dynamic / poison / undef depth, non-C,
/// vararg, non-AS0, musttail, bundles, noreturn, returns_twice, and
/// complex ABI stay out.  Ordinary tail is accepted and demoted.
static bool isSupportedReturnAddressIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::returnaddress)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedPointerType(ResultTy))
    return false;
  if (Call.arg_size() != 1)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 1 || !FTy->getParamType(0)->isIntegerTy(32))
    return false;
  const Value *Depth = Call.getArgOperand(0);
  if (!Depth || Depth->getType() != FTy->getParamType(0) ||
      !Call.paramHasAttr(0, Attribute::ImmArg))
    return false;
  const auto *DepthCI = dyn_cast<ConstantInt>(Depth);
  return DepthCI && DepthCI->isZero();
}

/// Exact llvm.frameaddress(i32 0) only (Intrinsic::frameaddress, AS0
/// pointer result, exact non-vararg FunctionType ptr(i32), C).
/// Depth must be an i32 ConstantInt 0 with the ImmArg parameter
/// attribute — isCallImmediateArgument keys true-immediate preservation
/// on that attribute, and AArch64 LowerFRAMEADDR does
/// cast<ConstantSDNode>.  Depth 0 is this function's FP (x29).  VMP
/// rewrites the function in place and post-CFF stays in the same
/// Function, so depth 0 still names this function's FP and must be
/// replayed as the original intrinsic — never folded or synthesized.
/// Depth > 0 walks the FP chain and is not trustworthy after VMP/CFF
/// frame changes.  Dynamic / poison / undef depth, non-C, vararg,
/// non-AS0 (including .p1), ordinary tail, musttail, bundles,
/// noreturn, returns_twice, and complex ABI stay out.
static bool isSupportedFrameAddressIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::frameaddress)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedPointerType(ResultTy))
    return false;
  if (Call.arg_size() != 1)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 1 || !FTy->getParamType(0)->isIntegerTy(32))
    return false;
  const Value *Depth = Call.getArgOperand(0);
  if (!Depth || Depth->getType() != FTy->getParamType(0) ||
      !Call.paramHasAttr(0, Attribute::ImmArg))
    return false;
  const auto *DepthCI = dyn_cast<ConstantInt>(Depth);
  return DepthCI && DepthCI->isZero();
}

/// Exact llvm.addressofreturnaddress only (Intrinsic::
/// addressofreturnaddress, AS0 pointer result, exact non-vararg
/// FunctionType ptr(), C, zero args).  LangRef: target-specific pointer
/// to the current function's return-address slot (AArch64 / x86).
/// AArch64 LowerADDROFRETURNADDR is FP+8.  VMP rewrites this function
/// in place, so the slot is this function's saved LR slot and must be
/// replayed as the original intrinsic — never folded or synthesized.
/// Ordinary tail, musttail, bundles, noreturn, returns_twice, non-C,
/// vararg, non-AS0 (including .p1), and complex ABI stay out.
static bool isSupportedAddressOfReturnAddressIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::addressofreturnaddress)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedPointerType(ResultTy))
    return false;
  if (Call.arg_size() != 0)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 0)
    return false;
  return true;
}

/// Exact llvm.sponentry only (Intrinsic::sponentry, AS0 pointer result,
/// exact non-vararg FunctionType ptr(), C, zero args).  LangRef: stack
/// pointer at entry of the current function; verified only on
/// AArch64/ARM.  AArch64 LowerSPONENTRY is a fixed frame object at
/// offset 0 (entry SP).  VMP rewrites this function in place, so the
/// value is this function's entry SP and must be replayed as the
/// original intrinsic — never precomputed or replaced by a constant.
/// Ordinary tail, musttail, bundles, noreturn, returns_twice, non-C,
