static bool isSupportedSPOnEntryIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::sponentry)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedPointerType(ResultTy))
    return false;
  if (Call.arg_size() != 0)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 0)
    return false;
  return true;
}

/// Exact llvm.stackguard only (Intrinsic::stackguard, AS0 pointer
/// result, exact non-vararg FunctionType ptr(), C, zero args).
/// LangRef: system stack-guard cookie (often @__stack_chk_guard).
/// VMP does not insert that symbol or ssp attributes; the call is
/// replayed via CallDescriptor so AArch64 LOAD_STACK_GUARD still sees
/// the intrinsic — never precomputed or replaced by a constant.
/// Ordinary tail, musttail, bundles, noreturn, returns_twice, non-C,
/// vararg, non-AS0, and complex ABI stay out.
static bool isSupportedStackGuardIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::stackguard)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedPointerType(ResultTy))
    return false;
  if (Call.arg_size() != 0)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 0)
    return false;
  return true;
}

/// Exact llvm.stacksave / llvm.stackrestore only (Intrinsic::stacksave or
/// stackrestore).  Narrow safe forms, C, non-vararg:
/// - stacksave: FunctionType ptr(), zero args, AS0 pointer result
/// - stackrestore: FunctionType void(ptr), exactly one AS0 pointer
///   ordinary operand whose type equals the formal param
/// Both are re-emitted via CallDescriptor / emitCallHandler.  The
/// saved pointer travels through the pointer VReg frame — never
/// precomputed, never replaced by a constant, never a new opcode.
/// Restricted entry dynamic alloca cannot share a function with these
/// (late "dynamic stack state").  Ordinary tail, musttail, bundles, noreturn,
/// returns_twice, non-C, vararg, non-AS0, and complex ABI stay out.
static bool isSupportedStackSaveRestoreIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  if (ID != Intrinsic::stacksave && ID != Intrinsic::stackrestore)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg())
    return false;
  if (ID == Intrinsic::stacksave) {
    Type *ResultTy = Call.getType();
    if (!isSupportedPointerType(ResultTy) || Call.arg_size() != 0)
      return false;
    return FTy->getReturnType() == ResultTy && FTy->getNumParams() == 0;
  }
  if (!Call.getType()->isVoidTy() || !FTy->getReturnType()->isVoidTy() ||
      Call.arg_size() != 1 || FTy->getNumParams() != 1)
    return false;
  const Value *Ptr = Call.getArgOperand(0);
  Type *ParamTy = FTy->getParamType(0);
  return Ptr && Ptr->getType() == ParamTy &&
         isSupportedPointerType(Ptr->getType()) &&
         isSupportedOrdinaryCallOperand(Ptr);
}

/// Exact llvm.stackprotector only (Intrinsic::stackprotector).
/// Narrow safe form: C, non-vararg FunctionType void(ptr, ptr),
/// exactly two arguments with formal type equality:
/// - arg0 is the cookie: AS0 ordinary pointer (not poison/undef)
/// - arg1 is the slot: same-function static AS0 alloca of a pointer
/// Re-emitted via CallDescriptor / VMOpcode::Call.  The cookie (arg0)
/// travels through the pointer VReg frame.  The slot (arg1) is the
/// interpreter-created static AllocaInst (the verifier requires an
/// alloca, not a VReg load).  VMP does not insert __stack_chk_guard
/// or ssp / sspstrong / sspreq; those function attributes are kept
/// so AArch64 ISel can emit __stack_chk_fail.  No new opcode.
/// Ordinary tail, musttail, bundles, noreturn, returns_twice, non-C,
/// vararg, non-AS0, dynamic-alloca slots, and complex ABI stay out.
static bool isSupportedStackProtectorIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::stackprotector)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  Type *ResultTy = Call.getType();
  if (!ResultTy->isVoidTy() || Call.arg_size() != 2)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 2)
    return false;
  const Value *Guard = Call.getArgOperand(0);
  const Value *Slot = Call.getArgOperand(1);
  if (!Guard || Guard->getType() != FTy->getParamType(0) ||
      !isSupportedPointerType(Guard->getType()) ||
      !isSupportedOrdinaryCallOperand(Guard))
    return false;
  if (!Slot || Slot->getType() != FTy->getParamType(1) ||
      !isSupportedPointerType(Slot->getType()) ||
      !isSupportedOrdinaryCallOperand(Slot))
    return false;
  const auto *AI = dyn_cast<AllocaInst>(Slot->stripPointerCasts());
  if (!AI || AI->getFunction() != Call.getFunction())
    return false;
  if (AI->isSwiftError() || AI->isUsedWithInAlloca() || !AI->isStaticAlloca())
    return false;
  if (AI->getAddressSpace() != 0 ||
      !isSupportedPointerType(AI->getAllocatedType()))
    return false;
  return true;
}

/// Exact llvm.va_start / llvm.va_end (Intrinsic::vastart / vaend).
/// Narrow safe form: C, non-vararg FunctionType void(ptr), exactly
/// one AS0 pointer ordinary operand whose type equals the formal
/// param.  Re-emitted via CallDescriptor / emitCallHandler.  The list
/// address travels through the pointer VReg frame — never precomputed.
/// Function-level analysis still owns one-list / two-list lifecycle.
/// Ordinary tail, musttail, bundles, noreturn, returns_twice, non-C,
/// vararg FTy, non-AS0, and complex ABI stay out.
static bool isSupportedVAStartEndIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  if (ID != Intrinsic::vastart && ID != Intrinsic::vaend)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  Type *ResultTy = Call.getType();
  if (!ResultTy->isVoidTy() || Call.arg_size() != 1)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 1)
    return false;
  const Value *Ptr = Call.getArgOperand(0);
  Type *ParamTy = FTy->getParamType(0);
  return Ptr && Ptr->getType() == ParamTy &&
         isSupportedPointerType(Ptr->getType()) &&
         isSupportedOrdinaryCallOperand(Ptr);
}

/// Exact llvm.va_copy (Intrinsic::vacopy).  C, non-vararg FunctionType
/// void(ptr, ptr), exactly two distinct AS0 pointer ordinary operands
/// (dest, src) with formal type equality.  Re-emitted via CallDescriptor.
/// Function-level analysis still owns the two-list lifecycle.  dest ==
/// src, ordinary tail, musttail, bundles, noreturn, returns_twice,
/// non-C, vararg FTy, non-AS0, and complex ABI stay out.
static bool isSupportedVACopyIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::vacopy)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  Type *ResultTy = Call.getType();
  if (!ResultTy->isVoidTy() || Call.arg_size() != 2)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 2)
    return false;
  const Value *Dest = Call.getArgOperand(0);
  const Value *Src = Call.getArgOperand(1);
  if (!Dest || !Src || Dest == Src)
    return false;
  if (Dest->getType() != FTy->getParamType(0) ||
      Src->getType() != FTy->getParamType(1))
    return false;
  return isSupportedPointerType(Dest->getType()) &&
         isSupportedOrdinaryCallOperand(Dest) &&
         isSupportedPointerType(Src->getType()) &&
         isSupportedOrdinaryCallOperand(Src);
}

/// Exact llvm.localaddress only (Intrinsic::localaddress, AS0 pointer
/// result, exact non-vararg FunctionType ptr(), C, zero args).
/// LangRef: address of the current function's local variable area.
/// AArch64 lowering is CopyFromReg of getLocalAddressRegister (SP when
/// there are no EH funclets and no var-sized objects, else base/FP).
/// Replayed via CallDescriptor into the pointer VReg — never
/// synthesized or replaced by a constant.  localescape / localrecover /
/// eh_recoverfp stay rejected by existing gates.  Ordinary tail,
/// musttail, bundles, noreturn, returns_twice, non-C, vararg, non-AS0,
/// and complex ABI stay out.
static bool isSupportedLocalAddressIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::localaddress)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedPointerType(ResultTy) || Call.arg_size() != 0)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 0)
    return false;
  return true;
}

/// Exact llvm.readcyclecounter only (Intrinsic::readcyclecounter,
/// exact non-vararg FunctionType i64(), C, zero args).  LangRef:
/// target cycle counter.  AArch64 ISel is MRS PMCCNTR_EL0 with
/// +perfmon, else 0.  Replayed via CallDescriptor into the i64
/// integer VReg — never pre-folded or deleted.  Ordinary tail,
/// musttail, bundles, noreturn, returns_twice, non-C, vararg, non-i64,
/// and complex ABI stay out.
static bool isSupportedReadCycleCounterIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::readcyclecounter)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  Type *ResultTy = Call.getType();
  if (!ResultTy->isIntegerTy(64) || Call.arg_size() != 0)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 0)
    return false;
  return true;
}

/// Exact llvm.flt.rounds only (Intrinsic::flt_rounds, exact non-vararg
