/// Exact llvm.aarch64.hint (exact non-vararg FunctionType void(i32), C).
/// The i32 imm is a CallDescriptor immediate in 0..127 (never a VReg)
/// with formal type equality.  Replayed via CallDescriptor — never
/// folded or deleted.  No target-features gate.  Ordinary tail,
/// musttail, bundles, noreturn, returns_twice, non-C, vararg,
/// dynamic/out-of-range, and complex ABI stay out.
static bool isSupportedAArch64HintIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::aarch64_hint)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  Type *ResultTy = Call.getType();
  if (!ResultTy->isVoidTy() || Call.arg_size() != 1)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 1)
    return false;
  const Value *Arg0 = Call.getArgOperand(0);
  if (!Arg0 || Arg0->getType() != FTy->getParamType(0))
    return false;
  // Imm must be an i32 ConstantInt and treated as an immediate argument.
  if (!isCallImmediateArgument(Call, 0))
    return false;
  const auto *Imm = dyn_cast<ConstantInt>(Arg0);
  if (!Imm || !Imm->getType()->isIntegerTy(32))
    return false;
  // AArch64 HINT encodes a 7-bit immediate (#imm0..127).
  const uint64_t Value = Imm->getZExtValue();
  return Value <= 127;
}

/// Exact llvm.aarch64.cls / cls64 (C, exact non-vararg FunctionType,
/// formal type equality):
///   cls   : i32 @llvm.aarch64.cls(i32)
///   cls64 : i32 @llvm.aarch64.cls64(i64)
/// Replayed via CallDescriptor into the i32 integer VReg — never
/// folded.  No target-features gate.  Ordinary tail, musttail,
/// bundles, noreturn, returns_twice, non-C, vararg, poison, wrong
/// width, and complex ABI stay out.
static bool isSupportedAArch64ClsIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  if (ID != Intrinsic::aarch64_cls && ID != Intrinsic::aarch64_cls64)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  Type *ResultTy = Call.getType();
  if (!ResultTy->isIntegerTy(32) || Call.arg_size() != 1)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 1)
    return false;
  const Value *Arg = Call.getArgOperand(0);
  if (!Arg || Arg->getType() != FTy->getParamType(0) ||
      !isSupportedOrdinaryCallOperand(Arg))
    return false;
  if (ID == Intrinsic::aarch64_cls)
    return Arg->getType()->isIntegerTy(32);
  // cls64: i64 operand only — does not relax cls to accept i64.
  return Arg->getType()->isIntegerTy(64);
}

/// AArch64-only llvm.aarch64.sdiv with exact scalar overloads only:
///   i32 @llvm.aarch64.sdiv.i32(i32, i32)
///   i64 @llvm.aarch64.sdiv.i64(i64, i64)
/// Re-emitted via normal Call handler using existing integer virtual
/// registers; no dedicated VM opcode.  Distinct from IR sdiv and
/// llvm.aarch64.udiv.  Mixed widths and other integer bitwidths stay rejected.
static bool isSupportedAArch64SDivI32Intrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::aarch64_sdiv)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.arg_size() != 2)
    return false;
  Type *ResultTy = Call.getType();
  unsigned BitWidth = 0;
  if (ResultTy->isIntegerTy(32))
    BitWidth = 32;
  else if (ResultTy->isIntegerTy(64))
    BitWidth = 64;
  else
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 2)
    return false;
  for (unsigned Index = 0; Index < 2; ++Index) {
    const Value *Arg = Call.getArgOperand(Index);
    Type *ParamTy = FTy->getParamType(Index);
    if (!Arg || Arg->getType() != ParamTy ||
        !Arg->getType()->isIntegerTy(BitWidth) ||
        !isSupportedOrdinaryCallOperand(Arg))
      return false;
  }
  return true;
}

/// AArch64-only llvm.aarch64.udiv with exact scalar overloads only:
///   i32 @llvm.aarch64.udiv.i32(i32, i32)
///   i64 @llvm.aarch64.udiv.i64(i64, i64)
/// Re-emitted via normal Call handler using existing integer virtual
/// registers; no dedicated VM opcode.  Distinct from IR udiv and
