/// Shape-only AArch64 scalar FRINT*.f32 gate (no fptoint feature check): exact
/// \p ExpectedID, scalar float result, one ordinary float operand, ordinary
/// call ABI.  Double overloads and other frint IDs stay out.
static bool isAArch64FrintZF32ShapeSupported(const CallInst &Call,
                                             Intrinsic::ID ExpectedID) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != ExpectedID)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  // Exact f32 overload only: float @llvm.aarch64.frint*.f32(float).
  Type *ResultTy = Call.getType();
  if (!isSupportedFloatType(ResultTy) || Call.arg_size() != 1)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || FTy->getReturnType() != ResultTy ||
      FTy->getNumParams() != 1)
    return false;
  const Value *Arg = Call.getArgOperand(0);
  return Arg && Arg->getType() == ResultTy &&
         Arg->getType() == FTy->getParamType(0) &&
         isSupportedOrdinaryCallOperand(Arg);
}

static bool isAArch64Frint32zF32ShapeSupported(const CallInst &Call) {
  return isAArch64FrintZF32ShapeSupported(Call, Intrinsic::aarch64_frint32z);
}

static bool isAArch64Frint64zF32ShapeSupported(const CallInst &Call) {
  return isAArch64FrintZF32ShapeSupported(Call, Intrinsic::aarch64_frint64z);
}

static bool isAArch64Frint32xF32ShapeSupported(const CallInst &Call) {
  return isAArch64FrintZF32ShapeSupported(Call, Intrinsic::aarch64_frint32x);
}

static bool isAArch64Frint64xF32ShapeSupported(const CallInst &Call) {
  return isAArch64FrintZF32ShapeSupported(Call, Intrinsic::aarch64_frint64x);
}

/// True when \p F has an explicit "target-features" function attribute whose
/// comma-separated list enables SVE: the last occurrence of the exact tokens
/// "+sve" / "-sve" wins.  Missing attribute, no +sve/-sve token, final -sve,
/// and related features (+sve2/+sme/…) do not count.  Command-line -mattr is
/// never consulted.
static bool functionHasExplicitSVEEnabled(const Function &F) {
  if (!F.hasFnAttribute("target-features"))
    return false;
  const Attribute Attr = F.getFnAttribute("target-features");
  if (!Attr.isValid() || !Attr.isStringAttribute())
    return false;

  // Optional last-seen state: none means SVE was never mentioned.
  bool Seen = false;
  bool Enabled = false;
  SmallVector<StringRef, 8> Parts;
  // MaxSplit must be -1: the 3-arg form is (Separator, MaxSplit, KeepEmpty).
  // Passing only `false` binds MaxSplit=0 and never splits multi-feature lists.
  Attr.getValueAsString().split(Parts, ',', /*MaxSplit=*/-1,
                                /*KeepEmpty=*/false);
  for (StringRef Part : Parts) {
    Part = Part.trim();
    // Exact token only — do not treat +sve2 / +sme / +sve.foo as +sve.
    if (Part == "+sve") {
      Seen = true;
      Enabled = true;
    } else if (Part == "-sve") {
      Seen = true;
      Enabled = false;
    }
  }
  return Seen && Enabled;
}

