/// Shape-only AArch64 MTE main-path gate (no +mte feature check).
/// Exact IDs only — llvm.aarch64.irg.sp is stack instrumentation and stays
/// out.  Ordinary call ABI (musttail / bundles / noreturn / returns_twice /
/// complex ABI rejected).  Pointers are address-space zero.
///
///   irg          : ptr  @llvm.aarch64.irg(ptr, i64)          ; i64 VReg
///   addg         : ptr  @llvm.aarch64.addg(ptr, i64 imm 0..15)
///   gmi          : i64  @llvm.aarch64.gmi(ptr, i64)          ; i64 VReg
///   ldg          : ptr  @llvm.aarch64.ldg(ptr, ptr)
///   stg          : void @llvm.aarch64.stg(ptr, ptr)
///   subp         : i64  @llvm.aarch64.subp(ptr, ptr)
///   tagp         : ptr  @llvm.aarch64.tagp(ptr, ptr, i64 ImmArg ConstantInt)
///   settag       : void @llvm.aarch64.settag(ptr, i64 const, % 16 == 0)
///   settag.zero  : void @llvm.aarch64.settag.zero(ptr, i64 const, % 16 == 0)
///   stgp         : void @llvm.aarch64.stgp(ptr, i64, i64)    ; i64 VRegs
///
/// addg / settag / settag.zero lengths are not ImmArg in the TD but AArch64
/// isel / EmitTargetCodeForSetTag require ConstantSDNode, so they travel on
/// ImmediateArguments.  tagp arg 2 is a true ImmArg.  Wrong shape / irg.sp
/// surface as "unsupported call instruction"; well-shaped MTE without +mte
/// is "unsupported target feature".
static bool isAArch64MTEShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  switch (ID) {
  case Intrinsic::aarch64_irg:
  case Intrinsic::aarch64_addg:
  case Intrinsic::aarch64_gmi:
  case Intrinsic::aarch64_ldg:
  case Intrinsic::aarch64_stg:
  case Intrinsic::aarch64_subp:
  case Intrinsic::aarch64_tagp:
  case Intrinsic::aarch64_settag:
  case Intrinsic::aarch64_settag_zero:
  case Intrinsic::aarch64_stgp:
    break;
  default:
    return false;
  }
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;

  auto IsAS0Ptr = [](const Value *V) {
    return V && isSupportedPointerType(V->getType()) &&
           isSupportedOrdinaryCallOperand(V);
  };
  auto IsI64Ordinary = [](const Value *V) {
    return V && V->getType()->isIntegerTy(64) &&
           isSupportedOrdinaryCallOperand(V);
  };

  switch (ID) {
  case Intrinsic::aarch64_irg:
    // ptr @llvm.aarch64.irg(ptr, i64)
    if (!isSupportedPointerType(Call.getType()) || Call.arg_size() != 2)
      return false;
    return IsAS0Ptr(Call.getArgOperand(0)) &&
           IsI64Ordinary(Call.getArgOperand(1));
  case Intrinsic::aarch64_addg: {
    // ptr @llvm.aarch64.addg(ptr, i64 ConstantInt 0..15)
    if (!isSupportedPointerType(Call.getType()) || Call.arg_size() != 2)
      return false;
    if (!IsAS0Ptr(Call.getArgOperand(0)))
      return false;
    if (!isCallImmediateArgument(Call, 1))
      return false;
    const auto *Imm = dyn_cast<ConstantInt>(Call.getArgOperand(1));
    if (!Imm || !Imm->getType()->isIntegerTy(64) || Imm->getValue().getActiveBits() > 4)
      return false;
    return Imm->getZExtValue() <= 15;
  }
  case Intrinsic::aarch64_gmi:
    // i64 @llvm.aarch64.gmi(ptr, i64)
    if (!Call.getType()->isIntegerTy(64) || Call.arg_size() != 2)
      return false;
    return IsAS0Ptr(Call.getArgOperand(0)) &&
           IsI64Ordinary(Call.getArgOperand(1));
  case Intrinsic::aarch64_ldg:
    // ptr @llvm.aarch64.ldg(ptr, ptr)
    if (!isSupportedPointerType(Call.getType()) || Call.arg_size() != 2)
      return false;
    return IsAS0Ptr(Call.getArgOperand(0)) && IsAS0Ptr(Call.getArgOperand(1));
  case Intrinsic::aarch64_stg:
    // void @llvm.aarch64.stg(ptr, ptr)
    if (!Call.getType()->isVoidTy() || Call.arg_size() != 2)
      return false;
    return IsAS0Ptr(Call.getArgOperand(0)) && IsAS0Ptr(Call.getArgOperand(1));
  case Intrinsic::aarch64_subp:
    // i64 @llvm.aarch64.subp(ptr, ptr)
    if (!Call.getType()->isIntegerTy(64) || Call.arg_size() != 2)
      return false;
    return IsAS0Ptr(Call.getArgOperand(0)) && IsAS0Ptr(Call.getArgOperand(1));
  case Intrinsic::aarch64_tagp: {
    // anyptr @llvm.aarch64.tagp(anyptr, ptr, i64 ImmArg ConstantInt)
    // Result matches operand 0; both pointers AS0.  Dynamic ImmArg is
    // illegal under the verifier; the ConstantInt check is defensive.
    if (!isSupportedPointerType(Call.getType()) || Call.arg_size() != 3)
      return false;
    const Value *Ptr0 = Call.getArgOperand(0);
    const Value *Base = Call.getArgOperand(1);
    if (Ptr0->getType() != Call.getType() || !IsAS0Ptr(Ptr0) || !IsAS0Ptr(Base))
      return false;
    if (!isCallImmediateArgument(Call, 2))
      return false;
    const auto *Imm = dyn_cast<ConstantInt>(Call.getArgOperand(2));
    return Imm && Imm->getType()->isIntegerTy(64);
  }
  case Intrinsic::aarch64_settag:
  case Intrinsic::aarch64_settag_zero: {
    // void @llvm.aarch64.settag[.zero](ptr, i64 ConstantInt, multiple of 16)
    if (!Call.getType()->isVoidTy() || Call.arg_size() != 2)
      return false;
    if (!IsAS0Ptr(Call.getArgOperand(0)))
      return false;
    if (!isCallImmediateArgument(Call, 1))
      return false;
    const auto *Size = dyn_cast<ConstantInt>(Call.getArgOperand(1));
    if (!Size || !Size->getType()->isIntegerTy(64))
      return false;
    return Size->getZExtValue() % 16 == 0;
  }
  case Intrinsic::aarch64_stgp:
    // void @llvm.aarch64.stgp(ptr, i64, i64)
    if (!Call.getType()->isVoidTy() || Call.arg_size() != 3)
      return false;
    return IsAS0Ptr(Call.getArgOperand(0)) &&
           IsI64Ordinary(Call.getArgOperand(1)) &&
           IsI64Ordinary(Call.getArgOperand(2));
  default:
    return false;
  }
}

/// Scalar AArch64 MTE main-path intrinsic only when the matching shape is
/// supported *and* the enclosing function explicitly enables +mte (see
/// functionHasExplicitMTEEnabled).  Re-emitted via the normal Call handler
/// using existing integer / pointer virtual registers and ImmediateArguments;
/// no dedicated VM opcode.  Well-shaped MTE without +mte is rejected
/// separately with "unsupported target feature".
static bool isSupportedAArch64MTEIntrinsic(const CallInst &Call) {
  if (!isAArch64MTEShapeSupported(Call))
    return false;
  const Function *Parent = Call.getFunction();
  return Parent && functionHasExplicitMTEEnabled(*Parent);
}

/// Shape-only llvm.aarch64.mops.memset.tag gate (no +mops/+mte check).
/// Exact Intrinsic::aarch64_mops_memset_tag only:
///   ptr @llvm.aarch64.mops.memset.tag(ptr AS0, i8, i64)
/// Result and dest are address-space zero; fill is i8; length is i64.
/// All three operands are ordinary VRegs (pointer / i8 / i64).  Other MOPS
/// (including SME mops) and MTE stack-only irg.sp stay out.  musttail /
/// bundles / noreturn / returns_twice / complex ABI rejected here.
static bool isAArch64MOPSMemsetTagShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::aarch64_mops_memset_tag)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (!isSupportedPointerType(Call.getType()) || Call.arg_size() != 3)
    return false;
  const Value *Dst = Call.getArgOperand(0);
  const Value *Val = Call.getArgOperand(1);
  const Value *Size = Call.getArgOperand(2);
  if (!isSupportedPointerType(Dst->getType()) ||
      !isSupportedOrdinaryCallOperand(Dst))
    return false;
  if (!Val->getType()->isIntegerTy(8) || !isSupportedOrdinaryCallOperand(Val))
    return false;
  return Size->getType()->isIntegerTy(64) &&
         isSupportedOrdinaryCallOperand(Size);
}

/// llvm.aarch64.mops.memset.tag only when the shape is supported *and* the
/// enclosing function explicitly enables both +mops and +mte (each last
/// exact token wins; see functionHasExplicitMOPSEnabled /
/// functionHasExplicitMTEEnabled).  Re-emitted via the normal Call handler:
/// ptr result on the pointer VReg frame; dest / i8 / i64 on pointer / i8 /
/// i64 VRegs.  No dedicated VM opcode.  Well-shaped memset.tag missing
/// either feature is rejected separately with "unsupported target feature".
static bool isSupportedAArch64MOPSMemsetTagIntrinsic(const CallInst &Call) {
  if (!isAArch64MOPSMemsetTagShapeSupported(Call))
    return false;
  const Function *Parent = Call.getFunction();
  return Parent && functionHasExplicitMOPSEnabled(*Parent) &&
         functionHasExplicitMTEEnabled(*Parent);
}

/// Shape-only llvm.aarch64.ttest gate (no +tme check).  Exact
/// Intrinsic::aarch64_ttest only: i64 @llvm.aarch64.ttest() — zero args,
/// i64 result.  musttail / bundles / noreturn / returns_twice / complex ABI
/// and any other signature fail here.  tstart / tcommit / tcancel are
/// intentionally not shapes: they change transaction boundaries, and the
/// VMP dispatcher would alter transaction capacity and abort semantics.
static bool isAArch64TTestShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::aarch64_ttest)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (!Call.getType()->isIntegerTy(64))
    return false;
  return Call.arg_size() == 0;
}

/// llvm.aarch64.ttest only when the shape is supported *and* the enclosing
/// function explicitly enables +tme (see functionHasExplicitTMEEnabled).
/// Re-emitted via the normal Call handler; i64 result on the integer VReg
/// frame; no dedicated VM opcode.  Well-shaped ttest without +tme is
/// rejected separately with "unsupported target feature".  tstart / tcommit
/// / tcancel stay unlisted so late eligibility skips them as unsupported
/// calls and keeps the original body plus hikari.vmp.selected.
static bool isSupportedAArch64TTestIntrinsic(const CallInst &Call) {
  if (!isAArch64TTestShapeSupported(Call))
    return false;
  const Function *Parent = Call.getFunction();
  return Parent && functionHasExplicitTMEEnabled(*Parent);
}

/// Fixed ld64b result: { i64, i64, i64, i64, i64, i64, i64, i64 } only.
static bool isAArch64Ld64bResultType(const Type *Ty) {
  const auto *StructTy = dyn_cast<StructType>(Ty);
  if (!StructTy || StructTy->getNumElements() != 8)
    return false;
  for (unsigned Index = 0; Index < 8; ++Index) {
    if (!StructTy->getElementType(Index)->isIntegerTy(64))
      return false;
  }
  return true;
}

/// Shape-only llvm.aarch64.ld64b (no +ls64 check): exact ID, one AS0 ptr,
/// {i64 x8} result, every use a single-index extractvalue 0..7, at most one
/// extract per index, never the aggregate itself.  phi/select/insertvalue/
/// aggregate memory users fail here (generic call / later instruction
/// rejects).  musttail / bundles / noreturn / returns_twice / complex ABI
/// rejected.  This does not open general aggregates.
static bool isAArch64Ld64bShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::aarch64_ld64b)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (!isAArch64Ld64bResultType(Call.getType()) || Call.arg_size() != 1)
    return false;
  const Value *Ptr = Call.getArgOperand(0);
  if (!isSupportedPointerType(Ptr->getType()) ||
      !isSupportedOrdinaryCallOperand(Ptr))
    return false;

  bool Seen[8] = {};
  for (const User *U : Call.users()) {
    const auto *EV = dyn_cast<ExtractValueInst>(U);
    if (!EV || EV->getNumIndices() != 1)
      return false;
    const unsigned Index = EV->getIndices()[0];
    if (Index >= 8 || Seen[Index] || !EV->getType()->isIntegerTy(64))
      return false;
    Seen[Index] = true;
  }
  return true;
}

/// Shape-only llvm.aarch64.st64b / st64bv / st64bv0 (no +ls64 check):
///   void @llvm.aarch64.st64b(ptr AS0, i64 x8)
///   i64  @llvm.aarch64.st64bv(ptr AS0, i64 x8)
///   i64  @llvm.aarch64.st64bv0(ptr AS0, i64 x8)
/// Ordinary CallDescriptor path.  Non-AS0 / wrong arity / musttail / bundles
/// / noreturn / returns_twice / complex ABI rejected.
static bool isAArch64St64FamilyShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  if (ID != Intrinsic::aarch64_st64b && ID != Intrinsic::aarch64_st64bv &&
      ID != Intrinsic::aarch64_st64bv0)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (ID == Intrinsic::aarch64_st64b) {
    if (!Call.getType()->isVoidTy())
      return false;
  } else if (!Call.getType()->isIntegerTy(64)) {
    return false;
  }
  if (Call.arg_size() != 9)
    return false;
  const Value *Ptr = Call.getArgOperand(0);
  if (!isSupportedPointerType(Ptr->getType()) ||
      !isSupportedOrdinaryCallOperand(Ptr))
    return false;
  for (unsigned Index = 1; Index < 9; ++Index) {
    const Value *Word = Call.getArgOperand(Index);
    if (!Word->getType()->isIntegerTy(64) ||
        !isSupportedOrdinaryCallOperand(Word))
      return false;
  }
  return true;
}

static bool isAArch64LS64ShapeSupported(const CallInst &Call) {
  return isAArch64Ld64bShapeSupported(Call) ||
         isAArch64St64FamilyShapeSupported(Call);
}

/// LS64 family only when the matching shape is supported *and* the enclosing
/// function explicitly enables +ls64 (see functionHasExplicitLS64Enabled).
/// st64b/st64bv/st64bv0 re-emit via CallDescriptor (ptr + 8 i64 VRegs;
/// i64 status on the integer frame for bv/bv0).  ld64b is planned separately
/// (eight integer VRegs from extractvalue 0..7).  Well-shaped LS64 without
/// +ls64 is "unsupported target feature".
static bool isSupportedAArch64LS64Intrinsic(const CallInst &Call) {
  if (!isAArch64LS64ShapeSupported(Call))
    return false;
  const Function *Parent = Call.getFunction();
  return Parent && functionHasExplicitLS64Enabled(*Parent);
}

static bool isSupportedAArch64Ld64bIntrinsic(const CallInst &Call) {
  if (!isAArch64Ld64bShapeSupported(Call))
    return false;
  const Function *Parent = Call.getFunction();
  return Parent && functionHasExplicitLS64Enabled(*Parent);
}

static bool isSupportedAArch64St64FamilyIntrinsic(const CallInst &Call) {
  if (!isAArch64St64FamilyShapeSupported(Call))
    return false;
  const Function *Parent = Call.getFunction();
  return Parent && functionHasExplicitLS64Enabled(*Parent);
}

static bool isSupportedAArch64Ld64bExtract(const ExtractValueInst &EV) {
  const auto *Call = dyn_cast<CallInst>(EV.getAggregateOperand());
  // Shape only: missing +ls64 still continues past the extract so the call
  // can report "unsupported target feature" rather than extractvalue.
  return Call && isAArch64Ld64bShapeSupported(*Call);
}

/// Shape-only llvm.aarch64.get.fpcr / set.fpcr (no feature gate):
///   i64  @llvm.aarch64.get.fpcr()
///   void @llvm.aarch64.set.fpcr(i64)
/// Re-emitted via CallDescriptor.  musttail / bundles / noreturn /
/// returns_twice / complex ABI / wrong signature rejected.
static bool isAArch64FPCRShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  if (ID != Intrinsic::aarch64_get_fpcr && ID != Intrinsic::aarch64_set_fpcr)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (ID == Intrinsic::aarch64_get_fpcr)
    return Call.getType()->isIntegerTy(64) && Call.arg_size() == 0;
  if (!Call.getType()->isVoidTy() || Call.arg_size() != 1)
    return false;
  const Value *Val = Call.getArgOperand(0);
  return Val->getType()->isIntegerTy(64) && isSupportedOrdinaryCallOperand(Val);
}

static bool isSupportedAArch64FPCRIntrinsic(const CallInst &Call) {
  return isAArch64FPCRShapeSupported(Call);
}

/// Fixed rndr/rndrrs result: { i64, i1 } only.
static bool isAArch64RndrResultType(const Type *Ty) {
  const auto *StructTy = dyn_cast<StructType>(Ty);
  return StructTy && StructTy->getNumElements() == 2 &&
         StructTy->getElementType(0)->isIntegerTy(64) &&
         StructTy->getElementType(1)->isIntegerTy(1);
}

/// Shape-only llvm.aarch64.rndr / rndrrs (no +rand check): exact IDs, zero
/// args, {i64,i1} result, every use a single-index extractvalue 0 (i64) or
/// 1 (i1), at most one of each, never the aggregate.  Duplicate / nested /
/// insertvalue / phi / select / aggregate memory fail here.  musttail /
/// bundles / noreturn / returns_twice / complex ABI rejected.
static bool isAArch64RndrShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  if (ID != Intrinsic::aarch64_rndr && ID != Intrinsic::aarch64_rndrrs)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (!isAArch64RndrResultType(Call.getType()) || Call.arg_size() != 0)
    return false;

  bool SeenValue = false;
  bool SeenSuccess = false;
  for (const User *U : Call.users()) {
    const auto *EV = dyn_cast<ExtractValueInst>(U);
    if (!EV || EV->getNumIndices() != 1)
      return false;
    const unsigned Index = EV->getIndices()[0];
    if (Index == 0) {
      if (SeenValue || !EV->getType()->isIntegerTy(64))
        return false;
      SeenValue = true;
    } else if (Index == 1) {
      if (SeenSuccess || !EV->getType()->isIntegerTy(1))
        return false;
      SeenSuccess = true;
    } else {
      return false;
    }
  }
  return true;
}

/// rndr/rndrrs only when shape is supported *and* the enclosing function
/// explicitly enables +rand (see functionHasExplicitRandEnabled).  Planned
/// as Rndr (i64 / i1 VRegs from extractvalue 0/1).  Well-shaped RNDR
/// without +rand is "unsupported target feature".
static bool isSupportedAArch64RndrIntrinsic(const CallInst &Call) {
  if (!isAArch64RndrShapeSupported(Call))
    return false;
  const Function *Parent = Call.getFunction();
  return Parent && functionHasExplicitRandEnabled(*Parent);
}

static bool isSupportedAArch64RndrExtract(const ExtractValueInst &EV) {
  const auto *Call = dyn_cast<CallInst>(EV.getAggregateOperand());
  // Shape only so missing +rand reports "unsupported target feature".
  return Call && isAArch64RndrShapeSupported(*Call);
}

/// Shape-only llvm.aarch64.fjcvtzs (no +jsconv check):
///   i32 @llvm.aarch64.fjcvtzs(double)
/// musttail / bundles / noreturn / returns_twice / complex ABI / wrong
/// signature fail here (generic call reject).  Well-shaped fjcvtzs without
/// +jsconv is "unsupported target feature".
static bool isAArch64FjcvtzsShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::aarch64_fjcvtzs)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (!Call.getType()->isIntegerTy(32) || Call.arg_size() != 1)
    return false;
  const Value *Arg = Call.getArgOperand(0);
  return Arg->getType()->isDoubleTy() && isSupportedOrdinaryCallOperand(Arg);
}

/// llvm.aarch64.fjcvtzs only when the shape is supported *and* the enclosing
/// function explicitly enables +jsconv (see functionHasExplicitJSConvEnabled).
/// Re-emitted via CallDescriptor; double operand on the float VReg frame,
/// i32 result on the integer frame.  Command-line -mattr is never consulted.
static bool isSupportedAArch64FjcvtzsIntrinsic(const CallInst &Call) {
  if (!isAArch64FjcvtzsShapeSupported(Call))
    return false;
  const Function *Parent = Call.getFunction();
  return Parent && functionHasExplicitJSConvEnabled(*Parent);
}

/// Shape-only generic llvm.ptrauth.sign / llvm.ptrauth.sign_generic.
/// This LLVM 15 AArch64 SDAG only selects those two IDs (PAC* / PACGA);
/// auth / strip / resign / blend stay out so replay cannot fail ISel.
///
///   sign         : i64 @llvm.ptrauth.sign(i64, i32 ImmArg key 0..3, i64)
///   sign_generic : i64 @llvm.ptrauth.sign_generic(i64, i64)
///
/// Key is ASIA/ASIB/ASDA/ASDB (0..3) and stays a true ImmArg on
/// CallDescriptor.  Value / discriminator are ordinary i64 VRegs.
/// musttail / bundles / noreturn / returns_twice / poison / undef /
/// complex ABI stay rejected.  Command-line -mattr is never consulted.
static bool isPtrAuthShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  if (ID != Intrinsic::ptrauth_sign && ID != Intrinsic::ptrauth_sign_generic)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (!Call.getType()->isIntegerTy(64))
    return false;
  if (ID == Intrinsic::ptrauth_sign) {
    if (Call.arg_size() != 3)
      return false;
    const Value *Val = Call.getArgOperand(0);
    const Value *Disc = Call.getArgOperand(2);
    if (!Val->getType()->isIntegerTy(64) ||
        !isSupportedOrdinaryCallOperand(Val) ||
        !Disc->getType()->isIntegerTy(64) ||
        !isSupportedOrdinaryCallOperand(Disc))
      return false;
    if (!isCallImmediateArgument(Call, 1))
      return false;
    const auto *Key = dyn_cast<ConstantInt>(Call.getArgOperand(1));
    if (!Key || !Key->getType()->isIntegerTy(32) || Key->isNegative())
      return false;
    return Key->getZExtValue() <= 3;
  }
  if (Call.arg_size() != 2)
    return false;
  const Value *Val = Call.getArgOperand(0);
  const Value *Disc = Call.getArgOperand(1);
  return Val->getType()->isIntegerTy(64) &&
         isSupportedOrdinaryCallOperand(Val) &&
         Disc->getType()->isIntegerTy(64) &&
         isSupportedOrdinaryCallOperand(Disc);
}

/// Generic llvm.ptrauth.sign / sign_generic only when the shape is
/// supported *and* the enclosing function explicitly enables +pauth
/// (see functionHasExplicitPAuthEnabled).  Re-emitted via CallDescriptor
/// using existing i64 integer VRegs; no dedicated VM opcode.  Well-shaped
/// ptrauth without +pauth is "unsupported target feature".
static bool isSupportedPtrAuthIntrinsic(const CallInst &Call) {
  if (!isPtrAuthShapeSupported(Call))
    return false;
  const Function *Parent = Call.getFunction();
  return Parent && functionHasExplicitPAuthEnabled(*Parent);
}

/// Exact llvm.aarch64.break only: void, single i32 ConstantInt ImmArg in
/// 0..65535.  IntrNoReturn, so doesNotReturn is not applied (same as
/// ubsantrap).  Dedicated terminating opcode — re-emits the same break
/// then unreachable; no PC advance; never a generic noreturn Call.
/// Dynamic / out-of-range / musttail / bundles / returns_twice / complex
/// ABI stay rejected (original body + hikari.vmp.selected, no bytecode).
static bool isSupportedAArch64BreakIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::aarch64_break)
    return false;
  if (Call.arg_size() != 1 || Call.hasOperandBundles() || Call.isMustTailCall() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (!Call.getType()->isVoidTy())
    return false;
  if (!isCallImmediateArgument(Call, 0))
    return false;
  const auto *Imm = dyn_cast<ConstantInt>(Call.getArgOperand(0));
  if (!Imm || !Imm->getType()->isIntegerTy(32))
    return false;
  return Imm->getZExtValue() <= 65535;
}

/// Result / index vector for AArch64 NEON tbl/tbx: already-supported
/// fixed i8 vectors of 64 or 128 bits (<8 x i8> / <16 x i8>).  Table
/// registers stay exactly <16 x i8> (llvm_v16i8_ty).  Other anyvector
/// instantiations (i16/i32/half, <4 x i8>, scalable) stay out.
static bool isAArch64NeonTblTbxLookupType(const Type *Ty) {
  const auto *FixedTy = dyn_cast<FixedVectorType>(Ty);
  if (!FixedTy || !isSupportedFixedVectorType(Ty))
    return false;
  if (!FixedTy->getElementType()->isIntegerTy(8))
    return false;
  const unsigned Bits = FixedTy->getPrimitiveSizeInBits().getFixedValue();
  return Bits == 64 || Bits == 128;
}

static bool isAArch64NeonTblTbxTableType(const Type *Ty) {
  const auto *FixedTy = dyn_cast<FixedVectorType>(Ty);
  return FixedTy && isSupportedFixedVectorType(Ty) &&
         FixedTy->getElementType()->isIntegerTy(8) &&
         FixedTy->getNumElements() == 16;
}

static bool isAArch64NeonTblTbxFamilyID(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_tbl1:
  case Intrinsic::aarch64_neon_tbl2:
  case Intrinsic::aarch64_neon_tbl3:
  case Intrinsic::aarch64_neon_tbl4:
  case Intrinsic::aarch64_neon_tbx1:
  case Intrinsic::aarch64_neon_tbx2:
  case Intrinsic::aarch64_neon_tbx3:
  case Intrinsic::aarch64_neon_tbx4:
    return true;
  default:
    return false;
  }
}

static unsigned getAArch64NeonTblTbxTableCount(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_tbl1:
  case Intrinsic::aarch64_neon_tbx1:
    return 1;
  case Intrinsic::aarch64_neon_tbl2:
  case Intrinsic::aarch64_neon_tbx2:
    return 2;
  case Intrinsic::aarch64_neon_tbl3:
  case Intrinsic::aarch64_neon_tbx3:
    return 3;
  case Intrinsic::aarch64_neon_tbl4:
  case Intrinsic::aarch64_neon_tbx4:
    return 4;
  default:
    return 0;
  }
}

static bool isAArch64NeonTblTbxTbxID(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_tbx1:
  case Intrinsic::aarch64_neon_tbx2:
  case Intrinsic::aarch64_neon_tbx3:
  case Intrinsic::aarch64_neon_tbx4:
    return true;
  default:
    return false;
  }
}

/// Exact llvm.aarch64.neon.tbl1..4 / tbx1..4 only, matching
/// IntrinsicsAArch64.td:
///   tblN: anyvector(result) (v16i8 x N, match<0> indices)
///   tbxN: anyvector(result) (match<0> passthru, v16i8 x N, match<0> indices)
/// Result/index restricted to supported <8 x i8> / <16 x i8>.  Tables
/// are always <16 x i8>.  Call site must be CallingConv::C and
/// non-vararg — the generic allowed-intrinsic path does not re-check
/// CC, so fastcc/coldcc would otherwise leak through.  Re-emitted via
/// CallDescriptor / vector VRegs; no dedicated VM opcode and no extra
/// +neon / +fullfp16 gate (baseline AArch64 AdvSIMD).  arm.neon.vtbl*,
/// uzp/zip/trn, and non-i8 lookups stay rejected.
static bool isSupportedAArch64NeonTblTbxIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonTblTbxFamilyID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.getFunctionType()->isVarArg())
    return false;
  Type *ResultTy = Call.getType();
  if (!isAArch64NeonTblTbxLookupType(ResultTy))
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  const bool IsTbx = isAArch64NeonTblTbxTbxID(ID);
  const unsigned TableCount = getAArch64NeonTblTbxTableCount(ID);
  const unsigned ExpectedArgs = (IsTbx ? 1u : 0u) + TableCount + 1u;
  if (TableCount == 0 || Call.arg_size() != ExpectedArgs)
    return false;
  unsigned Index = 0;
  if (IsTbx) {
    const Value *Passthru = Call.getArgOperand(Index++);
    if (Passthru->getType() != ResultTy ||
        !isSupportedOrdinaryCallOperand(Passthru))
      return false;
  }
  for (unsigned Table = 0; Table < TableCount; ++Table) {
    const Value *TableArg = Call.getArgOperand(Index++);
    if (!isAArch64NeonTblTbxTableType(TableArg->getType()) ||
        !isSupportedOrdinaryCallOperand(TableArg))
      return false;
  }
  const Value *Indices = Call.getArgOperand(Index);
  return Indices->getType() == ResultTy &&
         isSupportedOrdinaryCallOperand(Indices);
}

/// Practical AArch64 ISel overloads for neon st1xN / stN, integers and
/// f32/f64 only: 64-bit <8 x i8>/<4 x i16>/<2 x i32>/<2 x float>/
/// <1 x i64>/<1 x double> and 128-bit <16 x i8>/<8 x i16>/<4 x i32>/
/// <4 x float>/<2 x i64>/<2 x double>.  half, <4 x i8>, <3 x i32>, i1,
/// bfloat, scalable, and pointer vectors stay out.
static bool isAArch64NeonStVectorType(const Type *Ty) {
  const auto *FixedTy = dyn_cast<FixedVectorType>(Ty);
  if (!FixedTy || !isSupportedFixedVectorType(Ty))
    return false;
  Type *Elt = FixedTy->getElementType();
  const unsigned N = FixedTy->getNumElements();
  const unsigned Bits = FixedTy->getPrimitiveSizeInBits().getFixedValue();
  if (Bits != 64 && Bits != 128)
    return false;
  if (Elt->isIntegerTy(8))
    return N == 8 || N == 16;
  if (Elt->isIntegerTy(16))
    return N == 4 || N == 8;
  if (Elt->isIntegerTy(32) || Elt->isFloatTy())
    return N == 2 || N == 4;
  if (Elt->isIntegerTy(64) || Elt->isDoubleTy())
    return N == 1 || N == 2;
  return false;
}

static unsigned getAArch64NeonStVectorCount(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_st1x2:
  case Intrinsic::aarch64_neon_st2:
    return 2;
  case Intrinsic::aarch64_neon_st1x3:
  case Intrinsic::aarch64_neon_st3:
    return 3;
  case Intrinsic::aarch64_neon_st1x4:
  case Intrinsic::aarch64_neon_st4:
    return 4;
  default:
    return 0;
  }
}

/// Exact llvm.aarch64.neon.st1x2/st1x3/st1x4 and st2/st3/st4 only,
/// matching IntrinsicsAArch64.td AdvSIMD_NVec_Store_Intrinsic:
///   void (anyvector x N, anyptr-to-match)
/// N vectors share one supported ISel type; the pointer is AS0.
/// Call site must be CallingConv::C and non-vararg.  Re-emitted via
/// CallDescriptor (vector VRegs + pointer VReg); no dedicated VM
/// opcode and no extra +neon / +fullfp16 gate.  half vectors, SVE st*,
/// arm.neon.vst*, and non-AS0 stay rejected.  st2lane/st3lane/st4lane
/// use the separate lane helper.
static bool isSupportedAArch64NeonStIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const unsigned VecCount = getAArch64NeonStVectorCount(II->getIntrinsicID());
  if (VecCount == 0)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.getFunctionType()->isVarArg())
    return false;
  if (!Call.getType()->isVoidTy())
    return false;
  if (Call.arg_size() != VecCount + 1)
    return false;
  Type *VecTy = Call.getArgOperand(0)->getType();
  if (!isAArch64NeonStVectorType(VecTy))
    return false;
  for (unsigned Index = 0; Index < VecCount; ++Index) {
    const Value *Vec = Call.getArgOperand(Index);
    if (Vec->getType() != VecTy || !isSupportedOrdinaryCallOperand(Vec))
      return false;
  }
  const Value *Ptr = Call.getArgOperand(VecCount);
  return isSupportedPointerType(Ptr->getType()) &&
         isSupportedOrdinaryCallOperand(Ptr);
}

static unsigned getAArch64NeonStLaneVectorCount(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_st1lane:
    return 1;
  case Intrinsic::aarch64_neon_st2lane:
    return 2;
  case Intrinsic::aarch64_neon_st3lane:
    return 3;
  case Intrinsic::aarch64_neon_st4lane:
    return 4;
  default:
    return 0;
  }
}

/// Exact llvm.aarch64.neon.st1lane/st2lane/st3lane/st4lane only,
/// matching AdvSIMD_NVec_Store_Lane_Intrinsic:
///   void (anyvector x N, i64 lane, anyptr)
/// Practically: void (vec x N, i64, ptr AS0).  All N vectors share
/// one supported ISel type (same as st1xN/stN / ld1xN/ldN / ldNlane:
/// 64/128-bit i8/i16/i32/i64/f32/f64).  Lane is an i64 ConstantInt in
/// [0, Nelt) and travels as a CallDescriptor immediate (not ImmArg in
/// the TD; ISel requires ConstantSDNode).  Call site must be
/// CallingConv::C and non-vararg.  Ordinary tail is a hint and is
/// replayed as TCK_None; musttail stays out.  st2/3/4lane share the
/// same musttail-only check.  Re-emitted via CallDescriptor
/// (vector VRegs + immediate lane + pointer VReg).  SVE,
/// arm.neon.vst*lane, half, dynamic or out-of-range lanes, and
/// non-AS0 stay rejected.  No dedicated VM opcode and no extra
/// +neon / +fullfp16 gate.
static bool isSupportedAArch64NeonStLaneIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const unsigned VecCount = getAArch64NeonStLaneVectorCount(II->getIntrinsicID());
  if (VecCount == 0)
    return false;
  // Ordinary tail is a hint; replay as TCK_None on the generic path.
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.getFunctionType()->isVarArg())
    return false;
  if (!Call.getType()->isVoidTy())
    return false;
  if (Call.arg_size() != VecCount + 2)
    return false;
  Type *VecTy = Call.getArgOperand(0)->getType();
  if (!isAArch64NeonStVectorType(VecTy))
    return false;
  for (unsigned Index = 0; Index < VecCount; ++Index) {
    const Value *Vec = Call.getArgOperand(Index);
    if (Vec->getType() != VecTy || !isSupportedOrdinaryCallOperand(Vec))
      return false;
  }
  const Value *Lane = Call.getArgOperand(VecCount);
  if (!Lane->getType()->isIntegerTy(64))
    return false;
  const auto *LaneImm = dyn_cast<ConstantInt>(Lane);
  if (!LaneImm)
    return false;
  const uint64_t Lanes =
      cast<FixedVectorType>(VecTy)->getNumElements();
  if (LaneImm->isNegative() || LaneImm->uge(Lanes))
    return false;
  if (!isCallImmediateArgument(Call, VecCount))
    return false;
  const Value *Ptr = Call.getArgOperand(VecCount + 1);
  return isSupportedPointerType(Ptr->getType()) &&
         isSupportedOrdinaryCallOperand(Ptr);
}

static bool isSupportedAArch64NeonStFamily(const CallInst &Call) {
  return isSupportedAArch64NeonStIntrinsic(Call) ||
         isSupportedAArch64NeonStLaneIntrinsic(Call);
}

static unsigned getAArch64NeonLdRVectorCount(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_ld2r:
    return 2;
  case Intrinsic::aarch64_neon_ld3r:
    return 3;
  case Intrinsic::aarch64_neon_ld4r:
    return 4;
  default:
    return 0;
  }
}

static unsigned getAArch64NeonLdVectorCount(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_ld1x2:
  case Intrinsic::aarch64_neon_ld2:
    return 2;
  case Intrinsic::aarch64_neon_ld1x3:
  case Intrinsic::aarch64_neon_ld3:
    return 3;
  case Intrinsic::aarch64_neon_ld1x4:
  case Intrinsic::aarch64_neon_ld4:
    return 4;
  default:
    return getAArch64NeonLdRVectorCount(ID);
  }
}

/// Exact llvm.aarch64.neon.ld1x2/ld1x3/ld1x4, ld2/ld3/ld4, and
/// ld2r/ld3r/ld4r only, matching AdvSIMD_NVec_Load_Intrinsic:
///   {anyvector x N} (anyptr-to-match)
/// N vectors share one supported ISel type (same practical overloads
/// as st1xN/stN: 64/128-bit i8/i16/i32/i64/f32/f64).  The pointer is
/// AS0.  Call site must be CallingConv::C and non-vararg.
/// Every field 0..N-1 must be extracted exactly once (single-index
/// extractvalue of that vector type).  The tuple is never a first-class
/// aggregate (phi/select/store/ret/insertvalue), including 16-byte
/// {<8 x i8>,<8 x i8>} pairs that would otherwise match
/// isSupportedFlatAggregateType.  Re-emitted via CallDescriptor with
/// exploded vector VRegs — never the 1..64-byte flat-aggregate frame.
/// ld2r/ld3r/ld4r share this exact TD shape with ld1xN/ldN (replicate
/// load vs interleaved load); ordinary tail is rejected only on the
/// replicate IDs so the interpreter never demotes it.  SVE,
/// arm.neon.vld*, half, and non-AS0 stay rejected.  ld2lane/ld3lane/
/// ld4lane use the separate lane helper.  No dedicated VM opcode and
/// no extra +neon / +fullfp16 gate.
static bool isSupportedAArch64NeonLdIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const unsigned VecCount = getAArch64NeonLdVectorCount(II->getIntrinsicID());
  if (VecCount == 0)
    return false;
  // Ordinary tail is a hint; replay as TCK_None.  ld1xN/ldN share
  // this helper and also no longer reject ordinary tail.
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.getFunctionType()->isVarArg())
    return false;
  if (Call.arg_size() != 1)
    return false;
  const auto *StructTy = dyn_cast<StructType>(Call.getType());
  if (!StructTy || StructTy->getNumElements() != VecCount)
    return false;
  Type *VecTy = StructTy->getElementType(0);
  if (!isAArch64NeonStVectorType(VecTy))
    return false;
  for (unsigned Index = 1; Index < VecCount; ++Index) {
    if (StructTy->getElementType(Index) != VecTy)
      return false;
  }
  const Value *Ptr = Call.getArgOperand(0);
  if (!isSupportedPointerType(Ptr->getType()) ||
      !isSupportedOrdinaryCallOperand(Ptr))
    return false;

  bool Seen[4] = {};
  for (const User *U : Call.users()) {
    const auto *EV = dyn_cast<ExtractValueInst>(U);
    if (!EV || EV->getNumIndices() != 1 || EV->getAggregateOperand() != &Call)
      return false;
    const unsigned Index = EV->getIndices()[0];
    if (Index >= VecCount || Seen[Index] || EV->getType() != VecTy)
      return false;
    Seen[Index] = true;
  }
  for (unsigned Index = 0; Index < VecCount; ++Index) {
    if (!Seen[Index])
      return false;
  }
  return true;
}

static unsigned getAArch64NeonLdLaneVectorCount(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_ld2lane:
    return 2;
  case Intrinsic::aarch64_neon_ld3lane:
    return 3;
  case Intrinsic::aarch64_neon_ld4lane:
    return 4;
  default:
    return 0;
  }
}

/// Exact llvm.aarch64.neon.ld2lane/ld3lane/ld4lane only, matching
/// AdvSIMD_NVec_Load_Lane_Intrinsic:
///   {match x N} (match x (N-1), anyvector, i64 lane, anyptr)
/// Practically: {vec x N} (vec x N, i64, ptr AS0).  All N vectors share
/// one supported ISel type (same as st1xN/stN / ld1xN/ldN: 64/128-bit
/// i8/i16/i32/i64/f32/f64).  Lane is an i64 ConstantInt in [0, Nelt)
/// and travels as a CallDescriptor immediate (not ImmArg in the TD;
/// ISel requires ConstantSDNode).  Call site must be CallingConv::C
/// and non-vararg.  Every field 0..N-1 must be extracted exactly once.
/// The tuple is never a first-class aggregate, including 16-byte
/// {<8 x i8>,<8 x i8>} pairs.  Re-emitted via CallDescriptor with
/// exploded vector VRegs — never the 1..64-byte flat-aggregate frame.
/// Single-vector llvm.aarch64.neon.ld1lane is a separate helper (it
/// returns the updated vector, not a tuple).  Well-formed ld2r/ld3r/
/// ld4r use the ld1xN/ldN helper (same TD class).  SVE,
/// arm.neon.vld*lane, half, dynamic or out-of-range lanes, and
/// non-AS0 stay rejected.  No dedicated VM opcode and no extra
/// +neon / +fullfp16 gate.
static bool isSupportedAArch64NeonLdLaneIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const unsigned VecCount = getAArch64NeonLdLaneVectorCount(II->getIntrinsicID());
  if (VecCount == 0)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.getFunctionType()->isVarArg())
    return false;
  if (Call.arg_size() != VecCount + 2)
    return false;
  const auto *StructTy = dyn_cast<StructType>(Call.getType());
  if (!StructTy || StructTy->getNumElements() != VecCount)
    return false;
  Type *VecTy = StructTy->getElementType(0);
  if (!isAArch64NeonStVectorType(VecTy))
    return false;
  for (unsigned Index = 1; Index < VecCount; ++Index) {
    if (StructTy->getElementType(Index) != VecTy)
      return false;
  }
  for (unsigned Index = 0; Index < VecCount; ++Index) {
    const Value *Vec = Call.getArgOperand(Index);
    if (Vec->getType() != VecTy || !isSupportedOrdinaryCallOperand(Vec))
      return false;
  }
  const Value *Lane = Call.getArgOperand(VecCount);
  if (!Lane->getType()->isIntegerTy(64))
    return false;
  const auto *LaneImm = dyn_cast<ConstantInt>(Lane);
  if (!LaneImm)
    return false;
  const uint64_t Lanes =
      cast<FixedVectorType>(VecTy)->getNumElements();
  // ISel takes a ConstantSDNode lane in [0, Nelt).  Treat signed
  // negatives separately from the unsigned uge bound so i64 -1 cannot
  // be confused with a huge in-range index.
  if (LaneImm->isNegative() || LaneImm->uge(Lanes))
    return false;
  if (!isCallImmediateArgument(Call, VecCount))
    return false;
  const Value *Ptr = Call.getArgOperand(VecCount + 1);
  if (!isSupportedPointerType(Ptr->getType()) ||
      !isSupportedOrdinaryCallOperand(Ptr))
    return false;

  bool Seen[4] = {};
  for (const User *U : Call.users()) {
    const auto *EV = dyn_cast<ExtractValueInst>(U);
    if (!EV || EV->getNumIndices() != 1 || EV->getAggregateOperand() != &Call)
      return false;
    const unsigned Index = EV->getIndices()[0];
    if (Index >= VecCount || Seen[Index] || EV->getType() != VecTy)
      return false;
    Seen[Index] = true;
  }
  for (unsigned Index = 0; Index < VecCount; ++Index) {
    if (!Seen[Index])
      return false;
  }
  return true;
}

static bool isSupportedAArch64NeonLdFamily(const CallInst &Call) {
  return isSupportedAArch64NeonLdIntrinsic(Call) ||
         isSupportedAArch64NeonLdLaneIntrinsic(Call);
}

/// Exact llvm.aarch64.neon.ld1lane only, matching
/// AdvSIMD_1Vec_Load_Lane_Intrinsic:
///   anyvector (anyvector, i64 lane, anyptr)
/// Practically: vec (vec, i64, ptr AS0).  The result is the updated
/// single vector (not a tuple; no extractvalue explosion).  Vector
/// type is the same ISel set as st1xN/stN / ld1xN/ldN / ldNlane
/// (64/128-bit i8/i16/i32/i64/f32/f64).  Lane is an i64 ConstantInt
/// in [0, Nelt) and travels as a CallDescriptor immediate.  Call site
/// must be CallingConv::C and non-vararg.  Ordinary tail, musttail,
/// bundles, noreturn, returns_twice, and complex ABI stay out.
/// Re-emitted via CallDescriptor (vector VReg in, vector VReg out,
/// immediate lane, pointer VReg).  SVE, arm.neon.vld*lane, half,
/// bfloat, dynamic or out-of-range lanes, and non-AS0 stay rejected.
/// No dedicated VM opcode and no extra +neon / +fullfp16 gate.
static bool isSupportedAArch64NeonLd1LaneIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::aarch64_neon_ld1lane)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.getFunctionType()->isVarArg())
    return false;
  if (Call.arg_size() != 3)
    return false;
  Type *VecTy = Call.getType();
  if (!isAArch64NeonStVectorType(VecTy))
    return false;
  const Value *Src = Call.getArgOperand(0);
  if (Src->getType() != VecTy || !isSupportedOrdinaryCallOperand(Src))
    return false;
  const Value *Lane = Call.getArgOperand(1);
  if (!Lane->getType()->isIntegerTy(64))
    return false;
  const auto *LaneImm = dyn_cast<ConstantInt>(Lane);
  if (!LaneImm)
    return false;
  const uint64_t Lanes =
      cast<FixedVectorType>(VecTy)->getNumElements();
  if (LaneImm->isNegative() || LaneImm->uge(Lanes))
    return false;
  if (!isCallImmediateArgument(Call, 1))
    return false;
  const Value *Ptr = Call.getArgOperand(2);
  return isSupportedPointerType(Ptr->getType()) &&
         isSupportedOrdinaryCallOperand(Ptr);
}

static unsigned getAArch64NeonLdExplodedFieldCount(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return 0;
  if (unsigned N = getAArch64NeonLdVectorCount(II->getIntrinsicID()))
    return N;
  return getAArch64NeonLdLaneVectorCount(II->getIntrinsicID());
}

static bool isSupportedAArch64NeonLdExtract(const ExtractValueInst &EV) {
  if (EV.getNumIndices() != 1)
    return false;
  const Value *Agg = EV.getAggregateOperand();
  // Fail-closed: a NEON ld/ldlane extract is never an ordinary
  // AggregateExtractValue.  Family IDs are a subset of reserved
  // producers; requiring both keeps a 16-byte pair off the flat frame
  // if either check regresses.
  if (!isReservedAggregateProducer(Agg))
    return false;
  const auto *Call = dyn_cast<CallInst>(Agg);
  if (!Call || !isSupportedAArch64NeonLdFamily(*Call))
    return false;
  const unsigned Index = EV.getIndices()[0];
  const auto *StructTy = dyn_cast<StructType>(Call->getType());
  if (!StructTy || Index >= StructTy->getNumElements())
    return false;
  return EV.getType() == StructTy->getElementType(Index);
}

/// Practical AArch64 ISel overloads for neon.vcopy.lane: dest, source,
/// and result are the same 128-bit integer vector — <16 x i8>, <8 x
/// i16>, <4 x i32>, or <2 x i64>.  64-bit, half, f32/f64, bfloat,
/// mismatched dest/src widths, and other anyvector forms stay out.
static bool isAArch64NeonVCopyLaneVectorType(const Type *Ty) {
  const auto *FixedTy = dyn_cast<FixedVectorType>(Ty);
  if (!FixedTy || !isSupportedFixedVectorType(Ty))
    return false;
  if (FixedTy->getPrimitiveSizeInBits().getFixedValue() != 128)
    return false;
  Type *Elt = FixedTy->getElementType();
  const unsigned N = FixedTy->getNumElements();
  if (Elt->isIntegerTy(8))
    return N == 16;
  if (Elt->isIntegerTy(16))
    return N == 8;
  if (Elt->isIntegerTy(32))
    return N == 4;
  if (Elt->isIntegerTy(64))
    return N == 2;
  return false;
}

/// Exact llvm.aarch64.neon.vcopy.lane only, matching
/// AdvSIMD_2Vector2Index_Intrinsic:
///   anyvector (anyvector dst, i64 dstidx, match<0> src, i64 srcidx)
/// This surface further requires dest == src == result and a supported
/// 128-bit integer ISel type.  Lane indices are i64 ConstantInt in
/// [0, N) and travel as CallDescriptor immediates (not ImmArg in the
/// TD).  Call site must be CallingConv::C and non-vararg.  Re-emitted
/// via CallDescriptor / vector VRegs; no dedicated VM opcode and no
/// extra +neon gate.
static bool isSupportedAArch64NeonVCopyLaneIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::aarch64_neon_vcopy_lane)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.getFunctionType()->isVarArg())
    return false;
  if (Call.arg_size() != 4)
    return false;
  Type *ResultTy = Call.getType();
  if (!isAArch64NeonVCopyLaneVectorType(ResultTy))
    return false;
  const Value *Dst = Call.getArgOperand(0);
  const Value *DstIdx = Call.getArgOperand(1);
  const Value *Src = Call.getArgOperand(2);
  const Value *SrcIdx = Call.getArgOperand(3);
  if (Dst->getType() != ResultTy || Src->getType() != ResultTy)
    return false;
  if (!isSupportedOrdinaryCallOperand(Dst) ||
      !isSupportedOrdinaryCallOperand(Src))
    return false;
  if (!DstIdx->getType()->isIntegerTy(64) ||
      !SrcIdx->getType()->isIntegerTy(64))
    return false;
  const auto *DstImm = dyn_cast<ConstantInt>(DstIdx);
  const auto *SrcImm = dyn_cast<ConstantInt>(SrcIdx);
  if (!DstImm || !SrcImm)
    return false;
  const uint64_t Lanes =
      cast<FixedVectorType>(ResultTy)->getNumElements();
  if (DstImm->uge(Lanes) || SrcImm->uge(Lanes))
    return false;
  return isCallImmediateArgument(Call, 1) && isCallImmediateArgument(Call, 3);
}

/// Practical AArch64 ISel vector overloads for neon.sqadd/uqadd/sqsub/
/// uqsub (SIMDThreeSameVector): 64-bit <8 x i8>/<4 x i16>/<2 x i32>
/// and 128-bit <16 x i8>/<8 x i16>/<4 x i32>/<2 x i64>.  Scalar
/// i8/i16 (no ISel), <1 x i64> (scalar SIMD path), half/bfloat/float,
/// Scalar i32/i64 is an independent surface.
/// <4 x i8>, i1, scalable, and other anyint forms stay out.
static bool isAArch64NeonSatIntVectorType(const Type *Ty) {
  const auto *FixedTy = dyn_cast<FixedVectorType>(Ty);
  if (!FixedTy || !isSupportedFixedVectorType(Ty))
    return false;
  Type *Elt = FixedTy->getElementType();
  const unsigned N = FixedTy->getNumElements();
  const unsigned Bits = FixedTy->getPrimitiveSizeInBits().getFixedValue();
  if (Bits != 64 && Bits != 128)
    return false;
  if (Elt->isIntegerTy(8))
    return N == 8 || N == 16;
  if (Elt->isIntegerTy(16))
    return N == 4 || N == 8;
  if (Elt->isIntegerTy(32))
    return N == 2 || N == 4;
  if (Elt->isIntegerTy(64))
    return N == 2;
  return false;
}

static bool isAArch64NeonSatIntID(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_sqadd:
  case Intrinsic::aarch64_neon_uqadd:
  case Intrinsic::aarch64_neon_sqsub:
  case Intrinsic::aarch64_neon_uqsub:
    return true;
  default:
    return false;
  }
}

/// Exact llvm.aarch64.neon.sqadd/uqadd/sqsub/uqsub only, matching
/// AdvSIMD_2IntArg_Intrinsic: anyint (match, match).  This surface
/// further requires a supported ISel integer vector (not scalar).
/// Call site must be CallingConv::C and non-vararg.  Re-emitted via
/// CallDescriptor / vector VRegs; no dedicated VM opcode and no extra
/// +neon gate.  Mixed-sign suqadd/usqadd is an independent
/// surface.  SVE, arm.neon.*, scalar overloads, and non-ISel
/// widths stay rejected.  Halving shadd/uhadd/srhadd/urhadd is
/// an independent surface.
static bool isSupportedAArch64NeonSatIntIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonSatIntID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.getFunctionType()->isVarArg())
    return false;
  if (Call.arg_size() != 2)
    return false;
  Type *ResultTy = Call.getType();
  if (!isAArch64NeonSatIntVectorType(ResultTy))
    return false;
  const Value *LHS = Call.getArgOperand(0);
  const Value *RHS = Call.getArgOperand(1);
  return LHS->getType() == ResultTy && RHS->getType() == ResultTy &&
         isSupportedOrdinaryCallOperand(LHS) &&
         isSupportedOrdinaryCallOperand(RHS);
}

/// ISel SIMDThreeScalarBHSD for neon.sqadd/uqadd/sqsub/uqsub:
/// only i32(i32,i32) and i64(i64,i64) (plus v1i64, kept out).
/// i8/i16 encodings exist but have empty patterns.  Clang
/// vqadds_s32 / vqaddd_s64 / vqadds_u32 / vqsubs_*.  Must not
/// lower to llvm.sadd.sat / generic add.  No last-token.
static bool isAArch64NeonScalarSatIntType(const Type *Ty) {
  if (!Ty || Ty->isVectorTy())
    return false;
  return Ty->isIntegerTy(32) || Ty->isIntegerTy(64);
}

/// Shape-only scalar llvm.aarch64.neon.sqadd/uqadd/sqsub/uqsub
/// (AdvSIMD_2IntArg: anyint (match, match)).  Ordinary tail is
/// left to the generic accept.  Vector satint is independent.
static bool isAArch64NeonScalarSatIntShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonSatIntID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 2 ||
      FTy->getNumParams() != 2)
    return false;
  Type *Ty = Call.getType();
  if (!Ty || FTy->getReturnType() != Ty || !isAArch64NeonScalarSatIntType(Ty))
    return false;
  const Value *A = Call.getArgOperand(0);
  const Value *B = Call.getArgOperand(1);
  if (!A || !B)
    return false;
  if (A->getType() != Ty || B->getType() != Ty ||
      FTy->getParamType(0) != Ty || FTy->getParamType(1) != Ty)
    return false;
  return isSupportedOrdinaryCallOperand(A) &&
         isSupportedOrdinaryCallOperand(B);
}

/// Well-shaped scalar sqadd/uqadd/sqsub/uqsub i32/i64.  Baseline
/// HasNEON; no extra last-token.  Re-emitted via CallDescriptor /
/// integer VRegs.  No ImmediateArguments.  No new opcode.
static bool isSupportedAArch64NeonScalarSatIntIntrinsic(const CallInst &Call) {
  return isAArch64NeonScalarSatIntShapeSupported(Call);
}

/// Practical AArch64 ISel vector overloads for neon.suqadd /
/// usqadd (SIMDTwoVectorBHSDTied, baseline HasNEON): 64-bit
/// <8 x i8>/<4 x i16>/<2 x i32> and 128-bit
/// <16 x i8>/<8 x i16>/<4 x i32>/<2 x i64>.  First operand is
/// the tied accumulator, second is the mixed-sign addend.
/// Scalar SIMDTwoScalarBHSDTied (i32/i64), v1i64, v4i8, i1,
/// 256-bit, SVE, and other anyint forms stay out.
static bool isAArch64NeonSuqaddVectorType(const Type *Ty) {
  const auto *FixedTy = dyn_cast<FixedVectorType>(Ty);
  if (!FixedTy || !isSupportedFixedVectorType(Ty))
    return false;
  Type *Elt = FixedTy->getElementType();
  const unsigned N = FixedTy->getNumElements();
  const unsigned Bits = FixedTy->getPrimitiveSizeInBits().getFixedValue();
  if (Bits != 64 && Bits != 128)
    return false;
  if (Elt->isIntegerTy(8))
    return N == 8 || N == 16;
  if (Elt->isIntegerTy(16))
    return N == 4 || N == 8;
  if (Elt->isIntegerTy(32))
    return N == 2 || N == 4;
  if (Elt->isIntegerTy(64))
    return N == 2;
  return false;
}

/// Exact llvm.aarch64.neon.suqadd / usqadd only
/// (AdvSIMD_2IntArg: anyint (match, match)).  Clang vuqadd /
/// vsqadd.  Accumulator is operand 0 (tied dest); operand 1 is
/// the other-signed addend.  Mixed signedness and saturation are
/// preserved by exact CallDescriptor replay; never rewritten to
/// add, min/max, or casts.  Call site must be CallingConv::C and
/// non-vararg; formals equal operands.  Re-emitted via
/// CallDescriptor / vector VRegs; no dedicated VM opcode and no
/// last-token gate.  Ordinary tail is left to the generic accept.
static bool isSupportedAArch64NeonSuqaddIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  if (ID != Intrinsic::aarch64_neon_suqadd &&
      ID != Intrinsic::aarch64_neon_usqadd)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 2 ||
      FTy->getNumParams() != 2)
    return false;
  Type *ResultTy = Call.getType();
  if (!isAArch64NeonSuqaddVectorType(ResultTy) ||
      FTy->getReturnType() != ResultTy)
    return false;
  for (unsigned I = 0; I < 2; ++I) {
    const Value *Arg = Call.getArgOperand(I);
    if (Arg->getType() != ResultTy || FTy->getParamType(I) != ResultTy ||
        !isSupportedOrdinaryCallOperand(Arg))
      return false;
  }
  return true;
}

/// ISel SIMDTwoScalarBHSDTied for neon.suqadd/usqadd: only
/// i32(i32,i32) and i64(i64,i64) (plus v1i64, kept out).
/// i8/i16 encodings exist but have empty patterns.  Clang
/// vuqadds_s32 / vuqaddd_s64 -> suqadd; vsqadds_u32 /
/// vsqaddd_u64 -> usqadd.  Operand 0 is the tied accumulator.
/// Must not lower to add/min/max.  No last-token.
static bool isAArch64NeonScalarSuqaddType(const Type *Ty) {
  if (!Ty || Ty->isVectorTy())
    return false;
  return Ty->isIntegerTy(32) || Ty->isIntegerTy(64);
}

/// Shape-only scalar llvm.aarch64.neon.suqadd / usqadd
/// (AdvSIMD_2IntArg: anyint (match, match)).  Ordinary tail is
/// left to the generic accept.  Vector suqadd is independent.
static bool isAArch64NeonScalarSuqaddShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  if (ID != Intrinsic::aarch64_neon_suqadd &&
      ID != Intrinsic::aarch64_neon_usqadd)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 2 ||
      FTy->getNumParams() != 2)
    return false;
  Type *Ty = Call.getType();
  if (!Ty || FTy->getReturnType() != Ty || !isAArch64NeonScalarSuqaddType(Ty))
    return false;
  const Value *Acc = Call.getArgOperand(0);
  const Value *Src = Call.getArgOperand(1);
  if (!Acc || !Src)
    return false;
  if (Acc->getType() != Ty || Src->getType() != Ty ||
      FTy->getParamType(0) != Ty || FTy->getParamType(1) != Ty)
    return false;
  return isSupportedOrdinaryCallOperand(Acc) &&
         isSupportedOrdinaryCallOperand(Src);
}

/// Well-shaped scalar suqadd/usqadd i32/i64.  Baseline HasNEON;
/// no extra last-token.  Re-emitted via CallDescriptor / integer
/// VRegs, operand order preserved.  No new opcode.
