/// Exact llvm.aarch64.neon.fminv/fmaxv/fminnmv/fmaxnmv only, matching
/// AdvSIMD_1VectorArg_Float_Across_Intrinsic: anyfloat (anyvector).
/// Further requires a scalar f32/f64 result whose type matches the
/// element type of one ISel f32/f64 vector argument (same widths as
/// ordinary neon fmin/fmax: <2 x float>/<4 x float>/<2 x double>).
/// Call site must be CallingConv::C and non-vararg.  Re-emitted via
/// CallDescriptor (vector VReg in, scalar float VReg out); no
/// dedicated VM opcode and no extra +neon / +fullfp16 gate.  Does not
/// widen the ordinary or pairwise ID lists.  half, integer sminv
/// (independent surface), faddv (independent surface), SVE,
/// arm.neon.*, generic vector.reduce.fmin, and non-ISel widths
/// stay rejected.
static bool isSupportedAArch64NeonFMinMaxReduceIntrinsic(
    const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonFMinMaxReduceID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.getFunctionType()->isVarArg())
    return false;
  if (Call.arg_size() != 1)
    return false;
  Type *ResultTy = Call.getType();
  if (!isSupportedScalarF32F64Type(ResultTy))
    return false;
  const Value *Vec = Call.getArgOperand(0);
  Type *VecTy = Vec->getType();
  if (!isAArch64NeonFMinMaxVectorType(VecTy))
    return false;
  if (cast<FixedVectorType>(VecTy)->getElementType() != ResultTy)
    return false;
  return isSupportedOrdinaryCallOperand(Vec);
}

/// Exact llvm.aarch64.neon.faddv only (AdvSIMD_1VectorArg_Float_Across:
/// anyfloat (anyvector)).  Clang vaddv_f32 / vaddvq_f32 / vaddvq_f64.
/// ISel legal pairs (AArch64InstrInfo.td, baseline HasNEON) lower to
/// a fixed FADDP tree, not a hardware FADDV:
///   f32 <- <2 x float>   FADDPv2i32p
///   f32 <- <4 x float>   FADDPv4f32 then FADDPv2i32p  ((a0+a1)+(a2+a3))
///   f64 <- <2 x double>  FADDPv2i64p
/// LLVM 15 has no neon.faddv half ISel; vaddv_f16 is SVE.
/// Must not lower to llvm.vector.reduce.fadd (start-value sequential
/// / reassoc), pairwise neon.faddp (vector result), element-wise
/// fadd, or unordered reassociation.  Preserve the FADDP tree by
/// exact CallDescriptor replay (vector VReg in, scalar float VReg
/// out).  Call site must be CallingConv::C and non-vararg; formals
/// equal operands.  No extra +neon / +fullfp16.  Ordinary tail is
/// left to the generic accept.  Any FastMathFlags are rejected by
/// the existing float-call FMF gate.  No new opcode.
static bool isSupportedAArch64NeonFAddvIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::aarch64_neon_faddv)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 1 ||
      FTy->getNumParams() != 1)
    return false;
  Type *ResultTy = Call.getType();
  if (!ResultTy || FTy->getReturnType() != ResultTy ||
      !isSupportedScalarF32F64Type(ResultTy))
    return false;
  const Value *Vec = Call.getArgOperand(0);
  if (!Vec)
    return false;
  Type *VecTy = Vec->getType();
  if (!isAArch64NeonFMinMaxVectorType(VecTy) ||
      FTy->getParamType(0) != VecTy)
    return false;
  if (cast<FixedVectorType>(VecTy)->getElementType() != ResultTy)
    return false;
  return isSupportedOrdinaryCallOperand(Vec);
}

