/// Exact llvm.aarch64.neon.frecpe/frsqrte (AdvSIMD_1FloatArg) and
/// frecps/frsqrts (AdvSIMD_2FloatArg) only.  Further requires the same
/// ISel f32/f64 vectors as neon fmin/fmax: <2 x float>/<4 x float>/
/// <2 x double>.  Estimate is unary; step is two same-type arguments.
/// Call site must be CallingConv::C and non-vararg.  Re-emitted via
/// CallDescriptor / vector VRegs; no dedicated VM opcode and no extra
/// +neon / +fullfp16 gate.  Scalar estimate/step is an independent
/// surface.  half/bfloat, v1f64, frecpx (independent
/// scalar-exponent surface), integer urecpe/ursqrte (independent
/// integer-estimate surface), SVE, and arm.neon.* stay rejected.
static bool isSupportedAArch64NeonReciprocalIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  const bool IsEstimate = isAArch64NeonReciprocalEstimateID(ID);
  const bool IsStep = isAArch64NeonReciprocalStepID(ID);
  if (!IsEstimate && !IsStep)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() || Call.doesNotReturn() ||
      Call.canReturnTwice() || hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  if (Call.getFunctionType()->isVarArg())
    return false;
  const unsigned ExpectedArgs = IsEstimate ? 1u : 2u;
  if (Call.arg_size() != ExpectedArgs)
    return false;
  Type *ResultTy = Call.getType();
  if (!isAArch64NeonFMinMaxVectorType(ResultTy))
    return false;
  for (unsigned I = 0; I < ExpectedArgs; ++I) {
    const Value *Arg = Call.getArgOperand(I);
    if (Arg->getType() != ResultTy || !isSupportedOrdinaryCallOperand(Arg))
      return false;
  }
  return true;
}

/// ISel SIMDTwoVectorS for neon.urecpe / ursqrte: only v2i32 / v4i32.
static bool isAArch64NeonIntReciprocalType(const Type *Ty) {
  const auto *FixedTy = dyn_cast<FixedVectorType>(Ty);
  if (!FixedTy || !isSupportedFixedVectorType(Ty))
    return false;
  return FixedTy->getElementType()->isIntegerTy(32) &&
         (FixedTy->getNumElements() == 2 || FixedTy->getNumElements() == 4);
}

static bool isAArch64NeonIntReciprocalID(Intrinsic::ID ID) {
  return ID == Intrinsic::aarch64_neon_urecpe ||
         ID == Intrinsic::aarch64_neon_ursqrte;
}

/// Exact llvm.aarch64.neon.urecpe / ursqrte
/// (AdvSIMD_1VectorArg: anyvector (match)).  Unsigned integer
/// reciprocal / reciprocal-sqrt estimate, not fdiv and not
/// frecpe/frecpx.  ISel SIMDTwoVectorS, baseline HasNEON, only
/// <2 x i32> / <4 x i32>.  No scalar integer ID.  SVE urecpe /
/// ursqrte stay out.  C, non-vararg, exact FTy.  CallDescriptor /
/// integer vector VRegs.  No last-token gate.  Ordinary tail is
/// left to the generic accept.
static bool isSupportedAArch64NeonIntReciprocalIntrinsic(
    const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonIntReciprocalID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 1 ||
      FTy->getNumParams() != 1)
    return false;
  Type *Ty = Call.getType();
  if (!Ty || FTy->getReturnType() != Ty || !isAArch64NeonIntReciprocalType(Ty))
    return false;
  const Value *Arg = Call.getArgOperand(0);
  if (!Arg || Arg->getType() != Ty || FTy->getParamType(0) != Ty ||
      !isSupportedOrdinaryCallOperand(Arg))
    return false;
  return true;
}

/// ISel-proven llvm.aarch64.neon.frecpx scalars: f32/f64
/// (SIMDFPTwoScalar HasNEONorSME) and f16 (plus HasFullFP16).
/// There is no vector FRECPX ISel (unlike frecpe).
static bool isAArch64NeonFRecpXType(const Type *Ty) {
  return Ty && (Ty->isFloatTy() || Ty->isDoubleTy() || Ty->isHalfTy());
}

/// Shape-only llvm.aarch64.neon.frecpx (AdvSIMD_1FloatArg:
/// anyfloat (match)).  Reciprocal exponent, not estimate/step
/// and not fdiv.  Vector instantiations are legal IR but have
/// no ISel.  Shape does not check +fullfp16 so a missing/final
/// -fullfp16 half stays "unsupported target feature".  Ordinary
/// tail is left to the generic accept.
static bool isAArch64NeonFRecpXShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::aarch64_neon_frecpx)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 1 ||
      FTy->getNumParams() != 1)
    return false;
  Type *Ty = Call.getType();
  if (!Ty || FTy->getReturnType() != Ty || !isAArch64NeonFRecpXType(Ty))
    return false;
  const Value *Arg = Call.getArgOperand(0);
  if (!Arg || Arg->getType() != Ty || FTy->getParamType(0) != Ty ||
      !isSupportedOrdinaryCallOperand(Arg))
    return false;
  return true;
}

/// Well-shaped neon.frecpx.  Half needs last-token +fullfp16
/// (HasFullFP16).  f32/f64 need no extra token.  Command-line
/// -mattr is never consulted.  Re-emitted via CallDescriptor /
/// scalar float VRegs.  No ImmediateArguments.  No new opcode.
static bool isSupportedAArch64NeonFRecpXIntrinsic(const CallInst &Call) {
  if (!isAArch64NeonFRecpXShapeSupported(Call))
    return false;
  if (!Call.getType()->isHalfTy())
    return true;
  const Function *Parent = Call.getFunction();
  return Parent && functionHasExplicitFullFP16Enabled(*Parent);
}

/// Scalar ISel (HasNEONorSME):
///   frecpe/frsqrte: SIMDFPTwoScalar + explicit f16/f32/f64 pats
///   frecps/frsqrts: SIMDFPThreeScalar
/// Half needs HasFullFP16 (FRECPEv1f16 / FRSQRTEv1f16 / *16).
/// Vector estimate/step is the independent Reciprocal surface.
/// frecpx is the independent scalar-exponent surface.  v1f64 /
/// bfloat / integer urecpe stay out.
static bool isAArch64NeonScalarReciprocalType(const Type *Ty) {
  if (!Ty || Ty->isVectorTy())
    return false;
  return Ty->isHalfTy() || Ty->isFloatTy() || Ty->isDoubleTy();
}

/// Shape-only scalar llvm.aarch64.neon.frecpe/frsqrte (unary)
/// and frecps/frsqrts (binary).  Must not lower to fdiv/fmul/fsub
/// (estimate tables and Newton 2-ab / (3-ab)/2 differ).  Shape
/// does not check +fullfp16 so a missing/final-disabled half
/// token stays "unsupported target feature".  Ordinary tail is
/// left to the generic accept.  Any FastMathFlags are rejected
/// by the existing float-call FMF gate.
static bool isAArch64NeonScalarReciprocalShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  const bool IsEstimate = isAArch64NeonReciprocalEstimateID(ID);
  const bool IsStep = isAArch64NeonReciprocalStepID(ID);
  if (!IsEstimate && !IsStep)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  const unsigned ExpectedArgs = IsEstimate ? 1u : 2u;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != ExpectedArgs ||
      FTy->getNumParams() != ExpectedArgs)
    return false;
  Type *Ty = Call.getType();
  if (!Ty || FTy->getReturnType() != Ty ||
      !isAArch64NeonScalarReciprocalType(Ty))
    return false;
  for (unsigned I = 0; I < ExpectedArgs; ++I) {
    const Value *Arg = Call.getArgOperand(I);
    if (!Arg || Arg->getType() != Ty || FTy->getParamType(I) != Ty ||
        !isSupportedOrdinaryCallOperand(Arg))
      return false;
  }
  return true;
}

/// Well-shaped scalar frecpe/frsqrte/frecps/frsqrts.  Half needs
/// last-token +fullfp16 (HasFullFP16).  f32/f64 are baseline
/// HasNEON and need no extra token.  Command-line -mattr is
/// never consulted.  +fp16fml does not count as +fullfp16.
/// Re-emitted via CallDescriptor / scalar float VRegs.  No
/// ImmediateArguments.  No new opcode.
static bool isSupportedAArch64NeonScalarReciprocalIntrinsic(
    const CallInst &Call) {
  if (!isAArch64NeonScalarReciprocalShapeSupported(Call))
    return false;
  if (!Call.getType()->isHalfTy())
    return true;
  const Function *Parent = Call.getFunction();
  return Parent && functionHasExplicitFullFP16Enabled(*Parent);
}

/// Exact ISel form of llvm.aarch64.neon.pmull: AdvSIMD_2VectorArg_Long
/// instantiated as <8 x i16> (@llvm.aarch64.neon.pmull.v8i16)
/// (<8 x i8>, <8 x i8>).  Matches SIMDDifferentThreeVectorBD PMULLv8i8
/// (HasNEON / baseline AdvSIMD).  Other Long instantiations (v16i16,
/// v4i32, v2i64, smull/umull) have no direct PMULL pattern.
static bool isAArch64NeonPmullV8ShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::aarch64_neon_pmull)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 2 ||
      FTy->getNumParams() != 2)
    return false;
  Type *ResultTy = Call.getType();
  const auto *ResVT = dyn_cast<FixedVectorType>(ResultTy);
  if (!ResVT || !ResVT->getElementType()->isIntegerTy(16) ||
      ResVT->getNumElements() != 8 || FTy->getReturnType() != ResultTy)
    return false;
  for (unsigned I = 0; I < 2; ++I) {
    const Value *Arg = Call.getArgOperand(I);
    const auto *ArgVT = dyn_cast<FixedVectorType>(Arg->getType());
    if (!ArgVT || !ArgVT->getElementType()->isIntegerTy(8) ||
        ArgVT->getNumElements() != 8 || FTy->getParamType(I) != Arg->getType() ||
        !isSupportedOrdinaryCallOperand(Arg))
      return false;
  }
  return true;
}

/// Exact llvm.aarch64.neon.pmull64: <16 x i8> (i64, i64), IntrNoMem.
/// ISel: PMULLv1i64 (HasAES).  PMULLv2i64 is a high-lane combine, not
/// a second call signature.  Shape does not check +aes so a feature
/// miss stays "unsupported target feature".
static bool isAArch64NeonPmull64ShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::aarch64_neon_pmull64)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 2 ||
      FTy->getNumParams() != 2)
    return false;
  Type *ResultTy = Call.getType();
  const auto *ResVT = dyn_cast<FixedVectorType>(ResultTy);
  if (!ResVT || !ResVT->getElementType()->isIntegerTy(8) ||
      ResVT->getNumElements() != 16 || FTy->getReturnType() != ResultTy)
    return false;
  for (unsigned I = 0; I < 2; ++I) {
    const Value *Arg = Call.getArgOperand(I);
    if (!Arg->getType()->isIntegerTy(64) ||
        FTy->getParamType(I) != Arg->getType() ||
        !isSupportedOrdinaryCallOperand(Arg))
      return false;
  }
  return true;
}

/// Proven NEON polynomial-multiply long only.  8-bit pmull is
/// baseline HasNEON.  pmull64 requires last-token function +aes
/// (HasAES / FEAT_AES).  Re-emitted via CallDescriptor: v8i8/v8i16
/// and v16i8 use the vector VReg frame; pmull64 i64 args use the
/// integer frame.  No dedicated VM opcode.  smull/umull, same-width
/// pmul, SVE pmullb/pmullt, crypto aese/aesd, and other widths stay
/// out.  Element-wise pmul is a separate surface.
static bool isSupportedAArch64NeonPmullIntrinsic(const CallInst &Call) {
  if (isAArch64NeonPmullV8ShapeSupported(Call))
    return true;
  if (!isAArch64NeonPmull64ShapeSupported(Call))
    return false;
  const Function *Parent = Call.getFunction();
  return Parent && functionHasExplicitAESEnabled(*Parent);
}

/// Exact ISel forms of llvm.aarch64.neon.pmul (AdvSIMD_2VectorArg):
///   <8 x i8>  (v8i8, v8i8)   -> PMULv8i8
///   <16 x i8> (v16i8, v16i8) -> PMULv16i8
/// SIMDThreeSameVectorB, baseline HasNEON.  Result and both operands
/// are the same type.  v8i16 / v4i16 / v4i32 / v4i8 / float have no
/// PMUL pattern.  No +aes gate (unlike pmull64).  Re-emitted via
/// CallDescriptor / vector VRegs; no dedicated VM opcode.  Shape does
/// not reject ordinary tail so the generic accept keeps that
/// diagnostic.  smull/umull/pmull, SVE pmul, and crypto aese stay out.
static bool isSupportedAArch64NeonPmulIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::aarch64_neon_pmul)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 2 ||
      FTy->getNumParams() != 2)
    return false;
  Type *ResultTy = Call.getType();
  const auto *ResVT = dyn_cast<FixedVectorType>(ResultTy);
  if (!ResVT || !ResVT->getElementType()->isIntegerTy(8) ||
      (ResVT->getNumElements() != 8 && ResVT->getNumElements() != 16) ||
      FTy->getReturnType() != ResultTy)
    return false;
  for (unsigned I = 0; I < 2; ++I) {
    const Value *Arg = Call.getArgOperand(I);
    if (Arg->getType() != ResultTy || FTy->getParamType(I) != ResultTy ||
        !isSupportedOrdinaryCallOperand(Arg))
      return false;
  }
  return true;
}

/// ISel-proven same-width HS vectors for neon.sqdmulh / sqrdmulh
/// and neon.sqrdmlah / sqrdmlsh (SIMDThreeSameVectorHS /
/// SIMDThreeSameVectorSQRDMLxHTiedHS): v4i16 / v8i16 / v2i32 / v4i32.
/// Scalar i32 is an independent surface. Scalar i16, v8i8, v2i64,
/// v1i32, half/bfloat stay out.
static bool isAArch64NeonSqdmulhVectorType(const Type *Ty) {
  const auto *FixedTy = dyn_cast<FixedVectorType>(Ty);
  if (!FixedTy || !isSupportedFixedVectorType(Ty))
    return false;
  Type *Elt = FixedTy->getElementType();
  const unsigned N = FixedTy->getNumElements();
  const unsigned Bits = FixedTy->getPrimitiveSizeInBits().getFixedValue();
  if (Bits != 64 && Bits != 128)
    return false;
  if (Elt->isIntegerTy(16))
    return N == 4 || N == 8;
  if (Elt->isIntegerTy(32))
    return N == 2 || N == 4;
  return false;
}

static bool isAArch64NeonSqdmulhVectorID(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_sqdmulh:
  case Intrinsic::aarch64_neon_sqrdmulh:
    return true;
  default:
    return false;
  }
}

static bool isAArch64NeonSqdmulhLaneID(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_sqdmulh_lane:
  case Intrinsic::aarch64_neon_sqrdmulh_lane:
    return true;
  default:
    return false;
  }
}

static bool isAArch64NeonSqdmulhLaneQID(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_sqdmulh_laneq:
  case Intrinsic::aarch64_neon_sqrdmulh_laneq:
    return true;
  default:
    return false;
  }
}

/// Exact llvm.aarch64.neon.sqdmulh / sqrdmulh (AdvSIMD_2IntArg) and
/// .lane / .laneq (AdvSIMD_2VectorArg_Lane: anyint, match, anyint,
/// i32).  Vector form: result and both args are the same ISel i16/i32
/// vector.  Lane form: result/arg0 same ISel vector; arg1 is the
/// same-element 64-bit (lane) or 128-bit (laneq) index vector; arg2 is
/// an i32 ConstantInt in [0, Nsrc) kept as a CallDescriptor immediate.
/// Call site must be CallingConv::C and non-vararg.  Re-emitted via
/// CallDescriptor / vector VRegs.  No dedicated VM opcode and no +rdm
/// / +neon gate.  sqrdmlah/sqrdmlsh, scalar i32 (independent
/// surface), i8/i64, SVE, and other multiplies stay out.  Ordinary
/// tail is rejected at the generic accept.
static bool isSupportedAArch64NeonSqdmulhIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II)
    return false;
  const Intrinsic::ID ID = II->getIntrinsicID();
  const bool IsVector = isAArch64NeonSqdmulhVectorID(ID);
  const bool IsLane = isAArch64NeonSqdmulhLaneID(ID);
  const bool IsLaneQ = isAArch64NeonSqdmulhLaneQID(ID);
  if (!IsVector && !IsLane && !IsLaneQ)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  const unsigned ExpectedArgs = IsVector ? 2u : 3u;
  if (!FTy || FTy->isVarArg() || Call.arg_size() != ExpectedArgs ||
      FTy->getNumParams() != ExpectedArgs)
    return false;
  Type *ResultTy = Call.getType();
  if (!isAArch64NeonSqdmulhVectorType(ResultTy) ||
      FTy->getReturnType() != ResultTy)
    return false;
  const Value *LHS = Call.getArgOperand(0);
  if (LHS->getType() != ResultTy || FTy->getParamType(0) != ResultTy ||
      !isSupportedOrdinaryCallOperand(LHS))
    return false;
  if (IsVector) {
    const Value *RHS = Call.getArgOperand(1);
    return RHS->getType() == ResultTy && FTy->getParamType(1) == ResultTy &&
           isSupportedOrdinaryCallOperand(RHS);
  }
  const Value *IdxVec = Call.getArgOperand(1);
  const auto *IdxVT = dyn_cast<FixedVectorType>(IdxVec->getType());
  const auto *ResVT = cast<FixedVectorType>(ResultTy);
  if (!IdxVT || IdxVT->getElementType() != ResVT->getElementType() ||
      !isSupportedFixedVectorType(IdxVec->getType()) ||
      FTy->getParamType(1) != IdxVec->getType() ||
      !isSupportedOrdinaryCallOperand(IdxVec))
    return false;
  const unsigned IdxBits =
      IdxVT->getPrimitiveSizeInBits().getFixedValue();
  if (IsLane && IdxBits != 64)
    return false;
  if (IsLaneQ && IdxBits != 128)
    return false;
  const Value *Lane = Call.getArgOperand(2);
  if (!Lane->getType()->isIntegerTy(32) || FTy->getParamType(2) != Lane->getType())
    return false;
  const auto *LaneImm = dyn_cast<ConstantInt>(Lane);
  if (!LaneImm || LaneImm->isNegative() ||
      LaneImm->uge(IdxVT->getNumElements()))
    return false;
  return isCallImmediateArgument(Call, 2);
}

/// ISel SIMDThreeScalarHS for neon.sqdmulh/sqrdmulh: only
/// i32(i32, i32).  i16 encoding exists but has empty patterns;
/// clang vqdmulhh_s16 / vqrdmulhh_s16 Use64BitVectors (never
/// scalar i16).  i8/i64 have no scalar ISel.  Clang
/// vqdmulhs_s32 / vqrdmulhs_s32.  Must not lower to generic mul.
/// INT_MIN*INT_MIN saturates to INT_MAX.  No last-token.  Lane
/// is extractelement + this ID (no scalar lane IR).
static bool isAArch64NeonScalarSqdmulhType(const Type *Ty) {
  if (!Ty || Ty->isVectorTy())
    return false;
  return Ty->isIntegerTy(32);
}

/// Shape-only scalar llvm.aarch64.neon.sqdmulh / sqrdmulh
/// (AdvSIMD_2IntArg: anyint (match, match)).  Ordinary tail is
/// left to the generic accept.  Vector sqdmulh is independent.
static bool isAArch64NeonScalarSqdmulhShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonSqdmulhVectorID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 2 ||
      FTy->getNumParams() != 2)
    return false;
  Type *Ty = Call.getType();
  if (!Ty || FTy->getReturnType() != Ty ||
      !isAArch64NeonScalarSqdmulhType(Ty))
    return false;
  const Value *A = Call.getArgOperand(0);
  const Value *B = Call.getArgOperand(1);
  if (!A || !B)
    return false;
  if (A->getType() != Ty || B->getType() != Ty ||
      FTy->getParamType(0) != Ty || FTy->getParamType(1) != Ty)
    return false;
  return isSupportedOrdinaryCallOperand(A) &&
         isSupportedOrdinaryCallOperand(B);
}

/// Well-shaped scalar sqdmulh/sqrdmulh i32.  Baseline HasNEON;
/// no extra last-token.  Re-emitted via CallDescriptor /
/// integer VRegs.  No ImmediateArguments.  No new opcode.
static bool isSupportedAArch64NeonScalarSqdmulhIntrinsic(
    const CallInst &Call) {
  return isAArch64NeonScalarSqdmulhShapeSupported(Call);
}

static bool isAArch64NeonSqrdmlahID(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_sqrdmlah:
  case Intrinsic::aarch64_neon_sqrdmlsh:
    return true;
  default:
    return false;
  }
}

/// Shape-only llvm.aarch64.neon.sqrdmlah / sqrdmlsh (AdvSIMD_3IntArg:
/// anyint, match, match, match).  Result and all three args are the
/// same ISel HS i16/i32 vector.  Does not check +rdm so a feature miss
/// stays "unsupported target feature".  NEON has no .lane/.laneq IR
/// IDs (clang splat + 3-arg; ISel SIMDIndexedSQRDMLxHSDTied matches
/// duplane of this form).  SVE lane IDs stay out.  Ordinary tail is
/// left to the generic accept.
static bool isAArch64NeonSqrdmlahShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonSqrdmlahID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 3 ||
      FTy->getNumParams() != 3)
    return false;
  Type *ResultTy = Call.getType();
  if (!isAArch64NeonSqdmulhVectorType(ResultTy) ||
      FTy->getReturnType() != ResultTy)
    return false;
  for (unsigned I = 0; I < 3; ++I) {
    const Value *Arg = Call.getArgOperand(I);
    if (Arg->getType() != ResultTy || FTy->getParamType(I) != ResultTy ||
        !isSupportedOrdinaryCallOperand(Arg))
      return false;
  }
  return true;
}

