/// ISel BHS across-lane integer vectors for neon.saddv/uaddv/
/// sminv/uminv/smaxv/umaxv: 64-bit <8 x i8>/<4 x i16>/<2 x i32>
/// and 128-bit <16 x i8>/<8 x i16>/<4 x i32>.  v2i32 is the
/// pairwise ADDPv2i32 / *MAXP/*MINP fallback, not ADDV.4s.
/// v2i64 is addv-only (ADDPv2i64p).  v4i8 / v1i64 stay out.
static bool isAArch64NeonIntAcrossLaneVectorType(const Type *Ty) {
  const auto *FixedTy = dyn_cast<FixedVectorType>(Ty);
  if (!FixedTy || !isSupportedFixedVectorType(Ty))
    return false;
  Type *Elt = FixedTy->getElementType();
  const unsigned N = FixedTy->getNumElements();
  const unsigned Bits = FixedTy->getPrimitiveSizeInBits().getFixedValue();
  if (Bits != 64 && Bits != 128)
    return false;
  if (Elt->isIntegerTy(8))
    return N == 8 || N == 16;
  if (Elt->isIntegerTy(16))
    return N == 4 || N == 8;
  if (Elt->isIntegerTy(32))
    return N == 2 || N == 4;
  return false;
}

static bool isAArch64NeonIntAcrossReduceID(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_saddv:
  case Intrinsic::aarch64_neon_uaddv:
  case Intrinsic::aarch64_neon_sminv:
  case Intrinsic::aarch64_neon_uminv:
  case Intrinsic::aarch64_neon_smaxv:
  case Intrinsic::aarch64_neon_umaxv:
    return true;
  default:
    return false;
  }
}

/// Clang/ISel result vs argument for integer across-lane reduce.
/// Genuine forms are i32 from the BHS/v2i32 vectors above, plus
/// i64 from <2 x i64> for saddv/uaddv only.  i8/i16 results are
/// clang truncs of i32, not the intrinsic.  saddlv/uaddlv
/// (independent surface), faddv, and min/max on v2i64 stay out.
static bool isAArch64NeonIntAcrossReducePair(Intrinsic::ID ID,
                                            const Type *ResTy,
                                            const Type *ArgTy) {
  const auto *ArgVT = dyn_cast<FixedVectorType>(ArgTy);
  if (!ArgVT || !ResTy->isIntegerTy() || !isSupportedFixedVectorType(ArgTy))
    return false;
  if (ArgVT->getElementType()->isIntegerTy(64) &&
      ArgVT->getNumElements() == 2 &&
      ArgVT->getPrimitiveSizeInBits().getFixedValue() == 128) {
    if (ID != Intrinsic::aarch64_neon_saddv &&
        ID != Intrinsic::aarch64_neon_uaddv)
      return false;
    return ResTy->isIntegerTy(64);
  }
  return ResTy->isIntegerTy(32) && isAArch64NeonIntAcrossLaneVectorType(ArgTy);
}

/// Exact llvm.aarch64.neon.saddv/uaddv/sminv/uminv/smaxv/umaxv
/// (AdvSIMD_1VectorArg_Int_Across: anyint (anyvector)).  Unary.
/// Call site must be CallingConv::C and non-vararg; formals equal
/// operands.  Re-emitted via CallDescriptor (vector VReg in, integer
/// VReg out).  Does not fold into llvm.vector.reduce.*.  No last-token
/// gate.  Ordinary tail is left to the generic accept.
static bool isSupportedAArch64NeonIntAcrossReduceIntrinsic(
    const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonIntAcrossReduceID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 1 ||
      FTy->getNumParams() != 1)
    return false;
  Type *ResultTy = Call.getType();
  if (FTy->getReturnType() != ResultTy)
    return false;
  const Value *Arg = Call.getArgOperand(0);
  return isAArch64NeonIntAcrossReducePair(II->getIntrinsicID(), ResultTy,
                                          Arg->getType()) &&
         FTy->getParamType(0) == Arg->getType() &&
         isSupportedOrdinaryCallOperand(Arg);
}

static bool isAArch64NeonAddlvID(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_saddlv:
  case Intrinsic::aarch64_neon_uaddlv:
    return true;
  default:
    return false;
  }
}

/// ISel SIMDAcrossLanesSigned/UnsignedLong for neon.saddlv/uaddlv
/// (HasNEON): i32 from v8i8/v16i8/v4i16/v8i16, i64 from v4i32.
/// Clang vaddlv_s32/u32 on <2 x i32> is the same IR ID but ISel
/// SADDLP/UADDLP (no hardware SADDLV.2s).  i8/i16 results are
/// clang truncs of i32.  Must not lower to saddv, saddlp, or
/// llvm.vector.reduce.add.  v4i8 / v2i64 / 256-bit stay out.
static bool isAArch64NeonAddlvPair(const Type *ResTy, const Type *ArgTy) {
  const auto *ArgVT = dyn_cast<FixedVectorType>(ArgTy);
  if (!ArgVT || !ResTy->isIntegerTy() || !isSupportedFixedVectorType(ArgTy))
    return false;
  Type *Elt = ArgVT->getElementType();
  const unsigned N = ArgVT->getNumElements();
  const unsigned Bits = ArgVT->getPrimitiveSizeInBits().getFixedValue();
  if (Bits != 64 && Bits != 128)
    return false;
  if (Elt->isIntegerTy(8) && (N == 8 || N == 16))
    return ResTy->isIntegerTy(32);
  if (Elt->isIntegerTy(16) && (N == 4 || N == 8))
    return ResTy->isIntegerTy(32);
  if (Elt->isIntegerTy(32) && (N == 2 || N == 4))
    return ResTy->isIntegerTy(64);
  return false;
}

/// Exact llvm.aarch64.neon.saddlv/uaddlv only
/// (AdvSIMD_1VectorArg_Int_Across: anyint (anyvector)).  Clang
/// vaddlv.  Widening across-lane sum: result is one element
/// wider than the source.  Preserve by exact CallDescriptor
/// replay (vector VReg in, integer VReg out).  Call site must
/// be CallingConv::C and non-vararg; formals equal operands.
/// No last-token gate.  Ordinary tail is left to the generic
/// accept.  No new opcode.
static bool isSupportedAArch64NeonAddlvIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonAddlvID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 1 ||
      FTy->getNumParams() != 1)
    return false;
  Type *ResultTy = Call.getType();
  if (!ResultTy || FTy->getReturnType() != ResultTy)
    return false;
  const Value *Arg = Call.getArgOperand(0);
  if (!Arg)
    return false;
  return isAArch64NeonAddlvPair(ResultTy, Arg->getType()) &&
         FTy->getParamType(0) == Arg->getType() &&
         isSupportedOrdinaryCallOperand(Arg);
}

static bool isAArch64NeonSatShiftID(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_sqshl:
  case Intrinsic::aarch64_neon_uqshl:
  case Intrinsic::aarch64_neon_sqrshl:
  case Intrinsic::aarch64_neon_uqrshl:
    return true;
  default:
    return false;
  }
}

/// Exact llvm.aarch64.neon.sqshl/uqshl and the directly adjacent
/// saturating-rounding pair sqrshl/uqrshl (AdvSIMD_2IntArg:
/// anyint (match, match)).  ISel SIMDThreeSameVector, same integer
/// widths as neon.sqadd: v8i8/v16i8/v4i16/v8i16/v2i32/v4i32/v2i64.
/// Both operands are same-type vectors (per-lane shift, possibly
/// negative).  Constant amounts may ISel to SQSHL_I after replay;
/// they are not ImmArg.  Scalar i32/i64 is an independent surface.
/// v1i64, sshl/ushl/srshl/urshl (independent non-saturating
/// surface), sqshlu (independent immediate signed->unsigned
/// surface), saturating narrowing (independent surface), and SVE
/// stay out.  C, non-vararg,
/// exact FTy.
/// CallDescriptor / vector VRegs.  No last-token gate.  Ordinary
/// tail is left to the generic accept.
static bool isSupportedAArch64NeonSatShiftIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonSatShiftID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 2 ||
      FTy->getNumParams() != 2)
    return false;
  Type *ResultTy = Call.getType();
  if (!isAArch64NeonSatIntVectorType(ResultTy) ||
      FTy->getReturnType() != ResultTy)
    return false;
  for (unsigned I = 0; I < 2; ++I) {
    const Value *Arg = Call.getArgOperand(I);
    if (Arg->getType() != ResultTy || FTy->getParamType(I) != ResultTy ||
        !isSupportedOrdinaryCallOperand(Arg))
      return false;
  }
  return true;
}

/// ISel SIMDThreeScalarBHSD for neon.sqshl/uqshl/sqrshl/uqrshl:
/// only i32(i32,i32) and i64(i64,i64) (plus v1i64, kept out).
/// i8/i16 encodings exist but have empty patterns; clang
/// vqshlb_s8 / vqshlh_s16 Use64BitVectors.  Clang vqshls_s32 /
/// vqshld_s64 / vqshls_u32 / vqrshls_s32 / vqrshld_s64.
/// Must not lower to generic shl or llvm.sshl.sat.  Shift
/// amount is signed (negative = right).  SQRSHL/UQRSHL round
/// on right shift.  Constant positive amounts may ISel to
/// SQSHL #imm before VMP; replay uses integer VRegs so llc
/// keeps the register form.  No last-token.
static bool isAArch64NeonScalarSatShiftType(const Type *Ty) {
  if (!Ty || Ty->isVectorTy())
    return false;
  return Ty->isIntegerTy(32) || Ty->isIntegerTy(64);
}

/// Shape-only scalar llvm.aarch64.neon.sqshl/uqshl/sqrshl/uqrshl
/// (AdvSIMD_2IntArg: anyint (match, match)).  Ordinary tail is
/// left to the generic accept.  Vector satshift is independent.
static bool isAArch64NeonScalarSatShiftShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonSatShiftID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 2 ||
      FTy->getNumParams() != 2)
    return false;
  Type *Ty = Call.getType();
  if (!Ty || FTy->getReturnType() != Ty ||
      !isAArch64NeonScalarSatShiftType(Ty))
    return false;
  const Value *A = Call.getArgOperand(0);
  const Value *B = Call.getArgOperand(1);
  if (!A || !B)
    return false;
  if (A->getType() != Ty || B->getType() != Ty ||
      FTy->getParamType(0) != Ty || FTy->getParamType(1) != Ty)
    return false;
  return isSupportedOrdinaryCallOperand(A) &&
         isSupportedOrdinaryCallOperand(B);
}

/// Well-shaped scalar sqshl/uqshl/sqrshl/uqrshl i32/i64.
/// Baseline HasNEON; no extra last-token.  Re-emitted via
/// CallDescriptor / integer VRegs.  No ImmediateArguments
/// (shift is a register operand, not ImmArg).  No new opcode.
static bool isSupportedAArch64NeonScalarSatShiftIntrinsic(
    const CallInst &Call) {
  return isAArch64NeonScalarSatShiftShapeSupported(Call);
}

/// ISel vecshiftL*: Imm < EltBits (0..EltBits-1).  SQSHLU has no
/// register form; tryCombineShiftImm requires a constant splat of
/// the element width.
static bool isAArch64NeonSqshluSplatImmInRange(const Type *VecTy,
                                              const Value *Amt) {
  const auto *VT = dyn_cast<FixedVectorType>(VecTy);
  if (!VT || !Amt || Amt->getType() != VecTy)
    return false;
  Type *Elt = VT->getElementType();
  if (!Elt || !Elt->isIntegerTy())
    return false;
  const unsigned EltBits = Elt->getIntegerBitWidth();
  const auto *C = dyn_cast<Constant>(Amt);
  if (!C)
    return false;
  const Constant *Splat = C->getSplatValue();
  if (!Splat)
    return false;
  const auto *CI = dyn_cast<ConstantInt>(Splat);
  if (!CI || CI->isNegative())
    return false;
  return CI->getZExtValue() < EltBits;
}

/// Exact llvm.aarch64.neon.sqshlu (AdvSIMD_2IntArg: anyint
/// (match, match)).  Clang vqshlu_n splat-fills arg 1.
/// ISel SIMDVectorLShiftBHSD SQSHLU / AArch64sqshlui after
/// tryCombineShiftImm: v8i8/v16i8/v4i16/v8i16/v2i32/v4i32/v2i64,
/// vecshiftL* 0..EltBits-1.  No register-form SQSHLU.  Must not
/// rewrite to sqshl (signed sat), ushl, or generic shl.
/// Signed-to-unsigned saturate: negatives become 0.  Scalar
/// i32/i64 is an independent surface.  v1i64 stays out.  SVE
/// stays out.
/// Arg 1 stays on ImmediateArguments so ISel still sees a
/// constant splat.  C, non-vararg, exact FTy.  CallDescriptor /
/// vector VRegs.  No last-token gate.  Ordinary tail is left to
/// the generic accept.
static bool isSupportedAArch64NeonSqshluIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::aarch64_neon_sqshlu)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 2 ||
      FTy->getNumParams() != 2)
    return false;
  Type *ResultTy = Call.getType();
  if (!isAArch64NeonSatIntVectorType(ResultTy) ||
      FTy->getReturnType() != ResultTy)
    return false;
  const Value *Src = Call.getArgOperand(0);
  const Value *Amt = Call.getArgOperand(1);
  if (!Src || !Amt)
    return false;
  if (Src->getType() != ResultTy || FTy->getParamType(0) != ResultTy ||
      !isSupportedOrdinaryCallOperand(Src))
    return false;
  if (Amt->getType() != ResultTy || FTy->getParamType(1) != ResultTy)
    return false;
  if (!isAArch64NeonSqshluSplatImmInRange(ResultTy, Amt))
    return false;
  return isCallImmediateArgument(Call, 1);
}

/// ISel SIMDScalarLShiftBHSD SQSHLU / AArch64sqshlui after
/// tryCombineShiftImm: only i32(i32, i32 imm 0..31) and
/// i64(i64, i64 imm 0..63).  i8/i16 encodings exist but have
/// empty patterns; clang vqshlub_n_s8 / vqshluh_n_s16
/// Use64BitVectors.  Clang vqshlus_n_s32 / vqshlud_n_s64.
/// No register-form SQSHLU (dynamic / OOB / negative cannot
/// select).  Must not lower to sqshl / ushl / generic shl.
/// Negatives saturate to 0.  Amount is not ImmArg; keep it on
/// ImmediateArguments (isCallImmediateArgument already keys
/// sqshlu arg 1 as Constant).  No last-token.
static bool isAArch64NeonScalarSqshluType(const Type *Ty) {
  if (!Ty || Ty->isVectorTy())
    return false;
  return Ty->isIntegerTy(32) || Ty->isIntegerTy(64);
}

static bool isAArch64NeonScalarSqshluImmInRange(const Type *Ty,
                                               const Value *Amt) {
  if (!isAArch64NeonScalarSqshluType(Ty) || !Amt || Amt->getType() != Ty)
    return false;
  const auto *CI = dyn_cast<ConstantInt>(Amt);
  if (!CI || CI->isNegative())
    return false;
  const unsigned EltBits = Ty->getIntegerBitWidth();
  return CI->getZExtValue() < EltBits;
}

/// Shape-only scalar llvm.aarch64.neon.sqshlu (AdvSIMD_2IntArg).
/// Ordinary tail is left to the generic accept.  Vector sqshlu
/// is independent.
static bool isAArch64NeonScalarSqshluShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::aarch64_neon_sqshlu)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 2 ||
      FTy->getNumParams() != 2)
    return false;
  Type *Ty = Call.getType();
  if (!Ty || FTy->getReturnType() != Ty ||
      !isAArch64NeonScalarSqshluType(Ty))
    return false;
  const Value *Src = Call.getArgOperand(0);
  const Value *Amt = Call.getArgOperand(1);
  if (!Src || !Amt)
    return false;
  if (Src->getType() != Ty || FTy->getParamType(0) != Ty ||
      !isSupportedOrdinaryCallOperand(Src))
    return false;
  if (Amt->getType() != Ty || FTy->getParamType(1) != Ty)
    return false;
  if (!isAArch64NeonScalarSqshluImmInRange(Ty, Amt))
    return false;
  return isCallImmediateArgument(Call, 1);
}

/// Well-shaped scalar sqshlu i32/i64 with in-range ConstantInt
/// amount.  Baseline HasNEON.  Re-emitted via CallDescriptor /
/// integer VRegs + ImmediateArguments.  No new opcode.
static bool isSupportedAArch64NeonScalarSqshluIntrinsic(
    const CallInst &Call) {
  return isAArch64NeonScalarSqshluShapeSupported(Call);
}

static bool isAArch64NeonVarShiftID(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_sshl:
  case Intrinsic::aarch64_neon_ushl:
  case Intrinsic::aarch64_neon_srshl:
  case Intrinsic::aarch64_neon_urshl:
    return true;
  default:
    return false;
  }
}

/// Exact llvm.aarch64.neon.sshl/ushl and rounding srshl/urshl
/// (AdvSIMD_2IntArg: anyint (match, match)).  ISel
/// SIMDThreeSameVector, same integer widths as neon.sqshl:
/// v8i8/v16i8/v4i16/v8i16/v2i32/v4i32/v2i64.  Per-lane signed
/// shift amounts (negative means right).  srshl/urshl round;
/// sshl/ushl do not saturate.  Constant amounts may ISel to
/// VSHL / SRSHR_I after replay; they are not ImmArg.  Scalar
/// i64 is an independent surface.  i32 cannot select.  v1i64,
/// saturating sqshl/uqshl/sqrshl/uqrshl, sqshlu (independent
/// immediate surface), saturating narrowing (independent
/// surface), and SVE stay out.
/// C, non-vararg, exact FTy.
/// CallDescriptor / vector VRegs.  No last-token gate.  Ordinary
/// tail is left to the generic accept.
static bool isSupportedAArch64NeonVarShiftIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonVarShiftID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 2 ||
      FTy->getNumParams() != 2)
    return false;
  Type *ResultTy = Call.getType();
  if (!isAArch64NeonSatIntVectorType(ResultTy) ||
      FTy->getReturnType() != ResultTy)
    return false;
  for (unsigned I = 0; I < 2; ++I) {
    const Value *Arg = Call.getArgOperand(I);
    if (Arg->getType() != ResultTy || FTy->getParamType(I) != ResultTy ||
        !isSupportedOrdinaryCallOperand(Arg))
      return false;
  }
  return true;
}

/// Extra Pats in AArch64InstrInfo.td for neon.sshl/ushl/srshl/
/// urshl: only i64(i64, i64) -> *SHLv1i64.  SIMDThreeScalarD
/// itself matches v1i64 only (kept out).  i32 CannotYetSelect.
/// Clang vshld_s64 / vshld_u64 / vrshld_s64 / vrshld_u64.
/// Must not lower to generic shl or sat sqshl.  Amount is
/// signed (negative = right).  srshl/urshl round.  Constant
/// +imm may ISel to shl #n; -imm on srshl to srshr #n.
/// After VMP, amounts are VRegs so llc keeps register form.
/// No last-token.  No ImmediateArguments.
static bool isAArch64NeonScalarVarShiftType(const Type *Ty) {
  if (!Ty || Ty->isVectorTy())
    return false;
  return Ty->isIntegerTy(64);
}

/// Shape-only scalar llvm.aarch64.neon.sshl/ushl/srshl/urshl
/// (AdvSIMD_2IntArg).  Ordinary tail is left to the generic
/// accept.  Vector varshift is independent.
static bool isAArch64NeonScalarVarShiftShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonVarShiftID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 2 ||
      FTy->getNumParams() != 2)
    return false;
  Type *Ty = Call.getType();
  if (!Ty || FTy->getReturnType() != Ty ||
      !isAArch64NeonScalarVarShiftType(Ty))
    return false;
  const Value *A = Call.getArgOperand(0);
  const Value *B = Call.getArgOperand(1);
  if (!A || !B)
    return false;
  if (A->getType() != Ty || B->getType() != Ty ||
      FTy->getParamType(0) != Ty || FTy->getParamType(1) != Ty)
    return false;
  return isSupportedOrdinaryCallOperand(A) &&
         isSupportedOrdinaryCallOperand(B);
}

/// Well-shaped scalar sshl/ushl/srshl/urshl i64.  Baseline
/// HasNEON.  Re-emitted via CallDescriptor / integer VRegs.
/// No ImmediateArguments.  No new opcode.
static bool isSupportedAArch64NeonScalarVarShiftIntrinsic(
    const CallInst &Call) {
  return isAArch64NeonScalarVarShiftShapeSupported(Call);
}

static bool isAArch64NeonSatNarrowShiftID(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_sqshrn:
  case Intrinsic::aarch64_neon_uqshrn:
  case Intrinsic::aarch64_neon_sqrshrn:
  case Intrinsic::aarch64_neon_uqrshrn:
  case Intrinsic::aarch64_neon_sqshrun:
  case Intrinsic::aarch64_neon_sqrshrun:
    return true;
  default:
    return false;
  }
}

/// ISel SIMDVectorRShiftNarrowBHS low-half pairs (baseline HasNEON):
///   v8i8  <- v8i16,  vecshiftR16Narrow imm 1..8
///   v4i16 <- v4i32,  vecshiftR32Narrow imm 1..16
///   v2i32 <- v2i64,  vecshiftR64Narrow imm 1..32
/// High-half sqshrn2 is concat_vectors of a 64-bit dest with one of
/// these calls, not a second IR ID.  Non-saturating rshrn is an
/// independent surface.  Scalar SIMDScalarRShiftBHS i32(i64) is
/// an independent surface.
static bool isAArch64NeonSatNarrowShiftPair(const Type *ResTy,
                                           const Type *ArgTy) {
  const auto *ResVT = dyn_cast<FixedVectorType>(ResTy);
  const auto *ArgVT = dyn_cast<FixedVectorType>(ArgTy);
  if (!ResVT || !ArgVT || !isSupportedFixedVectorType(ResTy) ||
      !isSupportedFixedVectorType(ArgTy))
    return false;
  if (ResVT->getNumElements() != ArgVT->getNumElements())
    return false;
  Type *ResElt = ResVT->getElementType();
  Type *ArgElt = ArgVT->getElementType();
  const unsigned N = ResVT->getNumElements();
  if (ArgElt->isIntegerTy(16) && ResElt->isIntegerTy(8))
    return N == 8;
  if (ArgElt->isIntegerTy(32) && ResElt->isIntegerTy(16))
    return N == 4;
  if (ArgElt->isIntegerTy(64) && ResElt->isIntegerTy(32))
    return N == 2;
  return false;
}

/// ImmLeaf vecshiftR16/32/64Narrow: (uint32_t)Imm > 0 && Imm < 9/17/33.
static bool isAArch64NeonSatNarrowShiftImmInRange(const Type *ResTy,
                                                 const ConstantInt *Imm) {
  if (!Imm || Imm->getBitWidth() != 32 || Imm->isNegative())
    return false;
  const uint64_t V = Imm->getZExtValue();
  const auto *ResVT = dyn_cast<FixedVectorType>(ResTy);
  if (!ResVT)
    return false;
  Type *Elt = ResVT->getElementType();
  if (Elt->isIntegerTy(8))
    return V >= 1 && V <= 8;
  if (Elt->isIntegerTy(16))
    return V >= 1 && V <= 16;
  if (Elt->isIntegerTy(32))
    return V >= 1 && V <= 32;
  return false;
}

/// Exact llvm.aarch64.neon.sqshrn/uqshrn and the in-tree saturating
/// rounding / signed->unsigned narrow siblings (sqrshrn/uqrshrn/
/// sqshrun/sqrshrun).  AdvSIMD_2Arg_Scalar_Narrow: anyint
/// (extended, i32).  ISel SIMDVectorRShiftNarrowBHS, baseline
/// HasNEON, only the three low-half integer pairs above.  The i32
/// shift is not ImmArg but ISel requires vecshiftR*Narrow; it stays
/// on CallDescriptor ImmediateArguments.  rshrn (independent
/// non-saturating surface), dynamic/OOR/zero imm, scalar i32(i64)
/// (independent surface), v4i8, 256-bit, sqshlu, same-width
/// sqshl/sshl, and SVE stay out.
/// C, non-vararg, exact FTy.  CallDescriptor / vector VRegs.
/// No last-token gate.  Ordinary tail is left to the generic accept.
static bool isSupportedAArch64NeonSatNarrowShiftIntrinsic(
    const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonSatNarrowShiftID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 2 ||
      FTy->getNumParams() != 2)
    return false;
  Type *ResultTy = Call.getType();
  if (FTy->getReturnType() != ResultTy)
    return false;
  const Value *Src = Call.getArgOperand(0);
  const Value *Imm = Call.getArgOperand(1);
  if (!isAArch64NeonSatNarrowShiftPair(ResultTy, Src->getType()) ||
      FTy->getParamType(0) != Src->getType() ||
      !isSupportedOrdinaryCallOperand(Src))
    return false;
  if (!Imm->getType()->isIntegerTy(32) ||
      FTy->getParamType(1) != Imm->getType())
    return false;
  const auto *ImmC = dyn_cast<ConstantInt>(Imm);
  if (!ImmC || !isAArch64NeonSatNarrowShiftImmInRange(ResultTy, ImmC))
    return false;
  return isCallImmediateArgument(Call, 1);
}

/// ISel SIMDScalarRShiftBHS for neon.sqshrn/uqshrn/sqrshrn/
/// uqrshrn/sqshrun/sqrshrun: only i32(i64, i32 imm 1..32)
/// (vecshiftR32).  i16(i32) / i8(i16) encodings exist but have
/// empty patterns; clang vqshrns_n_s32 / vqshrnh_n_s16
/// Use64BitVectors.  Clang vqshrnd_n_s64 / vqshrnd_n_u64 /
/// vqrshrnd_n_s64 / vqshrund_n_s64.  Must not lower to
/// scalar.sqxtn or generic lshr+trunc.  sqshrun/sqrshrun are
/// signed->unsigned (negatives saturate to 0).  Amount is not
/// ImmArg; isCallImmediateArgument already keys these IDs.
/// No last-token.  rshrn stays out (independent).
static bool isAArch64NeonScalarSatNarrowShiftPair(const Type *ResTy,
                                                 const Type *ArgTy) {
  if (!ResTy || !ArgTy || ResTy->isVectorTy() || ArgTy->isVectorTy())
    return false;
  return ResTy->isIntegerTy(32) && ArgTy->isIntegerTy(64);
}

static bool isAArch64NeonScalarSatNarrowShiftImmInRange(
    const ConstantInt *Imm) {
  if (!Imm || Imm->getBitWidth() != 32 || Imm->isNegative())
    return false;
  const uint64_t V = Imm->getZExtValue();
  return V >= 1 && V <= 32;
}

/// Shape-only scalar llvm.aarch64.neon.sqshrn family
/// (AdvSIMD_2Arg_Scalar_Narrow: anyint (extended, i32)).
/// Ordinary tail is left to the generic accept.  Vector
/// sat-narrow-shift is independent.
static bool isAArch64NeonScalarSatNarrowShiftShapeSupported(
    const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonSatNarrowShiftID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 2 ||
      FTy->getNumParams() != 2)
    return false;
  Type *ResultTy = Call.getType();
  if (!ResultTy || FTy->getReturnType() != ResultTy)
    return false;
  const Value *Src = Call.getArgOperand(0);
  const Value *Imm = Call.getArgOperand(1);
  if (!Src || !Imm)
    return false;
  if (!isAArch64NeonScalarSatNarrowShiftPair(ResultTy, Src->getType()) ||
      FTy->getParamType(0) != Src->getType() ||
      !isSupportedOrdinaryCallOperand(Src))
    return false;
  if (!Imm->getType()->isIntegerTy(32) ||
      FTy->getParamType(1) != Imm->getType())
    return false;
  const auto *ImmC = dyn_cast<ConstantInt>(Imm);
  if (!ImmC || !isAArch64NeonScalarSatNarrowShiftImmInRange(ImmC))
    return false;
  return isCallImmediateArgument(Call, 1);
}

/// Well-shaped scalar sat-narrow-shift i32(i64, i32 1..32).
/// Baseline HasNEON.  Re-emitted via CallDescriptor / integer
/// VRegs + ImmediateArguments.  No new opcode.
static bool isSupportedAArch64NeonScalarSatNarrowShiftIntrinsic(
    const CallInst &Call) {
  return isAArch64NeonScalarSatNarrowShiftShapeSupported(Call);
}

/// Exact llvm.aarch64.neon.rshrn only (AdvSIMD_2Arg_Scalar_Narrow:
/// anyint (extended, i32)).  The only in-tree non-saturating
/// rounding-narrow IR ID; there is no neon.shrn ID (SHRN is
/// trunc+ashr ISel) and no rshrn2 ID (high-half is concat of this
/// ID).  ISel SIMDVectorRShiftNarrowBHS plus optional RADDHN when
/// the immediate is exactly half the source element width.  Same
/// three low-half pairs and vecshiftR*Narrow ranges as the
/// saturating narrow surface.  The i32 shift is not ImmArg; it
/// stays on CallDescriptor ImmediateArguments.  Saturating
/// sqshrn/uqshrn/sqrshrn/uqrshrn/sqshrun/sqrshrun, dynamic/OOR/
/// zero imm, scalar, v4i8, 256-bit, and SVE rshrnb stay out.  C,
/// non-vararg, exact FTy.  CallDescriptor / vector VRegs.  No
/// last-token gate.  Ordinary tail is left to the generic accept.
static bool isSupportedAArch64NeonRshrnIntrinsic(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::aarch64_neon_rshrn)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 2 ||
      FTy->getNumParams() != 2)
    return false;
  Type *ResultTy = Call.getType();
  if (FTy->getReturnType() != ResultTy)
    return false;
  const Value *Src = Call.getArgOperand(0);
  const Value *Imm = Call.getArgOperand(1);
  if (!isAArch64NeonSatNarrowShiftPair(ResultTy, Src->getType()) ||
      FTy->getParamType(0) != Src->getType() ||
      !isSupportedOrdinaryCallOperand(Src))
    return false;
  if (!Imm->getType()->isIntegerTy(32) ||
      FTy->getParamType(1) != Imm->getType())
    return false;
  const auto *ImmC = dyn_cast<ConstantInt>(Imm);
  if (!ImmC || !isAArch64NeonSatNarrowShiftImmInRange(ResultTy, ImmC))
    return false;
  return isCallImmediateArgument(Call, 1);
}

static bool isAArch64NeonWideningShiftID(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_shll:
  case Intrinsic::aarch64_neon_sshll:
  case Intrinsic::aarch64_neon_ushll:
    return true;
  default:
    return false;
  }
}

/// Low-half widening-left-shift pairs only (SIMDVectorLShiftLong):
///   v8i16 <- v8i8    shll #8;  sshll/ushll vecshiftL8  0..7
///   v4i32 <- v4i16   shll #16; sshll/ushll vecshiftL16 0..15
///   v2i64 <- v2i32   shll #32; sshll/ushll vecshiftL32 0..31
/// Wide v16i8 / v8i16 / v4i32 sources are shll2/sshll2/ushll2
/// extract_high + the same low-half ID, not a direct form.
static bool isAArch64NeonWideningShiftPair(const Type *ResTy,
                                          const Type *SrcTy) {
  const auto *Res = dyn_cast<FixedVectorType>(ResTy);
  const auto *Src = dyn_cast<FixedVectorType>(SrcTy);
  if (!Res || !Src || !isSupportedFixedVectorType(ResTy) ||
      !isSupportedFixedVectorType(SrcTy))
    return false;
  Type *ResElt = Res->getElementType();
  Type *SrcElt = Src->getElementType();
  if (!ResElt->isIntegerTy() || !SrcElt->isIntegerTy())
    return false;
  if (Res->getNumElements() != Src->getNumElements())
    return false;
  const unsigned Lanes = Res->getNumElements();
  const unsigned ResBits = ResElt->getIntegerBitWidth();
  const unsigned SrcBits = SrcElt->getIntegerBitWidth();
  if (ResBits != SrcBits * 2)
    return false;
  return (Lanes == 8 && SrcBits == 8) || (Lanes == 4 && SrcBits == 16) ||
         (Lanes == 2 && SrcBits == 32);
}

static bool isAArch64NeonWideningShiftImmInRange(const Type *SrcTy,
                                                const ConstantInt *Imm) {
  if (!Imm || Imm->getBitWidth() != 32 || Imm->isNegative())
    return false;
  const auto *Src = dyn_cast<FixedVectorType>(SrcTy);
  if (!Src || !Src->getElementType()->isIntegerTy())
    return false;
  return Imm->getZExtValue() < Src->getElementType()->getIntegerBitWidth();
}

/// Shape-only llvm.aarch64.neon.shll / sshll / ushll.
/// shll is AdvSIMD_2VectorArg_Scalar_Wide_BySize (no imm; shift is
/// the source element width).  sshll/ushll are
/// AdvSIMD_2VectorArg_Scalar_Wide (i32 shift, not ImmArg).
/// ISel ImmLeaf is vecshiftL* so the i32 must stay a true
/// ConstantInt on ImmediateArguments.  Must not lower to
/// sext/zext + shl.  High-half / wide source / scalable / SVE
/// stay out.  Ordinary tail is left to the generic accept.
/// No last-token gate (baseline HasNEON).
static bool isAArch64NeonWideningShiftShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonWideningShiftID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg())
    return false;
  Type *ResTy = Call.getType();
  if (!ResTy || FTy->getReturnType() != ResTy)
    return false;

  const Intrinsic::ID ID = II->getIntrinsicID();
  if (ID == Intrinsic::aarch64_neon_shll) {
    if (Call.arg_size() != 1 || FTy->getNumParams() != 1)
      return false;
    const Value *Src = Call.getArgOperand(0);
    if (!Src || !isAArch64NeonWideningShiftPair(ResTy, Src->getType()) ||
        FTy->getParamType(0) != Src->getType())
      return false;
    return isSupportedOrdinaryCallOperand(Src);
  }

  if (Call.arg_size() != 2 || FTy->getNumParams() != 2)
    return false;
  const Value *Src = Call.getArgOperand(0);
  const Value *Imm = Call.getArgOperand(1);
  if (!Src || !Imm)
    return false;
  if (!isAArch64NeonWideningShiftPair(ResTy, Src->getType()) ||
      FTy->getParamType(0) != Src->getType() ||
      !isSupportedOrdinaryCallOperand(Src))
    return false;
  if (!Imm->getType()->isIntegerTy(32) ||
      FTy->getParamType(1) != Imm->getType())
    return false;
  const auto *ImmC = dyn_cast<ConstantInt>(Imm);
  if (!ImmC || !isAArch64NeonWideningShiftImmInRange(Src->getType(), ImmC))
    return false;
  return isCallImmediateArgument(Call, 1);
}

/// Well-shaped low-half shll / sshll / ushll.  Re-emitted via
/// CallDescriptor / vector VRegs; sshll/ushll immediates stay on
/// ImmediateArguments.  No new opcode.  Not rewritten to
/// sext/zext + shl.
static bool isSupportedAArch64NeonWideningShiftIntrinsic(
    const CallInst &Call) {
  return isAArch64NeonWideningShiftShapeSupported(Call);
}

static bool isAArch64NeonShiftInsertID(Intrinsic::ID ID) {
  return ID == Intrinsic::aarch64_neon_vsli ||
         ID == Intrinsic::aarch64_neon_vsri;
}

/// vecshiftL*: Imm < EltBits (0..EltBits-1).
/// vecshiftR*: Imm > 0 && Imm < EltBits+1 (1..EltBits).
static bool isAArch64NeonShiftInsertImmInRange(Intrinsic::ID ID,
                                              const Type *VecTy,
                                              const ConstantInt *Imm) {
  if (!Imm || Imm->getBitWidth() != 32 || Imm->isNegative())
    return false;
  const auto *VT = dyn_cast<FixedVectorType>(VecTy);
  if (!VT)
    return false;
  const uint64_t V = Imm->getZExtValue();
  const unsigned EltBits = VT->getElementType()->getIntegerBitWidth();
  if (ID == Intrinsic::aarch64_neon_vsli)
    return V < EltBits;
  if (ID == Intrinsic::aarch64_neon_vsri)
    return V >= 1 && V <= EltBits;
  return false;
}

/// Exact llvm.aarch64.neon.vsli / vsri
/// (AdvSIMD_3VectorArg_Scalar: anyvector (match, match, i32)).
/// Clang vsli_n / vsri_n are WInst builtins that emit these IDs,
/// not generic shl/lshr/or.  ISel lowers them to AArch64ISD::VSLI /
/// VSRI then SIMDVectorL/RShiftBHSDTied (baseline HasNEON):
/// v8i8/v16i8/v4i16/v8i16/v2i32/v4i32/v2i64.  v1i64 is the scalar
/// SLId/SRId form and stays out.  The i32 shift is not ImmArg;
/// vsli uses vecshiftL (0..EltBits-1), vsri uses vecshiftR
/// (1..EltBits); it stays on CallDescriptor ImmediateArguments.
/// Generic or+shift that ISel may fold to SLI is already the
/// ordinary integer-vector surface.  SVE sli/sri, dynamic/OOR
/// imm, float/half/bfloat, and non-C stay out.  C, non-vararg,
/// exact FTy.  CallDescriptor / vector VRegs.  No last-token gate.
/// Ordinary tail is left to the generic accept.
static bool isSupportedAArch64NeonShiftInsertIntrinsic(
    const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonShiftInsertID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 3 ||
      FTy->getNumParams() != 3)
    return false;
  Type *ResultTy = Call.getType();
  if (!isAArch64NeonSatIntVectorType(ResultTy) ||
      FTy->getReturnType() != ResultTy)
    return false;
  for (unsigned I = 0; I < 2; ++I) {
    const Value *Arg = Call.getArgOperand(I);
    if (Arg->getType() != ResultTy || FTy->getParamType(I) != ResultTy ||
        !isSupportedOrdinaryCallOperand(Arg))
      return false;
  }
  const Value *Imm = Call.getArgOperand(2);
  if (!Imm->getType()->isIntegerTy(32) ||
      FTy->getParamType(2) != Imm->getType())
    return false;
  const auto *ImmC = dyn_cast<ConstantInt>(Imm);
  if (!ImmC ||
      !isAArch64NeonShiftInsertImmInRange(II->getIntrinsicID(), ResultTy,
                                         ImmC))
    return false;
  return isCallImmediateArgument(Call, 2);
}

static bool isAArch64NeonSatNarrowID(Intrinsic::ID ID) {
  switch (ID) {
  case Intrinsic::aarch64_neon_sqxtn:
  case Intrinsic::aarch64_neon_uqxtn:
  case Intrinsic::aarch64_neon_sqxtun:
    return true;
  default:
    return false;
  }
}

/// Exact llvm.aarch64.neon.sqxtn / uqxtn / sqxtun
/// (AdvSIMD_1VectorArg_Narrow: anyint (extended)).  Signedness is
/// the ID: sqxtn signed->signed, uqxtn unsigned->unsigned,
/// sqxtun signed->unsigned.  ISel SIMDMixedTwoVector, baseline
/// HasNEON, same three low-half pairs as saturating/rounding
/// narrow shift: v8i8<-v8i16, v4i16<-v4i32, v2i32<-v2i64.
/// High-half sqxtn2 is concat_vectors of this ID, not a second
/// IR ID.  Scalar scalar_sqxtn/uqxtn/sqxtun is an independent
/// surface.  Non-saturating XTN (trunc ISel) and SVE sqxtnb/t
/// stay out.  C, non-vararg, exact FTy.  CallDescriptor /
/// vector VRegs.  No last-token gate and no ImmediateArguments.
/// Ordinary tail is left to the generic accept.
static bool isSupportedAArch64NeonSatNarrowIntrinsic(
    const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonSatNarrowID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 1 ||
      FTy->getNumParams() != 1)
    return false;
  Type *ResultTy = Call.getType();
  if (FTy->getReturnType() != ResultTy)
    return false;
  const Value *Src = Call.getArgOperand(0);
  if (!isAArch64NeonSatNarrowShiftPair(ResultTy, Src->getType()) ||
      FTy->getParamType(0) != Src->getType() ||
      !isSupportedOrdinaryCallOperand(Src))
    return false;
  return true;
}

static bool isAArch64NeonScalarSatNarrowID(Intrinsic::ID ID) {
  return ID == Intrinsic::aarch64_neon_scalar_sqxtn ||
         ID == Intrinsic::aarch64_neon_scalar_uqxtn ||
         ID == Intrinsic::aarch64_neon_scalar_sqxtun;
}

/// ISel SIMDTwoScalarMixedBHS matches only i32(i64) for
/// scalar_sqxtn / scalar_uqxtn / scalar_sqxtun.  i16(i32) and
/// i8(i16) encodings exist with empty patterns.  Clang
/// vqmovnd_s64 / vqmovnd_u64 / vqmovund_s64.  h/s forms use
/// vector sqxtn, not these IDs.
static bool isAArch64NeonScalarSatNarrowPair(const Type *ResTy,
                                            const Type *ArgTy) {
  return ResTy && ArgTy && ResTy->isIntegerTy(32) && ArgTy->isIntegerTy(64);
}

/// Exact llvm.aarch64.neon.scalar.sqxtn / uqxtn / sqxtun
/// (AdvSIMD_1IntArg_Narrow: anyint (anyint)).  Signedness is the
/// ID.  Only the ISel pair i32(i64).  Must not rewrite to trunc
/// or vector sqxtn.  Vector sqxtn is an independent surface.
/// SVE stays out.  C, non-vararg, exact FTy.  CallDescriptor /
/// integer VRegs.  No last-token gate and no ImmediateArguments.
/// Ordinary tail is left to the generic accept.
static bool isSupportedAArch64NeonScalarSatNarrowIntrinsic(
    const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || !isAArch64NeonScalarSatNarrowID(II->getIntrinsicID()))
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 1 ||
      FTy->getNumParams() != 1)
    return false;
  Type *ResultTy = Call.getType();
  if (!ResultTy || FTy->getReturnType() != ResultTy)
    return false;
  const Value *Src = Call.getArgOperand(0);
  if (!Src || !isAArch64NeonScalarSatNarrowPair(ResultTy, Src->getType()) ||
      FTy->getParamType(0) != Src->getType() ||
      !isSupportedOrdinaryCallOperand(Src))
    return false;
  return true;
}

/// ISel SIMDThreeSameVectorFP for neon.fmulx (HasNEON):
/// v2f32 / v4f32 / v2f64, plus HasFullFP16 for v4f16 / v8f16.
/// Scalar SIMDFPThreeScalar (HasNEONorSME): f32 / f64, plus
/// HasFullFP16 for half.  Clang vmulxs_f32 / vmulxd_f64 /
/// vmulxh_f16.  v1f64 / v2f16 / bfloat stay out.
static bool isAArch64NeonFMulXType(const Type *Ty) {
  if (!Ty)
    return false;
  if (!Ty->isVectorTy())
    return Ty->isHalfTy() || Ty->isFloatTy() || Ty->isDoubleTy();
  const auto *FixedTy = dyn_cast<FixedVectorType>(Ty);
  if (!FixedTy || !isSupportedFixedVectorType(Ty))
    return false;
  Type *Elt = FixedTy->getElementType();
  const unsigned N = FixedTy->getNumElements();
  if (Elt->isHalfTy())
    return N == 4 || N == 8;
  if (Elt->isFloatTy())
    return N == 2 || N == 4;
  return Elt->isDoubleTy() && N == 2;
}

/// Shape-only llvm.aarch64.neon.fmulx (AdvSIMD_2FloatArg:
/// anyfloat (match, match), Commutative).  No fmulx.lane IR ID;
/// clang vmulx_lane is splat + this ID; scalar lane is extract
/// + this ID.  Must not lower to fmul (NaN/Inf special cases
/// differ).  v1f64 / bfloat / vcmla / SVE stay generic.  Shape
/// does not check +fullfp16 so a missing/final-disabled half
/// token stays "unsupported target feature".  Ordinary tail is
/// left to the generic accept.
static bool isAArch64NeonFMulXShapeSupported(const CallInst &Call) {
  const auto *II = dyn_cast<IntrinsicInst>(&Call);
  if (!II || II->getIntrinsicID() != Intrinsic::aarch64_neon_fmulx)
    return false;
  if (Call.isMustTailCall() || Call.hasOperandBundles() ||
      Call.doesNotReturn() || Call.canReturnTwice() ||
      hasUnsupportedCallABIAttributes(Call))
    return false;
  if (Call.getCallingConv() != CallingConv::C)
    return false;
  FunctionType *FTy = Call.getFunctionType();
  if (!FTy || FTy->isVarArg() || Call.arg_size() != 2 ||
      FTy->getNumParams() != 2)
    return false;
  Type *Ty = Call.getType();
  if (!Ty || FTy->getReturnType() != Ty || !isAArch64NeonFMulXType(Ty))
    return false;
  const Value *A = Call.getArgOperand(0);
  const Value *B = Call.getArgOperand(1);
  if (!A || !B)
    return false;
  if (A->getType() != Ty || B->getType() != Ty ||
      FTy->getParamType(0) != Ty || FTy->getParamType(1) != Ty)
    return false;
  return isSupportedOrdinaryCallOperand(A) &&
         isSupportedOrdinaryCallOperand(B);
}

/// Well-shaped neon.fmulx.  Half (scalar or vector) needs
/// last-token +fullfp16 (HasFullFP16).  f32/f64 are baseline
/// HasNEON and need no extra token.  Command-line -mattr is
/// never consulted.  +fp16fml / +complxnum do not count as
/// +fullfp16.  Re-emitted via CallDescriptor / vector or scalar
/// float VRegs.  No ImmediateArguments.  No new opcode.
static bool isSupportedAArch64NeonFMulXIntrinsic(const CallInst &Call) {
  if (!isAArch64NeonFMulXShapeSupported(Call))
    return false;
  if (!Call.getType()->getScalarType()->isHalfTy())
    return true;
  const Function *Parent = Call.getFunction();
  return Parent && functionHasExplicitFullFP16Enabled(*Parent);
}

