        Type *DstTy = Cast->getType();
        if (isSupportedScalarFPFrameType(SrcTy) &&
            DstTy->isIntegerTy(getScalarFPBitWidth(SrcTy)) &&
            isSupportedOperand(Cast->getOperand(0)))
          return true;
        if (isSupportedScalarFPFrameType(DstTy) &&
            SrcTy->isIntegerTy(getScalarFPBitWidth(DstTy)) &&
            isSupportedOperand(Cast->getOperand(0)))
          return true;
