      if (isSupportedFlatAggregateType(Select->getType())) {
        if (!isSupportedFlatAggregateSelect(*Select))
          return "unsupported aggregate instruction";
        continue;
      }
      if (Select->getType()->isAggregateType())
        return "unsupported aggregate instruction";
