          return "unsupported readcyclecounter";
        if (II->getIntrinsicID() == Intrinsic::flt_rounds)
          return "unsupported flt.rounds";
        if (II->getIntrinsicID() == Intrinsic::set_rounding)
          return "unsupported set.rounding";
