            Builder.CreateBitCast(FalseValue, I16Vec, "vmp.vbf.sel.f");
        Value *Bits =
            Builder.CreateSelect(Condition, TBits, FBits, "vmp.vbf.sel");
        Result = Builder.CreateBitCast(Bits, VecTy, "vmp.vbf.sel.bf");
