        if (Kind == FreezeSrcUndef)
          return UndefValue::get(Descriptor.SrcTy);
        if (Kind == FreezeSrcPoison)
          return PoisonValue::get(Descriptor.SrcTy);
        return vectorFromSlot(
            Builder, loadVectorSource(Builder, CurrentPC, Field),
            Descriptor.SrcTy);
