        Value *Op0i = Builder.CreateBitCast(Op0, I16Src, "vmp.vbf.shuf.a");
        Value *Op1i = Builder.CreateBitCast(Op1, I16Src, "vmp.vbf.shuf.b");
        Value *Shuf = Builder.CreateShuffleVector(Op0i, Op1i, Descriptor.Mask,
                                                  "vmp.vbf.shuf");
